(window.GIM_TS=window.GIM_TS||{})["Eruvin.6"]={"from":144,"a":[["\u0003עד שיהו בתים וחצירות\u0004 משמע חצירות — שתים (מיעוט רבים) לפחות, ומשמע בתים — שני בתים לפחות לכל חצר, \u0003פתוחין לתוכו,\u0004 ואם לא נתקיימו תנאים אלה אין זה מבוי שאפשר להתירו בלחי וקורה. \u0003ושמואל אמר: אפילו בית אחד\u0004 בלא חצר \u0003וחצר\u0004 שבית פתוח לתוכה \u0003אחת\u0004 במבוי אפשר להתירו. \u0003ור' יוחנן אמר אפילו\u0004 אינו אלא \u0003חורבה\u0004 יש למבוי זה היתר על ידי לחי וקורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 האם \u0003אמר ר' יוחנן\u0004 בהיתר מבוי \u0003אפילו בשביל של כרמים?\u0004 שאם היו במבוי בית ושביל כרמים שראשו האחד פונה לחצר והשני למבוי האם דיים כדי לעשות שיתוף במבוי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא אמר ר' יוחנן אלא בחורבה, דחזי\u0004 \u0005[שראויה]\u0006 \u0003לדירה, אבל שביל של כרמים דלא חזי\u0004 \u0005[שאינו ראוי]\u0006 \u0003לדירה — לא.\u0004","\u0003אמר רב הונא בר חיננא: ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לשיטתו]\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003אמר ר' שמעון: אחד\u0004 (גם) \u0003גגות ואחד קרפיפות ואחד חצירות — רשות אחת הן לכלים ששבתו לתוכן.\u0004 ומותר לטלטל בין אלה כלים שנשארו בשבת, אבל \u0003לא\u0004 נחשבו רשות אחת \u0003לכלים ששבתו בתוך הבית\u0004 שכלים שהיו בבית אין להוציאם לחצר אחרת בלא עירוב.","\u0003ואמר רב: הלכה כר' שמעון, והוא שלא עירבו\u0004 בני החצירות כל חצר לעצמה שאז יטלטלו רק את הכלים שבחצירות \u0003עצמן אבל עירבו גזרינן\u0004 \u0005[גוזרים אנו]\u0006 ואוסרים אף בכלים ששבתו בחצר \u0003דילמא אתי לאפוקי מאני\u0004 \u0005[שמא יבוא להוציא דברים]\u0006 של ה\u0003בתים לחצר\u0004 ויטעה ויטלטל אף כלים אלה מחצר לחצר שלא כדין.","\u0003ושמואל אמר: בין עירבו ובין לא עירבו\u0004 מותר. \u0003וכן אמר ר' יוחנן: הלכה כר' שמעון, בין עירבו ובין לא עירבו. אלמא: לא גזרינן דילמא אתי לאפוקי מאני\u0004 \u0005[מכאן\u0006 ש\u0005אין אנו גוזרים שמא יבוא להוציא דברים]\u0006 של ה\u0003בתים לחצר\u0004 לדעת ר' יוחנן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין היתר במבוי שיש בו חורבה \u0003לא גזרינן דילמא אתי לאפוקי מאני\u0004 \u0005[אין אנו גוזרים שמא יבואו להוציא את חפצי]\u0006 \u0003חצר לחורבה\u0004 דרך המבוי, שאף על פי שהחורבה כיון שאין בה דיורים אינה נכללת בתוך העירוב ואין בה היתר טלטול, מכל מקום ר' יוחנן אינו חושש לאפשרות טלטול אסור זה.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב ברונא וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 שלדעת שמואל מבוי שיש בו בית אחד וחצר אחת אפשר להתירו בלחי וקורה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר בר בי\u0004 \u0005[בן בית\u0006 מדרשו\u0005]\u0006 של \u0003רב: אמר שמואל הכי\u0004 \u0005[כך]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אחוי\u0004 \u0005[הראה]\u0006 \u0003לי\u0004 את מקום \u0003אושפיזיה\u0004 \u0005[דירתו]\u0006 ואלך ואשאלנו, \u0003אחוי ליה\u0004 \u0005[הראה לו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003שמואל, אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003אמר מר הכי\u0004 \u0005[ אדוני כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","הקשה לו ר' אלעזר: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 בענין אחר, \u0003אין לנו בעירובין אלא כלשון משנתינו, שהמבוי לחצירות כחצר לבתים,\u0004 ואם כן לפי לשון משנתינו כדיוקה יש צורך בשתי חצירות ושני בתים. \u0003אישתיק\u0004 \u0005[שתק]\u0006 שמואל ולא ענה לו.","ושואלים: האם לאחר ששתק שמואל ולא נתן תשובה לסתירה זו, \u0003קבלה מיניה\u0004 \u0005[קבל אותה ממנו]\u0006 הסכים לה לקושיה, וחזר בו \u0003או לא קבלה מיניה\u0004 \u0005[ממנו].\u0006 ומנסים להביא ראיה ממעשה שהיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דההוא מבואה דהוה דייר ביה\u0004 \u0005[אותו מבוי שהיה גר בו]\u0006 \u0003איבות בר איהי\u0004 בחצר לבדו \u0003עבד ליה לחייא, ושרא ליה\u0004 \u0005[עשה לו\u0006 למבוי \u0005לחי, והתיר לו]\u0006 \u0003שמואל\u0004 לטלטל בו,"],["\u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב ענן\u0004 לאחר מות שמואל \u0003שדיה\u0004 \u0005[והשליכו,\u0006 את הלחי\u0005]\u0006 כדי שיידע איבות בר איהי שאין מבוי זה מותר בטלטול שאין תקון זה בלחי מועיל אלא למבוי שיש בו שתי חצירות ושני בתים. \u0003אמר\u0004 איבות בר איהי בהתמרמרות: \u0003מבואה דדיירנא ביה ואתינא משמיה\u0004 \u0005[\u0006האם \u0005מבוי שהייתי דר והולך בו משמו]\u0006 של \u0003מר שמואל, ניתי\u0004 \u0005[יבוא]\u0006 \u0003רב ענן בר רב נישדייה מן\u0004 \u0005[\u0006ו\u0005ישליכנו ממני]?!\u0006 ואם כן, מן העובדה שלחי זה היה קיים כל ימי שמואל \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לא קיבלה מיניה\u0004 \u0005[קבל\u0006 שמואל \u0005ממנו]\u0006 קושיה זו, שהרי התיר ליחיד הדר במבוי לעשות בו תיקון.","ודוחים: אין להביא מכאן ראיה גמורה, \u0003לעולם אימא\u0004 \u0005[\u0006אפשר \u0005לומר]\u0006 \u0003לך\u0004 ש\u0003קיבלה מינה\u0004 \u0005[ממנו]\u0006 וחזר בו מדבריו, ובמבוי זה היה מקרה מיוחד \u0003הכא חזנא הוא דהוה אכיל נהמא בביתיה ואתי ביית בבי כנישתא\u0004 \u0005[כאן\u0006 במבוי זה היה גם \u0005שמש\u0006 בית הכנסת \u0005שהיה אוכל לחם בביתו\u0006 במקום אחר \u0005ובא ולן בבית הכנסת]\u0006 שהיה פתוח למבוי זה.","\u0003ואיבות בר איהי סבר: מקום פיתא גרים\u0004 \u0005[הפת הוא שגורם]\u0006 ועל פיו נקבע עיקר מקום שביתה, ולכן אין בית הכנסת נחשב כדירה שהרי אוכל השמש במקום אחר, וסבר שהתיר לו שמואל מטעם כלשהו לעשות תיקון למבואו אף שהוא דר בו ביחידות, אולם לפי האמת לא כך היה. \u0003ושמואל לטעמיה\u0004 \u0005[לשיטתו]\u0006 ש\u0003אמר: מקום לינה גרים\u0004 \u0005[גורם]\u0006 וכיון שהשמש לן בבית הכנסת שבמבוי זה הרי שם שני בתים וחצירות, ואפשר להתיר את המבוי בלחי וקורה מטעם זה.","\u0003אמר ר' יהודה אמר רב: מבוי שצידו אחד גוי וצידו אחד\u0004 כמה בתי \u0003ישראל\u0004 הפתוחים לרשות הרבים — \u0003אין מערבין אותו דרך חלונות\u0004 שבין בית לבית בצדו האחד כדי \u0003להתירו\u0004 (את בתי ישראל) לטלטל \u0003דרך פתחים\u0004 של הבית הסמוך \u0003למבוי,\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: אמר רב\u0004 בענין זה \u0003אפילו בחצר\u0004 שדרים בה ישראל וגוי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 \u0003דאי\u0004 \u0005שאם]\u0006 אפילו \u0003לא אמר מאי\u0004 \u0005[מה]\u0006 היה ההבדל? הלא עקרון אחד הוא!","אמר לו: \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003רב משום דקסבר\u0004 \u0005[שסבר]:\u0006 \u0003אין מבוי ניתר בלחי וקורה עד שיהו בתים וחצירות פתוחין לתוכו,\u0004 וביתו של הגוי אינו נחשב כבית לענין זה, ולכן לא התיר רב.","אמר לו רב יוסף: אם זהו הטעם, \u0003תרתי\u0004 \u0005[שתים,\u0006 שתי הלכות באותו ענין\u0005]\u0006 \u0003למה לי,\u0004 הלוא כבר אמר רב שאין מבוי ניתר אלא כשבתים וחצירות פתוחים לתוכו! השיב לו: \u0003צריכא\u0004 \u0005[צריך]\u0006 לומר שניהם \u0003דאי מההיא\u0004 \u0005[שאם מ\u0006ההלכה \u0005ההיא]\u0006 לענין בתים וחצירות בכלל,"],["\u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003דירת גוי שמה דירה\u0004 לענין החשבתו של המבוי. \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003דירת גוי לא שמה\u0004 \u0005[אינה נחשבת]\u0006 \u0003דירה ואי מהכא — הוה אמינא\u0004 \u0005[ואם מכאן\u0006 בלבד\u0005, הייתי אומר]:\u0006 \u0003לא ידענא\u0004 \u0005[אין אני יודע]\u0006 \u0003בתים כמה\u0004 הם, \u0003קא משמע לן\u0004 \u0005[הרי הוא משמיע לנו]\u0006 \u0003בתים תרין\u0004 \u0005[שנים]\u0006","\u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר רב אפילו חצר,\u0004 משמע \u0003טעמא\u0004 \u0005[טעמו]\u0006 \u0003של רב דקא סבר\u0004 \u0005[שסבר]:\u0006 \u0003אסור לעשות\u0004 שיהא \u0003יחיד\u0004 דר \u0003במקום גוי\u0004 ולכן אין מסייעים לו לערב, כדי שיכבד עליו להיות שם ויעקור דירתו.","\u0003אמר רב יוסף: אי הכי היינו דשמענא ליה\u0004 \u0005[אם כן\u0006 לפי פירוש זה \u0005זהו ששמעתי]\u0006 \u0003לר' טבלא\u0004 ש\u0003אמר: \"גוי גוי\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 שתי הלכות, \u0003ולא ידענא מאי אמר\u0004 \u0005[ולא ידעתי, אז מה אמר],\u0006 וכעת מבין אני שאמר פעם לענין מבוי שבצידו אחד גוי, ופעם אחרת לענין חצר שיש בה גוי.","\u0003שתי חצירות\u0004 שהיו \u0003זו לפנים מזו\u0004 והחיצונה פתוחה לרשות הרבים, \u0003עירבה הפנימית\u0004 לעצמה \u0003ולא עירבה החיצונה — הפנימית מותרת והחיצונה אסורה.\u0004","עירבה \u0003החיצונה ולא הפנימית — שתיהן אסורות\u0004 שהרי בני הפנימית עוברים דרך החצר החיצונה והריהם במדת מה כבני חצר שלא עירבו. \u0003עירבה זו לעצמה וזו לעצמה\u0004 ולא עירבו אלו עם אלו — \u0003זו מותרת בפני עצמה וזו מותרת בפני עצמה\u0004 אבל לא לטלטל מזו לזו.","\u0003ר' עקיבא אוסר\u0004 אף במקרה זה את \u0003החיצונה שדריסת הרגל\u0004 של בני החצר הפנימית \u0003אוסרתה\u0004 שהרי בני פנימית אסור להם לטלטל בחיצונה. \u0003וחכמים אומרים: אין דריסת הרגל אוסרתה\u0004 שכיון שאין בני החצר הפנימית משתמשים בחצר החיצונה, ובחצרם שלהם מותרים הם — אינם אוסרים בחצר אחרת.","\u0003שכח אחד מן החיצונה ולא עירב — הפנימית מותרת והחיצונה אסורה.\u0004 שכח אחד \u0003מהפנימית ולא עירב — שתיהן אסורות.\u0004 שהרי מתוך שהפנימית אסורה, הרי שדריסת רגלה אוסרת אף את החיצונה.","\u0003נתנו עירובן במקום אחד ושכח אחד בין מהפנימית בין מן החיצונה ולא עירב — שתיהן אסורות\u0004 שהרי הן כחצר אחת. \u0003ואם היו\u0004 החצירות \u0003של יחידים\u0004 שבכל חצר רק אדם אחד — \u0003אינן צריכין לערב\u0004 ביניהן שלא אמרו דין עירוב אלא ברבים הגרים בחצר.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר ר' ינאי:\u0004 משנתנו האומרת שאם עירבה החיצונה ולא הפנימית שתיהן אסורות הרי \u0003זו דברי ר' עקיבא,\u0004 ש\u0003אמר: אפילו רגל המותרת במקומה\u0004 אפילו אדם הבא מחצר שבה מותר לו לטלטל — \u0003אוסרת שלא במקומה,\u0004 אם רגיל הוא לעבור בחצר אחרת ואשר בה נעשה כבן החצר אוסר אף אותה בטלטול. \u0003אבל חכמים אומרים: כשם שרגל המותרת\u0004 במקומה \u0003אינה אוסרת\u0004 בחצר אחרת — \u0003כך\u0004 אפילו \u0003רגל האסורה\u0004 במקומה \u0003אינה אוסרת\u0004 ומשום כך גם אם לא עירבה החצר הפנימית ועירבה חיצונה בלבד, אין החיצונה נאסרת משום דריסת רגלי בני החצר הפנימית.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"עירבה חיצונה ולא פנימית — שתיהן אסורות\". מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' עקיבא — מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דוקא\u0005]\u0006 שנה מקרה של \u0003רגל אסורה?\u0004 כאשר לא עירבה פנימית, והלא לשיטתו במשנה בדין עירבה זו לעצמה וזו לעצמה \u0003אפילו רגל מותרת נמי\u0004 \u0005[גם כן]\u0006 אוסרת, ואף אם היתה הפנימית מערבת לעצמה היתה אוסרת את החיצונה. \u0003אלא לאו רבנן\u0004 \u0005[\u0006האם \u0005לא\u0006 כדברי \u0005חכמים]\u0006 ומשמע שחכמים סבורים בכל זאת כי רגל האסורה במקומה אוסרת שלא במקומה. ובניגוד לדברי ר' ינאי!","ודוחים: \u0003לעולם\u0004 דברים אלה כשיטת \u0003ר' עקיבא\u0004 אלא משנתנו בסגנון \u0003\"לא זו אף זו\" קתני\u0004 \u0005[שנויה]\u0006 שהוא הולך מן הפשוט והקל אל מקרה מסובך יותר, וכך יש להבינה: לא רק אם עירבה החיצונה ולא הפנימית אסורות אלא גם אם עירבו כל אחת לעצמה עדיין החיצונה אסורה.","ועוד שואלים ומבררים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עירבה זו לעצמה וזו לעצמה זו מותרת בפני עצמה וזו מותרת בפני עצמה. טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 ש\u0003עירבה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא עירבה שתיהן אסורות,\u0004","\u0003והא האי תנא\u0004 \u0005[והרי תנא זה]\u0006 נראה ש\u0003אמר\u0004 (שהוא סובר) \u0003רגל המותרת אינה אוסרת, רגל האסורה אוסרת, מני הא\u0004 \u0005[\u0006כשיטת \u0005מי היא זו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' עקיבא היא — אפילו רגל המותרת נמי\u0004 \u0005[גם כן]\u0006 אוסרת, \u0003אלא לאו רבנן\u0004 \u0005[האם לא\u0006 כשיטת \u0005חכמים]\u0006 \u0003היא.\u0004 ומשמע שחכמים סבורים כי רגל האסורה במקומה — אוסרת. \u0003ועוד\u0004 ראיה \u0003מדסיפא\u0004 \u0005[אם סופה]\u0006 כשיטת \u0003ר' עקיבא רישא לאו\u0004 \u0005[\u0006משמע \u0005שראשה איננו]\u0006 כשיטת \u0003ר' עקיבא.\u0004","את הקושיה הזו דוחים: כל המשנה \u0003כולה\u0004 שיטת \u0003ר' עקיבא היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003עירבה זו לעצמה וזו לעצמה — זו מותרת בפני עצמה וזו מותרת בפני עצמה. במה דברים אמורים\u0004 שכל אחת מותרת לעצמה — \u0003שעשתה\u0004 פנימית \u0003דקה\u0004 (מעין מחיצה לפתחה), \u0003אבל לא עשתה דקה — חיצונה אסורה,\u0004 כ\u0003דברי ר' עקיבא, שר' עקיבא אוסר את החיצונה, מפני שדריסת הרגל אוסרת\u0004 בכל מקרה. \u0003וחכמים אומרים: אין דריסת הרגל אוסרת.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ביבי בר אביי\u0004 שנינו במשנתנו: \u0003ואם היו\u0004 חצירות אלו כל אחת \u0003של יחידים — אין צריכין לערב\u0004 ונדייק \u0003הא\u0004 \u0005[הרי]\u0006 אם היו חצירות אלו \u0003של רבים צריכין לערב\u0004 בכל חצר לחוד, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003רגל המותרת במקומה — אינה אוסרת, רגל האסורה — אוסרת,\u0004 ובנגוד לדברי ר' ינאי בדעת ר' עקיבא!","\u0003ועוד מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבינא\u0004 ממשנתנו \u0003\"שכח אחד מן החיצונה ולא עירב — הפנימית מותרת, וחיצונה אסורה. שכח אחד מהפנימית ולא עירב — שתיהן אסורות\". טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 ש\u0003שכח הא\u0004 \u0005[הרי]\u0006 אם \u0003לא שכח\u0004 ועירבה כל חצר לעצמה \u0003שתיהן מותרות. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003רגל המותרת — אינה אוסרת, רגל האסורה — אוסרת\u0004 ודברים אלו ודאי אינם דעת ר' עקיבא שהרי לדבריו אף רגל מותרת אוסרת, אלא ודאי הוא מדברי חכמים, הרי שאף חכמים סבורים שרגל האסורה במקומה אוסרת בחצר אחרת.","\u0003אלא\u0004 אין אפשרות להחזיק בגרסה זו \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מסר גרסה מתוקנת לפיה \u0003אמר ר' ינאי: שלש מחלוקות בדבר: תנא קמא סבר: רגל המותרת — אינה אוסרת, רגל האסורה — אוסרת. ר' עקיבא סבר: אפילו רגל המותרת אוסרת. ורבנן בתראי סברי\u0004 \u0005[וחכמים אחרונים סבורים]:\u0006 \u0003כשם שרגל מותרת אינה אוסרת — כך רגל האסורה אינה אוסרת\u0004 ונתיישבו לפי שיטה זו כל הקשיים שהועלו קודם.","נאמר במשנה כי אם \u0003נתנו עירובן במקום אחד ושכח אחד\u0004 מהן הרי הוא אוסר על כולם. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003מקום אחד,\u0004 ומדוע אם נתנו במקום אחד שונה הדבר ממה שנתנו בני כל חצר במקום לחוד?","(נתנו סימנים לדברים הבאים: \u0003חיצונה עצמה בבית יחידאה רבינא דלא משכח בפנים)\u0004","\u0003אמר רב יהודה אמר רב:\u0004 מקום אחד משמעו שנתנו עירובם בחצר ה\u0003חיצונה, ומאי קרו לה\u0004 \u0005[ומדוע קראו לה]\u0006 \u0003\"מקום אחד\"\u0004 — הכונה היא שהוא ה\u0003מקום המיוחד לשתיהן\u0004 לשתי החצירות שהרי גם בני החצר הפנימית עוברים שם, שבמקרה זה אם שכח אחד מבני החיצונה אף הפנימית נאסרת, שהרי החצר הפנימית אין עירובה אלא בחצר החיצונה ואינה יכולה לומר שאין לחיצונה שותפות בה, אבל אם שכח אחד מבני הפנימית אינה נאסרת אלא החיצונה."],["\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כדברי ר' יהודה ש\"מקום אחד\" הכוונה לחיצונה: \u0003נתנו עירובן בחיצונה, ושכח אחד, בין מן החיצונה ובין מן הפנימית, ולא עירב — שתיהן אסורות,\u0004 אם \u0003נתנו עירובן בפנימית, ושכח אחד מן הפנימית ולא ערב — שתיהן אסורות.\u0004 שכח אחד \u0003מן החיצונה ולא עירב — שתיהן אסורות,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: בזו\u0004 כאשר העירוב מונח בפנימית והשוכח דר בחיצונה, \u0003פנימית מותרת וחיצונה אסורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר חנן לאביי: מאי שנא לרבנן דאמרי\u0004 \u0005[מה שונה ל\u0006שיטת \u0005חכמים שאומרים]\u0006 שהחצר ה\u0003פנימית מותרת — משום דאחדא דשא ומשתמשא\u0004 \u0005[שמחזיקה דלתה\u0006 סגורה בפני בני החיצונה\u0005, ומשתמשת\u0006 בחצר בעצמה\u0005],\u0006 \u0003לר' עקיבא נמי\u0004 \u0005[גם כן]:\u0006 \u0003תיחד דשא ותשמש\u0004 \u0005[תאחוז,\u0006 תסגור\u0005, דלתה ותשתמש]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עירוב מרגילה,\u0004 שלולא היה העירוב מונח בה, אפשר היה לטעון כן. אבל עתה כיון שהעירוב מונח בה, נעשית החיצונה רגילה לבוא אליה.","והקשו: אם כן, \u0003לרבנן נמי\u0004 \u0005[לחכמים גם כן]\u0006 אפשר לומר \u0003עירוב מרגילה!\u0004 ומשיבים: \u0003דאמרה\u0004 \u0005[שאומרת\u0006 אז\u0005]\u0006 החצר הפנימית לחיצונה: \u0003לתקוני\u0004 \u0005[ל\u0006שם \u0005תיקון]\u0006 \u0003שיתפתיך\u0004 שיתפנו אתכם בעירוב אחד, \u0003ולא לעוותי\u0004 \u0005[ל\u0006שם \u0005קלקול].\u0006 וכיון ששכח אחד מכם, אין אנו מסכימים עוד בשותפות זו.","ומקשים: לשיטת \u0003ר' עקיבא נמי תימא\u0004 \u0005[גם כן תאמר]\u0006 החצר הפנימית: \u0003לתקוני\u0004 \u0005[לתיקון]\u0006 \u0003שיתפתיך ולא לעוותי\u0004 \u0005[לקלקול]?\u0006 ומשיבים: \u0003דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003לה\u0004 חצר חיצונה לפנימית: \u0003מבטלינן\u0004 \u0005[מבטלים אנחנו]\u0006 \u0003לך רשותי\u0004 (לכם את רשותנו), ואז מותר לבני פנימית לטלטל בחצרם. ודברי ר' עקיבא הם עד שביטלו. \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 לדעתם \u0003אין ביטול רשות מחצר לחצר.\u0004","ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003שמואל ור' יוחנן\u0004 החולקים (לעיל עירובין סח,א) אם יש ביטול מחצר לחצר \u0003בפלוגתא דרבנן\u0004 \u0005[במחלוקת של חכמים]\u0006 \u0003ור' עקיבא קא מיפלגי\u0004 \u0005[נחלקו].\u0006 ש\u0003שמואל\u0004 הסבור שאין ביטול רשות מחצר לחצר \u0003אמר כרבנן\u0004 \u0005[כחכמים],\u0006 \u0003ור' יוחנן\u0004 הסבור שיש ביטול רשות \u0003אמר כר' עקיבא?\u0004","ודוחים: \u0003אמר לך שמואל\u0004 \u0005[יכול היה שמואל לומר לך]\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי, \u0003אפילו ל\u0004שיטת \u0003ר' עקיבא\u0004 אמרתי. \u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' עקיבא הכא\u0004 \u0005[כאן]\u0006 שיש ביטול רשות מחצר לחצר \u0003אלא בשתי חצירות זו לפנים מזו, דאסרן אהדדי\u0004 \u0005[ש\u0006הן \u0005אוסרות זו על זו],\u0006 \u0003אבל התם\u0004 \u0005[שם]\u0006 שנחלקו בשתי חצירות סמוכות, \u0003מי קא אסרן אהדדי\u0004 \u0005[האם הן אוסרות זו על זו]?\u0006 ולכן שם אין צורך כלל לבטל רשות, אף לשיטה זו.","\u0003ור' יוחנן אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 אמרתי, \u0003עד כאן לא קאמרי רבנן הכא\u0004 \u0005[אמרו חכמים כאן]\u0006 שאין חצר יכולה לבטל רשותה לחצר שניה \u0003אלא\u0004 משום \u0003דאמרה\u0004 \u0005[שאומרת]\u0006 החצר הפנימית \u0003לה: אדמבטלת\u0004 \u0005[עד שאת מבטלת]\u0006 \u0003לי\u0004 רשות, \u0003קא אסרת עלאי\u0004 \u0005[הרי את אוסרת עלי],\u0006 ומוותרים אנו על הביטול ועל האיסור. \u0003אבל התם, מי קאסרת עלה\u0004 \u0005[שם, האם אוסרת עליה]?\u0006 וכיון שכך לא אמרו חכמים שאין לבטל.","נאמר במשנה: \u0003ואם היו\u0004 החצירות \u0003של יחידים\u0004 אין צריכים לערב. \u0003אמר רב יוסף, תני\u0004 \u0005[שנה]\u0006 \u0003רבי: היו שלשה\u0004 אנשים בשתי החצירות — \u0003אסורין\u0004 בלא עירוב. בין שהיו שנים בחיצונה ואחד בפנימית, ובין שהיו שנים בפנימית ואחד בחיצונה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ביבי\u0004 לחכמים: \u0003לא תציתו ליה, אנא אמריתה ניהלה\u0004 \u0005[אל תקשיבו לו,\u0006 שטעות בידו\u0005,\u0006 כי \u0005אני אמרתי אותה לו],\u0006 \u0003ומשמיה\u0004 \u0005[ומשמו]\u0006 של \u0003רב אדא בר אהבה אמריתה ניהלה\u0004 \u0005[אמרתי אותה לו],\u0006 אלא משום שחלה רב יוסף נשתכח ממנו דיוק הדברים, והנוסח הנכון היה כך: אם היו שנים בחיצונה אסור, \u0003הואיל ואני קורא בהן רבים בחיצונה,\u0004 וגזרו חכמים שיהיו רבים אלה אוסרים את הפנימית. \u0003אמר רב יוסף\u0004 בהשתוממות כששמע זאת: \u0003מריה\u0004 \u0005[ריבונו]\u0006 של \u0003אברהם! 'רבים' ב'רבי' איחלף\u0004 \u0005[התחלף]\u0006 \u0003לי,\u0004 שכשהחל להיזכר בתלמודו מחדש נדמה היה לו בטעות כי הלכה זו נאמרה בשם \"רבי\", במקום שנאמרה בדין \"רבים\", ובשל טעות זאת יצר אותה גירסה מדומה.","\u0003ושמואל אמר: לעולם מותרות, עד שיהו שנים בפנימית ואחד בחיצונה.\u0004","\u0003אמר ר' אלעזר: וגוי הרי הוא כרבים,\u0004 שאם בפנימית גר גוי, ובחיצונה שני ישראלים, אוסרת דריסת רגלו על שניהם. ומקשים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 יחיד מ\u0003ישראל\u0004 ש\u0003לא אסר\u0004 \u0005[אוסר]\u0006 על חבירו, \u0003דמאן דידע\u0004 \u0005[שמי שיודע]\u0006 שבפנימית אין אלא יחיד — \u0003ידע\u0004 \u0005[יודע],\u0006 \u0003ומאן דלא ידע\u0004 \u0005[ומי שלא יודע]\u0006 \u0003— סבר: עירובי עירב\u0004 \u0005[סבור: עירב].\u0006 אם כן, \u0003גוי נמי\u0004 \u0005[גם כן],\u0006 \u0003אמרינן: דידע — ידע, דלא ידע — סבר: אגירי אוגר\u0004 \u0005[אומרים אנו:\u0006 מי \u0005שיודע\u0006 שהוא יחידי \u0005—\u0006 \u0005יודע\u0006 גם שאינו אוסר כשהוא יחידי, \u0005ו\u0006מי \u0005שאינו יודע\u0006 יחשוב שודאי \u0005שכר\u0006 מן הגוי\u0005]!\u0006","ומשיבים: אין לומר כן כי \u0003סתם גוי, אי איתא דאוגר — מיפעא פעי\u0004 \u0005[אם אמנם שהשכיר —\u0006 \u0005היה מפטפט],\u0006 והיו הכל יודעים זאת. ואם לא סיפר — יודעים שלא השכיר.","\u0003אמר רב יהודה אמר שמואל: עשרה בתים זה לפנים מזה\u0004 ואין הפנימי יכול לצאת לחצר אלא אם כן עובר על פני כולם, \u0003פנימי\u0004 לבדו \u0003נותן את עירובו\u0004 בחצר, \u0003ודיו.\u0004 והדרים בשאר הבתים הרי הם כדרים בבית שער ומסדרון לבית הפנימי, והדרים בבית שער אינם צריכים לתת.","\u0003ור' יוחנן אמר: אפילו\u0004 ה\u0003חיצון\u0004 חייב לערב. ומקשים האיך אפשר לומר כן הלא דירת \u0003חיצון בית שער הוא\u0004 לפנימיים לו! ומדוע יתן עירוב? ומסבירים הכוונה היא \u0003חיצון של פנימי\u0004 שהתכוון לומר שאף הבית התשיעי מבחוץ שהוא חיצון לבית אחרון, נותן עירוב ואינו כבית שער.","וטעם הדברים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון\u0005, הם נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 שמואל\u0005]\u0006 \u0003סבר: בית שער דיחיד שמיה\u0004 \u0005[נחשב]\u0006 \u0003בית שער\u0004 ואם כן הבית התשיעי נידון כבית שער, שהרי משמש הוא דרך מעבר ליחיד הגר לפנים ממנו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן\u0005]\u0006 \u0003סבר: לא שמיה\u0004 \u0005[אינו נחשב]\u0006 \u0003בית שער\u0004 ולכן חייב אף הוא לערב.","\u0003אמר ר' נחמן אמר רבה בר אבוה אמר רב: שתי חצירות ושלשה בתים ביניהן, זה,\u0004 בן חצר אחת, \u0003בא דרך זה,\u0004 הבית הסמוך לו, \u0003ונותן עירובו בזה,\u0004 בבית האמצעי. \u0003וזה,\u0004 בן החצר האחרת, \u0003בא דרך זה,\u0004 הבית הסמוך לחצר שלו, \u0003ונותן עירוב\u0004 אף הוא \u0003בזה\u0004 האמצעי."],["\u0003זה נעשה בית שער לזה, וזה\u0004 בית אחר, \u0003נעשה בית שער לזה.\u0004 והבית ה\u0003אמצעי הוה ליה\u0004 \u0005[הריהו\u0006 נעשה\u0005]\u0006 \u0003בית שמניחין בו עירוב,\u0004 ובית כזה \u0003אין צריך ליתן את הפת.\u0004","\u0003בדיק להו\u0004 \u0005[בדק\u0006 בחן \u0005אותם]\u0006 החכם \u0003רחבה לרבנן\u0004 \u0005[את חכמים]:\u0006 היו \u0003שתי חצירות ושני בתים ביניהם\u0004 ולא רצו לערב יחד, ולכן \u0003זה בא דרך\u0004 בית \u0003זה\u0004 הסמוך לחצירו, \u0003ונתן עירובו בזה,\u0004 בבית הסמוך לחבירו. \u0003וזה בא דרך זה ונתן עירובו בזה,\u0004 האם \u0003קנו עירוב או לא. מי משוית להו\u0004 \u0005[האם\u0006 אפשר ש\u0005תעשה,\u0006 תחשוב\u0005, אותם]\u0006 \u0003לגבי דהאי\u0004 \u0005[לגביו של זה]\u0006 המניח עירוב \u0003בית, ולגבי דהאי\u0004 \u0005[ולגביו של זה]\u0006 שעובר דרכו \u0003בית שער,\u0004 שהוא יכול לעבור דרך הבית הסמוך לו שייחשב כבית שער, ולהניח עירובו בבית אחר שיחשב כבית ממש. וכן השני \u0003ולגבי דהאי\u0004 \u0005[ולגביו של זה]\u0006 \u0003בית שער, ולגבי דהאי\u0004 \u0005[ולגביו של זה]\u0006 \u0003בית\u0004 בהיפוך הדברים?","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שניהן לא קנו עירוב,\u0004 כי \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 כלומר, בכל אופן שתרצה תחשוב, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בית שער משוית ליה\u0004 \u0005[עושה אתה אותו],\u0006 \u0003הנותן את עירובו בבית שער אכסדרה ומרפסת — אינו עירוב. אי\u0004 \u0005[אם]\u0006 כ\u0003בית משוית ליה\u0004 \u0005[אתה עושה\u0006 מחשיב \u0005אותו],\u0006 הרי \u0003קא\u0004 \u0005[הוא]\u0006 \u0003מטלטל לבית\u0004 ש\u0003לא מערב ליה\u0004 \u0005[אותו].\u0006 וכיון שיש ספק כפול בדבר שההנחה המועילה לגבי אחד מזיקה לשני וכן להפך, הרי משום כך שניהם לא קנו עירוב כל עיקר.","והקשה להם: \u0003ומאי שנא\u0004 \u0005[ומה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004ההלכה שקבע \u0003רבא?\u0004 ש\u0003אמר רבא, אמרו לו שנים\u0004 לאחד: \u0003צא וערב עלינו. לאחד עירב עליו מבעוד יום, ולאחד עירב עליו בין השמשות.\u0004 וארע ש\u0003זה שעירב עליו מבעוד יום נאכל עירובו בין השמשות, וזה שעירב עליו בין השמשות נאכל עירובו משתחשך.\u0004 ובין השמשות ספק יום ספק לילה הוא, ואם יום הוא — עירוב שהונח בו נפסל, ובכל זאת אמר רבא \u0003שניהם קנו עירוב,\u0004 שאף שיש כאן שתי הנחות סותרות, מקילים ואומרים שלגבי זה שנאכל עירובו בבין השמשות, מחשיבים אותו כאילו הוא כבר לילה וקנה שביתה מבעוד יום, והועיל לו. ואילו לגבי זה שעירב בין השמשות נחשב כאילו הוא עדיין יום ויש לו עוד שהות כדי לקנות שביתה מחדש, שספק בדיני עירובין יש להקל בו!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003ספק יממא\u0004 \u0005[יום]\u0006 \u0003ספק ליליא\u0004 \u0005[לילה]\u0006 \u0003לא מינכרא מילתא\u0004 \u0005[ניכר הדבר],\u0006 ואין הכל רואים מתי וכיצד היה הדבר, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שהבתים עומדים לפנינו, \u0003אי דלגבי דהאי\u0004 \u0005[אם שלגביו של זה]\u0006 שמניח את העירוב זה \u0003בית, לגבי דהאי\u0004 \u0005[לגביו של זה]\u0006 שעובר דרכו הרי הוא גם כן \u0003בית. אי לגבי דהאי\u0004 \u0005[אם לגביו של זה]\u0006 שעובר דרכו הוא \u0003בית שער, לגבי דהאי נמי\u0004 \u0005[לגביו של זה\u0006 שמניח בו עירוב \u0005גם כן]\u0006 \u0003בית שער,\u0004 ומשום כך אין עירובם קונה.","","\u0003חלון\u0004 שהיה בכותל \u0003שבין שתי חצירות\u0004 שהיה \u0003ארבעה על ארבעה\u0004 טפחים, והיה \u0003בתוך עשרה\u0004 טפחים לקרקע — \u0003מערבין\u0004 בני החצירות \u0003שנים\u0004 שני עירובין, אחד לכל חצר. \u0003ואם רצו — מערבין\u0004 עירוב \u0003אחד,\u0004 ומצרפים את שתי החצירות כאחת. שעל ידי החלון יכולות שתי חצירות להיחשב כאחת.","ואולם אם היה החלון \u0003פחות\u0004 בשטחו \u0003מארבעה על ארבעה\u0004 טפחים \u0003או\u0004 שהיה \u0003למעלה מעשרה טפחים, שוב אינו נחשב כפתח, ואינן יכולות להיחשב כחצר אחת, ולכן מערבין שנים ואין מערבין אחד.\u0004","על קביעת שטחו של החלון בארבעה על ארבעה טפחים שואלים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר\u0006 ש\u0005שנינו\u0006 ב\u0005סתם\u0006 משנה\u0005]\u0006 \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 (לעיל עירובין ט,א) ש\u0003אמר: כל פחות מארבעה כלבוד דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 ולכן צריך שיהיה החלון בן ארבעה טפחים, שבפחות מכן, הריהו כלבוד וכאילו נסתם החלון. ודוחים: \u0003אפילו תימא כרבנן\u0004 \u0005[תאמר\u0006 שמשנתנו \u0005כ\u0006דעת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו ש\u0003פליגי רבנן עליה\u0004 \u0005[חלקו חכמים עליו\u0006 על\u0005]\u0006 \u0003רבן שמעון בן גמליאל אלא לענין לבודין\u0004 (מיהו הנקרא לבוד וצמוד), \u0003אבל לענין פתחא\u0004 \u0005[פתח]\u0006 \u0003אפילו רבנן מודו דאי איכא\u0004 \u0005[חכמים מודים שאם יש]\u0006 פתח \u0003ארבעה על ארבעה — חשיב\u0004 \u0005[נחשב\u0006 הוא\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא חשיב\u0004 \u0005[נחשב].\u0006 נאמר במשנה שאם היה החלון \u0003פחות מארבעה\u0004 או למעלה מעשרה, מערבים שנים. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן הדבר\u0005]\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 קודם לכן \u0003ארבעה על ארבעה בתוך עשרה — ממילא אנא ידענא\u0004 \u0005[אני יודע]\u0006 ש\u0003פחות מארבעה ולמעלה מעשרה לא!\u0004 ולשם מה יש לחזור ולשנות דבר זה? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 \u0003דכוליה\u0004 \u0005[שכולו\u0006 כל החלון\u0005]\u0006 היה \u0003למעלה מעשרה, אבל\u0004 אם \u0003מקצתו בתוך עשרה — מערבין שנים, ואם רצו — מערבין אחד.\u0004 ומעירים: לפי הסבר זה נמצא כי \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנה \u0005את\u0006 דבר \u0005זה ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כולו למעלה מעשרה ומקצתו בתוך עשרה, כולו בתוך עשרה ומקצתו למעלה מעשרה — מערבין שנים, ואם רצו — מערבין אחד.\u0004","","","","","עיקר ההלכה שבברייתא זו ברור לנו, אך על לשונה של הברייתא תוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 אם \u0003כולו למעלה מעשרה ומקצתו בתוך עשרה, אמרת \"מערבין שנים ואם רצו מערבין אחד\"\u0004 שדינו כפתח, \u0003כולו בתוך עשרה ומקצתו למעלה מעשרה מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]?\u0006 ומשיבים: אכן הברייתא בסיגנון של \u0003\"זו ואין צריך לומר זו קתני\u0004 \u0005[נשנתה]\u0006\" והיא הולכת מן הכבד והמחודש אל הקל והפשוט. \u0003אמר ר' יוחנן: חלון עגול צריך שיהא בהיקפו עשרים וארבעה טפחים, ושנים ומשהו מהן בתוך עשרה, שאם ירבענו\u0004 (יעשה בתוכו צורת ריבוע) הריהו בן ארבעה על ארבעה טפחים, ו\u0003נמצא משהו בתוך עשרה.\u0004","","","על חשבון זה שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 כלל הוא בידינו: \u0003כל שיש בהיקפו שלשה טפחים — יש בו ברוחבו טפח,\u0004 ואם כן לפי חשבון זה \u0003בתריסר\u0004 \u0005[בשנים עשר]\u0006 טפחים \u0003סגיא\u0004 \u0005[מספיק].\u0006 שעיגול שהיקפו שנים עשר טפחים, יש לפי זה בקוטרו ארבעה טפחים, אם כן דיו בכך לעשות חלון ארבעה על ארבעה."],["\u0003הני מילי בעיגולא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בעיגול]\u0006 וביחס בין היקפו וקוטרו שאורכו ורוחבו ארבעה טפחים, \u0003אבל בריבועא בעינן טפי\u0004 \u0005[בריבוע צריכים יותר].\u0006 שאם רוצים שיהא ריבוע שלם חסום, שאף עוביו בן ארבעה טפחים, ויכנס כולו בתוך העיגול, יש צורך בהיקף גדול יותר.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כמה מרובע יתר על העגול — רביע,\u0004 אם כן לכל היותר \u0003בשיתסר סגיא\u0004 \u0005[בששה עשר\u0006 טפחים \u0005די]\u0006 ולא יותר!","ומשיבים: \u0003הני מילי בעיגולא דנפיק מגו ריבועא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בעיגול היוצא מתוך ריבוע],\u0006 שהריבוע מקיף את העיגול. \u0003אבל ריבועא דנפיק מגו עיגולא, בעינן טפי\u0004 \u0005[ריבוע היוצא מתוך עיגול, צריכים אנו יותר]\u0006 וההבדל בין הריבוע והעיגול גדול אז יותר. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003משום מורשא דקרנתא\u0004 \u0005[בליטתן של הקרנות].\u0006 שהרי המרחק מנקודת המרכז ועד לקצה זוית המרובע, גדול יותר מן המרחק עד לפאת המרובע.","ועדיין מקשים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל אמתא בריבועא אמתא ותרי חומשי באלכסונא\u0004 \u0005[אמה בריבוע\u0006 הריהי \u0005אמה ושתי חמישיות באלכסון],\u0006 ואם נחשב כמה הוא אלכסונו של ריבוע בן ארבעה טפחים נמצא כי האלכסון הריהו חמישה טפחים ושלוש חמישיות, ואם נכפיל מדה זו פי שלוש לדעת את ההיקף, נמצא כי \u0003בשיבסר נכי חומשי סגיא\u0004 \u0005[בשבעה עשר פחות חמישית מספיק]\u0006 להקיף בעיגול ריבוע בן ארבעה טפחים.","ומשיבים: \u0003ר' יוחנן אמר כי\u0004 \u0005[כ\u0006שיטת\u0005]\u0006 \u0003דייני קיסרי, ואמרי לה כרבנן דקיסרי דאמרי\u0004 \u0005[ויש אומרים כ\u0006שיטת \u0005חכמי קיסרי שאומרים]:\u0006 \u0003עיגולא מגו ריבועא — ריבעא\u0004 \u0005[עיגול מתוך ריבוע\u0006 פחות ממנו ב\u0005רבע],\u0006 \u0003ריבועא מגו עיגולא — פלגא\u0004 \u0005[ריבוע\u0006 שמילא \u0005בתוך עיגול,\u0006 ההבדל הוא \u0005מחצית]\u0006 של הריבוע. ולפי זה עשה ר' יוחנן את חשבונו, ששני שליש מעשרים וארבעה שהוא היקף העיגול הם שש עשרה, שזהו היקפו של הריבוע, שהוא ארבע על ארבע.","נאמר במשנה שאם היה החלון \u0003פחות מארבעה על ארבעה\u0004 טפחים מערבין שנים ולא אחד, וכן הדין אם היה החלון למעלה מעשרה טפחים. \u0003אמר רב נחמן: לא שנו\u0004 דין זה של חלון בתוך עשרה \u0003אלא\u0004 ב\u0003חלון שבין שתי חצירות, אבל\u0004 אם היה \u0003חלון שבין שני בתים — אפילו למעלה מעשרה נמי\u0004 \u0005[גם כן]\u0006 \u0003אם רצו לערב — מערבין אחד. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003ביתא כמאן דמלי דמי\u0004 \u0005[הבית כאילו מלא נחשב],\u0006 ולכן אין להבדיל בבית בין למטה מעשרה ולמעלה מעשרה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 מהברייתא: \u0003אחד לי\u0004 כלומר אחד הוא, \u0003חלון שבין שתי חצירות, ואחד לי חלון שבין שני בתים, ואחד לי חלון שבין שתי עליות, ואחד לי חלון שבין שני גגין, ואחד לי חלון שבין שני חדרים — כולן ארבעה על ארבעה בתוך עשרה,\u0004 ובניגוד לשיטת רב נחמן!","\u0003ומשיבים: תרגומא\u0004 \u0005[הסבר\u0006 דבר זה\u0005]\u0006 שדין עשרה טפחים שהוזכר בברייתא זו דיבר רק על \u0003חצירות,\u0004 ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אחד לי\" קתני\u0004 \u0005[שנה]\u0006 משמע שכולם שוים בזה! אלא \u0003תרגומא\u0004 \u0005[הסבר\u0006 זאת\u0005]\u0006 שכולם שוים לענין שצריך שיהא בחלון \u0003ארבעה על ארבעה\u0004 טפחים, אבל לא הכל חייבים להיות בגובה עשרה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אבא מרב נחמן: לול\u0004 (כעין חור או ארובה) \u0003הפתוח מן בית\u0004 של אחד \u0003לעלייה\u0004 של אחר, האם \u0003צריך סולם קבוע\u0004 שיעמוד בתוך לול זה \u0003להתירו\u0004 כדי שתחשבנה שתי הקומות כדירה אחת \u0003או אין צריך סולם קבוע להתירו?\u0004","וצדדי הבעיה: \u0003כי אמרינן ביתא כמאן דמליא דמי\u0004 \u0005[כאשר אומרים אנו\u0006 ש\u0005הבית כמלא נחשב]\u0006 \u0003הני מילי\u0004 \u0005[\u0006דברים \u0005אלה אמורים]\u0006 בחלון שהיה \u0003מן הצד, אבל\u0004 באמצע — \u0003לא,\u0004 ולכן אין אומרים שהלול סמוך לחלק המלא בבית, וצריך סולם קבוע כדי להתירו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה],\u0006 וכיון שהבית נחשב כמלא, מגיע הלול עד העלייה ושתי הקומות הם כדירה אחת ואין צורך בסולם?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו צריך. סבור מינה\u0004 \u0005[סברו\u0006 חכמים \u0005מ\u0006תשובה \u0005זו]\u0006 כי הכוונה: \u0003סולם קבוע הוא\u0004 ש\u0003אינו צריך, הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003סולם עראי — צריך.\u0004 ואולם \u0003אתמר\u0004 \u0005[נאמר]\u0006 בענין זה, \u0003אמר רב יוסף בר מניומי אמר רב נחמן: אחד סולם קבוע ואחד סולם ארעי — אינו צריך,\u0004 שעצם העובדה שהפתח הוא בתוך הבית דיה כדי להתיר.","\u0003כותל ש\u0004היה \u0003בין שתי חצירות, גבוה עשרה ורוחב ארבעה\u0004 טפחים — \u0003מערבין שנים\u0004 עירוב לכל חצר לעצמה, \u0003ואין מערבין אחד.\u0004","\u0003היו בראשו\u0004 של הכותל \u0003פירות — אלו\u0004 בני חצר זו \u0003עולין מכאן ואוכלין\u0004 מהם, \u0003ואלו\u0004 בני החצר האחרת \u0003עולין מכאן ואוכלין, ובלבד שלא יורידו\u0004 את הפירות \u0003למטן\u0004 מראש הכותל לחצירות.","\u0003נפרצה הכותל,\u0004 אם היתה הפירצה \u0003עד עשר אמות — מערבין שנים, ואם רצו מערבין אחד, שהוא כפתח\u0004 ככל פירצה פחות מעשר אמות. נפרץ \u0003יותר מכאן — מערבין אחד ואין מערבין שנים,\u0004 שפירצה בגודל זה מבטלת את המחיצה ונעשו שתי החצירות כרשות אחת.","שאלו: אם כותל זה \u0003אין בו\u0004 רוחב \u0003ארבעה\u0004 טפחים \u0003מאי\u0004 \u0005[מה\u0006 יהא דינו\u0005]?\u0006 \u0003אמר רב:\u0004 במקרה זה \u0003אויר שתי רשויות שולטת בו,\u0004 שכיון שאין הכותל רחב כדי להוות רשות לעצמה, נחשב ראש הכותל כשייך לשתי החצירות גם יחד וממילא אסור לשתיהן, \u0003ולא יזיז בו\u0004 ואפילו בראשו \u0003אפילו\u0004 כ\u0003מלא נימה.\u0004"],["\u0003ור' יוחנן אמר: אלו,\u0004 בני חצר זו, \u0003מעלין מכאן\u0004 מהחצר לראש הכותל, וכן מורידים ממנו לחצר \u0003ואוכלין, ואלו מעלין מכאן ואוכלין.\u0004 שנעשה הכותל כאילו אינו קיים, ובטלה רשותו לשתי החצירות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו עולין מכאן ואוכלין, ואלו עולין מכאן ואוכלין.\u0004 ונדייק: \u0003עולין — אין\u0004 \u0005[כן],\u0006 ואולם \u0003מעלין מהחצר לראש הכותל — לא.\u0004 וקשה לדברי ר' יוחנן!","ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003יש בו\u0004 ברוחבו של הכותל \u0003ארבעה על ארבעה\u0004 טפחים, \u0003עולין — אין\u0004 \u0005[כן],\u0006 \u0003מעלין — לא,\u0004 משום שאז הריהו כעין רשות לעצמה. ואולם אם \u0003אין בו ארבעה על ארבעה — מעלין נמי\u0004 \u0005[גם כן].\u0006","\u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין זה, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מקום שאין בו ארבעה על ארבעה\u0004 טפחים, שהיה מצוי בין רשות הרבים ורשות היחיד — \u0003מותר לבני רשות הרבים\u0004 וגם \u0003לבני רשות היחיד לכתף עליו\u0004 לשים עליו משאם ולקחתו משם, משום שהוא נחשב כמקום פטור. \u0003ובלבד שלא יחליפו\u0004 בני רשות זו עם בני רשות אחרת דרך מקום פטור. הרי שבמקום פטור לא חשש ר' יוחנן והתיר גם לבני רשות זו וגם לבני רשות אחרת להשתמש בו.","ושואלים: \u0003ו\u0004כי \u0003רב\u0004 האוסר לטלטל באופן כזה כמלוא נימה \u0003לית ליה\u0004 \u0005[אין לו\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003רב דימי\u0004 לענין זה? ומשיבים: \u0003אי\u0004 \u0005 [אם]\u0006 מדובר \u0003ב\u0004מקום פטור שבין \u0003רשויות דאורייתא\u0004 \u0005[שמן התורה]\u0006 (רשות היחיד ורשות הרבים) — \u0003הכי נמי\u0004 \u0005[כך גם כן],\u0006 ומודה רב שמותר לבני שתי הרשויות להעמיס עליו.","ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בכותל זה \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו] —\u0006 \u0003ברשויות דרבנן\u0004 \u0005[שמדברי חכמים].\u0006 \u0003וחכמים עשו חזוק לדבריהם יותר משל תורה.\u0004 כי דברי תורה החמורים נשמרים ואין צורך להחמיר בגזירות ובתקנות לשמירתם, מה שאין כך בתקנת חכמים, שאם לא ישמרו את הסייגים יבואו לפרוץ את התקנה כולה.","\u0003אמר רבה אמר רב הונא אמר רב נחמן: כותל שבין שתי חצירות, צידו אחד\u0004 שלצד חצר אחת \u0003גבוה עשרה טפחים וצידו\u0004 ה\u0003אחד שוה לארץ.\u0004 שחצר זו היתה גבוהה יותר, וגובה הכותל שווה לגובהה, או אפילו גבוה ממנה אלא שעדיין נמוך מעשרה טפחים — \u0003נותנין אותו\u0004 את השימוש בראש הכותל לענין שבת, \u0003לזה ששוה לארץ\u0004 בלבד.","וטעמו של דבר, \u0003משום דהוה\u0004 \u0005[שהוא]\u0006 מצד של \u0003זה תשמישו בנחת ולזה תשמישו בקשה\u0004 (בקושי). שבני החצר שגב הכותל שוה לקרקעם, נוח להם להשתמש בו. \u0003ו\u0004כלל הוא ש\u0003כל\u0004 דבר לענין שבת ש\u0003לזה בנחת ולזה בקשה — נותנין אותו לזה שתשמישו בנחת.\u0004","ובדומה לכך \u0003אמר רב שיזבי אמר רב נחמן: חריץ\u0004 (תעלה) \u0003שבין שתי חצירות, צידו אחד עמוק עשרה וצידו אחד שוה לארץ\u0004 או פחות מעשרה טפחים, לפי שחצר זו נמוכה בהרבה מחברתה — \u0003נותנין אותו לזה ששוה לארץ.\u0004 וטעמו של דבר: \u0003משום דהוה ליה\u0004 \u0005[שהריהו,\u0006 נעשה\u0005]\u0006 בצד אחד \u0003לזה תשמישו בנחת, ולזה\u0004 לצד האחר שהחריץ נמוך בו \u0003תשמישו בקשה,\u0004 וכל שלזה בנחת ולזה בקשה, נותנים אותו לזה שתשמישו בנחת.","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכות]\u0006 להיאמר שתי הלכות קרובות אלה, ואין לומר שתילמד האחת מחברתה. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק ב\u0003כותל,\u0004 היינו אומרים \u0003משום דבגובהא משתמשי אינשי\u0004 \u0005[שבגובה משתמשים אנשים],\u0006 ואף לבני החצר הנמוכה קל יחסית השימוש בכותל זה. \u0003אבל\u0004 ב\u0003חריץ — בעומקא\u0004 \u0005[בעומק]\u0006 \u0003לא משתמשי אינשי\u0004 \u0005[משתמשים אנשים],\u0006 שטירחה היא להתכופף ולשים דבר בתוך החריץ — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ויהיו שניהם אסורים.","\u0003ו\u0004כן \u0003אי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 \u0003בחריץ\u0004 בלבד, היינו אומרים טעמו \u0003משום\u0004 ש\u0003לא בעיתא תשמישתא\u0004 \u0005[מדאיג שימושו],\u0006 שכל דבר שמניחים בו נשמר. \u0003אבל כותל דבעיתא תשמישתא\u0004 \u0005[שמדאיג שימושו]\u0006 שמא יפול דבר ממנו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאמרה בו הלכה זו, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שתי הלכות אלה.","ולענין הכותל שבין החצירות אמרו: אם \u0003בא למעטו\u0004 מגובה עשרה, שמניח אבן בצידו או בונה שם אצטבה, ועל ידי כך יותר להשתמש בו, או יעשה מעבר בינו ובין חצר אחרת. \u0003אם יש במעוטו\u0004 (באורך החלק שנתמעט בו) \u0003ארבעה\u0004 טפחים עד פחות מעשרה — \u0003מותר להשתמש בכל הכותל כולו.\u0004 שנעשה מקום זה כפתח, ונעשו שתי החצירות כאחת והכותל כולו מותר. \u0003ואם לאו,\u0004 שאין אורך ארבעה טפחים במיעוט — \u0003אין משתמש אלא כנגד המיעוט\u0004 שבאותו מקום ולא יותר.","על הלכה זו תוהים: \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 איך יכול אתה לקבל דבר זה? \u0003אי אהני מעוטא\u0004 [אם הועיל המיעוט] אף שהוא פחות מארבעה טפחים — \u0003בכוליה\u0004 \u0005[בכל]\u0006 ה\u0003כותל\u0004 כולו \u0003לישתמש\u0004 \u0005[שישתמש].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אהני\u0004 \u0005[הועיל\u0006 המיעוט\u0005]\u0006 — \u0003אפילו כנגד המיעוט נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ישתמש, שאין חלק זה מעלה ואיננו מוריד. \u0003אמר רבינא:\u0004 כאן מדובר \u0003כגון שעקר חוליא מראשו\u0004 של הכותל, שכיון שבפועל אין הכותל גבוה שם עשרה מותר להשתמש בו במקום זה כבפתח.","כהמשך לדברים אלה \u0003אמר רב יחיאל:\u0004 אם \u0003כפה ספל\u0004 (כלי גדול) והניחו סמוך לכותל עד שאין בגובהו עשרה טפחים — \u0003ממעט.\u0004","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע\u0006 יהא כן\u0005]?\u0006 והלוא ספל זה \u0003דבר הניטל בשבת הוא,\u0004 שאין בו איסור טלטול, \u0003ו\u0004כלל הוא ש\u0003דבר הניטל בשבת אינו ממעט.\u0004 שהרי אי אפשר לראותו כחלק מהגדר, שכיון שאפשר ליטלו משם ביום השבת עצמו, אינו יכול להיחשב כמחיצת קבע. ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דחבריה בארעא\u0004 \u0005[שחבר\u0006 את הספל \u0005לארץ].\u0006 ומפני שיש עליו עפר, אי אפשר לטלטלו בשל האיסור לטלטל את העפר.","ומקשים: \u0003וכי חבריה בארעא, מאי הוי\u0004 \u0005[וכאשר חברו בארץ, מה נהיה\u0006 על ידי כך\u0005]?\u0006 \u0003והא תניא\u0004 \u0005[והלוא שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פגה\u0004 של תאנים \u0003שהטמינה בתבן\u0004 המיועד להסקה שהוא מוקצה כדי שתבשיל, וכן \u0003חררה\u0004 (פת דקה) \u0003שהטמינה\u0004 מבעוד יום \u0003בגחלים\u0004 וכבו, אף על פי שהם מוקצה, \u0003אם מגולה מקצתה — נטלת בשבת,\u0004 ואין אוסרים משום שאגב כך מטלטל את התבן או הגחלים.","ומסבירים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו\u0006 לספל\u0005]\u0006 \u0003אוגניים\u0004 בראשו והעפר מכסה ממש את אגני הספל. והמוציאו, עוקר עפר ממקומו בדרך חפירה.","ושוב מקשים: \u0003וכי אית ליה\u0004 \u0005[וכאשר יש לו]\u0006 \u0003אוגניים, מאי הוי\u0004 \u0005[מה נהיה\u0006 על ידי כך\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הטומן לפת\u0004 או \u0003צנון תחת הגפן\u0004 רק כדי לשמרם שם, \u0003בזמן\u0004"],["\u0003שמקצת עלין\u0004 של הלפת או הצנון \u0003מגולין — אינו חושש, לא משום כלאים,\u0004 שאין כאן איסור של זריעת כלאים, ירקות בתוך הכרם, שהרי לא לשם זריעה נתכוון. \u0003ולא משום מעשר,\u0004 שאינו צריך לחשוש שמא צמחו והוסיפו הלפת או הצנון ויש להפריש מעשר על התוספת. \u0003ולא משום שביעית,\u0004 שאין בכך משום עבודת האדמה בשנת השמיטה, וכן אין לחשוש שמא צמחו והוסיפו והרי תוספת זו אסורה כגידולי שביעית. \u0003וניטלין בשבת\u0004 מן האדמה, אף שחלקו הגדול של הצנון בעפר, ובכל זאת מותר להוציאו. ואם כן אף בספל אין מקום לאיסור!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה מיוחד שחיבר את הספל חיבור מוצק כל כך \u0003דבעי מרא וחצינא\u0004 \u0005[שיש צורך\u0006 ב\u0005מעדר ואיזמל]\u0006 כדי לעוקרו, וזו מלאכת חפירה ממש האסורה בשבת, וכיון שאי אפשר לעוקרו בשבת הרי ספל זה נחשב כקבוע וממעט.","נאמר כי \u0003סולם המצרי\u0004 שהוא קטן \u0003אינו ממעט\u0004 וסולם \u0003הצורי\u0004 שהוא גדול \u0003ממעט.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003סולם המצרי? אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ינאי: כל שאין לו ארבעה חווקים\u0004 \u0005[שלבים].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003סולם המצרי לא ממעט? אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא שמיע לך הא\u0004 \u0005[שמעת\u0006 דבר \u0005זה]\u0006 ש\u0003אמר רב אחא בר אדא, אמר רב המנונא אמר רב: משום דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003דבר שניטל בשבת\u0004 שאינו מוקצה, \u0003וכל דבר שניטל בשבת — אינו ממעט,\u0004 שהרי איננו נעשה חלק מהכותל.","והקשה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו צורי נמי\u0004 \u0005[גם כן]\u0006 שהרי גם סולם גדול אינו מוקצה, ומותר לטלטלו בשבת! ותרצו: \u0003התם\u0004 \u0005[שם]\u0006 בסולם צורי \u0003כובדו קובעו,\u0004 שאף שהוא מותר בטלטול, הרי משום כובדו אינו קל לטלטול, ועל כן הוא מיעוט של ממש.","\u0003אמר אביי: כותל שבין שתי חצירות\u0004 שהיה \u0003גבוה עשרה טפחים, והניח\u0004 סמוך לכותל \u0003סולם רחב ארבעה\u0004 טפחים \u0003מכאן\u0004 מצד חצר זו \u0003וסולם רחב ארבעה מכאן\u0004 מצד החצר האחרת. \u0003ואין בין זה לזה שלשה טפחים,\u0004 ששני הסולמות משני עברי הכותל סמוכים זה לזה במרחק שלושה טפחים, אפילו אינם מכוונים — \u0003ממעט.\u0004 נחשב כאילו היה שם פתח, שהסולם דינו כפתח לענין זה. אם היה המרחק \u0003שלשה\u0004 טפחים או יותר — \u0003אינו ממעט.\u0004","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הגבלה זו \u0003אלא\u0004 ש\u0003לא הוי\u0004 \u0005[היה]\u0006 רוחב ה\u0003כותל ארבעה\u0004 טפחים, \u0003אבל הוי\u0004 \u0005[היה]\u0006 ה\u0003כותל ארבעה\u0004 טפחים — \u0003אפילו\u0004 היה סולם \u0003מופלג\u0004 (מרוחק) \u0003טובא\u0004 \u0005[הרבה]\u0006 מחבירו, \u0003נמי\u0004 \u0005[גם כן]\u0006 מתיר, שמתוך שהוא רחב ארבעה טפחים הריהו משמש כמעבר בין שני הסולמות, ושני הסולמות משמשים איפוא למעשה כפתח.","\u0003אמר רב ביבי בר אביי: בנה איצטבא\u0004 מעץ \u0003על גב איצטבא\u0004 סמוך לכותל, \u0003אם יש באיצטבא התחתונה\u0004 אורך \u0003ארבעה\u0004 טפחים — \u0003ממעט\u0004 את גובהו של הכותל מעשרה טפחים. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם \u0003אין בתחתונה\u0004 אורך \u0003ארבעה\u0004 טפחים, \u0003ו\u0004אולם \u0003יש בעליונה ארבעה\u0004 טפחים, \u0003ואין בין זה לזה שלשה\u0004 טפחים — \u0003ממעט,\u0004 שנחשבות שתי האצטבאות כאחת וכמיעוט לכותל.","\u0003ואמר רב נחמן אמר רבה בר אבוה: סולם ששליבותיו פורחות,\u0004 שהשלבים שבו אינם מחוברים ביניהם כדרך מדרגות אלא מנותקים זה מזה, \u0003אם יש בשליבה התחתונה ארבעה\u0004 טפחים — \u0003ממעט\u0004 בכותל. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם \u0003אין בשליבה התחתונה ארבעה\u0004 טפחים \u0003ויש בשליבה העליונה ארבעה\u0004 טפחים, \u0003ואין בין זה לזה שלשה טפחים — ממעט,\u0004 שעל ידי דין לבוד נעשים שני השלבים כאחד.","\u0003ואמר רב נחמן אמר רבה בר אבוה:\u0004"],["\u0003זיז היוצא מן הכותל\u0004 ששטחו \u0003ארבעה על ארבעה\u0004 טפחים, \u0003והניח עליו סולם\u0004 שאין בין שלביו שלושה טפחים, אפילו רוחבו של הזיז \u0003כל שהוא — מיעטו\u0004 לכותל על ידי זיז וסולם זה.","ומסייגים את הדברים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא דאותביה עליה\u0004 \u0005[שהניחו עליו]\u0006 שהניח את הסולם על הזיז במישרין, ונעשה הסולם דרך להגיע אל הזיז, \u0003אבל אותביה בהדיה\u0004 \u0005[הניחו ליד\u0006 הזיז\u0005]\u0006 \u0003— ארווחי ארוחיה\u0004 \u0005[\u0006רק \u0005הרחיבו\u0006 את הזיז\u0005],\u0006 ואין הסולם נחשב כחלק מהזיז, וזיז שאינו בתוך שלושה לקרקע איננו ממעט את הכותל.","\u0003ואמר רב נחמן אמר רבה בר אבוה: כותל\u0004 שגובהו \u0003תשעה עשר\u0004 טפחים — \u0003צריך זיז אחד להתירו.\u0004 שאם יש זיז באמצעו, וסולם (אפילו רחבו כלשהו) נסמך עליו, הריהו כפתח, שהוא פחות מעשרה טפחים מראש הכותל ומתירו.","ואילו \u0003כותל\u0004 שגובהו \u0003עשרים\u0004 טפחים — \u0003צריך שני זיזים להתירו,\u0004 אחד בתוך עשרה טפחים מן הקרקע והשני בתוך עשרה טפחים מראש הכותל. \u0003אמר רב חסדא: והוא שהעמידן\u0004 את הזיזים \u0003זה שלא כנגד זה, שאפשר להניח סולם מזיז לזיז ולטפס.\u0004","\u0003אמר רב הונא:\u0004 היה \u0003עמוד ברשות הרבים, גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה,\u0004 שדינו כרשות היחיד, \u0003ונעץ בו\u0004 בראשו \u0003יתד כל שהוא — מיעטו.\u0004 שהרי השטח שאפשר להשתמש בו אינו עוד ארבעה טפחים אלא פחות מכן.","\u0003אמר רב אדא בר אהבה:\u0004 מה שנאמר בהלכה זו הוא רק אם \u0003גבוה שלשה,\u0004 כי פחות משלושה כלבוד הוא ומתבטל. \u0003אביי ורבא דאמרי תרוויהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אף על פי שאין גבוה שלשה,\u0004 ביטל היתד את העמוד מתורת רשות היחיד.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]:\u0006 \u0003לא\u0004 רגיל \u0003משתמש ליה\u0004 \u0005[להשתמש בו],\u0006 שהרי שטח של ארבעה על ארבעה טפחים ראוי לשימוש רק כשהוא ישר. ואם יש בו בליטה, אפילו היא פחותה משלושה טפחים, שוב אין המקום ראוי לשימוש.","\u0003רב אשי אמר: אפילו יתד גבוה שלשה\u0004 אינו ממעט, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]:\u0006 \u0003אפשר דתלי ביה מידי\u0004 \u0005[שתולה בו דבר].\u0006 שאף אם אין ראש העמוד ראוי עוד להניח עליו חפצים, הרי עדיין ראוי הוא לתלות בו, ויש בו אפשרות שימוש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 לשיטתך, אם \u0003מלאו כולו ביתדות מהו?\u0004 שאם נעץ בראש העמוד יתדות רבות ונתמלא כולו, מה דינו?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא שמיע לך הא\u0004 \u0005[שמעת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' יוחנן: בור וחולייתה מצטרף לעשרה,\u0004 שמחשיבים גם את עומק הבור וגם את החוליה (האבן שסביב לפתח הבור) ושניהם יחד מצטרפים לעומק עשרה טפחים. וכן רוחב הבור עם עובי החוליה מצטרפים יחד לכדי ארבעה טפחים כדי לעשותו לרשות היחיד.","והרי גם שם אפשר לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003הא לא משתמש ליה\u0004 \u0005[הרי איננו יכול להשתמש בו\u0006 בחולית הבור\u0005]\u0006 שהרי בה עצמה אינו יכול להניח כמעט דבר, שהרי רובה חללו של הבור? \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 \u0003דמנח מידי\u0004 \u0005[שמניח דבר]\u0006 כגון לוח על פתח הבור \u0003ומשתמש\u0004 בו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003דמנח מידי\u0004 \u0005[שמניח דבר]\u0006 על היתדות \u0003ומשתמש.\u0004","\u0003באמר רב יהודה אמר שמואל: כותל\u0004 שגובהו \u0003עשרה\u0004 טפחים — \u0003צריך סולם ארבעה עשר\u0004 טפחים כדי \u0003להתירו,\u0004 כדי שיעמידנו באלכסון. \u0003רב יוסף אמר: אפילו שלשה עשר ומשהו\u0004 דיו, שאם יגיע הסולם עד פחות מטפח קצה הכותל, אף זה ראוי.","\u0003אביי אמר: אפילו\u0004 היה אורך הסולם \u0003אחד עשר ומשהו,\u0004 עדיין יגיע קצהו, אם יועמד באלכסון, לפחות משלושה טפחים מראש הכותל, וראוי להשתמש בו.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אפילו\u0004 היה הסולם \u0003שבעה ומשהו\u0004 — מתיר, שאפשר להעמיד את הסולם זקוף ליד הכותל. וכיון שפחות משלושה טפחים מראש הכותל הרי זה לבוד, אף סולם זה נחשב כפתח.","וכעין זה \u0003אמר רב: סולם זקוף — ממעט\u0004 בכותל כפתח. ודבר זה \u0003גמרא, ולא ידענא מאי טעמא\u0004 \u0005[מסורת\u0006 היא בידי, \u0005ואיני יודע מה טעם\u0006 הדבר\u0005]\u0006 שהרי אין אנשים רגילים לעלות בסולם העומד בצורה כזו.","\u0003אמר שמואל: ולא ידע אבא טעמא דהא מלתא\u0004 \u0005[והאם אין אבא,\u0006 רב\u0005, יודע טעמו של דבר זה]?!\u0006 \u0003מידי דהוה\u0004 \u0005[הרי זה כמו שהוא\u0006 עושה\u0005]\u0006 \u0003איצטבא על גבי איצטבא,\u0004 שאף שאין קל לעלות, כיון שיש לו שלבים שאפשר לעלות בהם בדוחק — הרי זה כפתח.","\u0003אמר רבה אמר ר' חייא:\u0004 גזעי \u0003דקלים שבבבל,\u0004 שמניחם ליד כותל כדי לטפס עליהם — \u0003אין צריכים קבע\u0004 שיקבעם וידביקם לקרקע, והם ממעטים מיד. ו\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]:\u0006 \u0003כבידן קובעתן,\u0004 שמתוך כובדם, קשים הם לטלטול, ואף שעל פי דין מותרים הם בטלטול מכל מקום הריהם כקבועים ודבוקים.","\u0003ו\u0004בדומה לזה \u0003רב יוסף אמר\u0004 בשם \u0003ר' אושעיא: סולמות שבבבל — אינן צריכין קבע. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]:\u0006 \u0003כבידן קובעתן,\u0004 שסולמות אלה היו כרגיל גדולים וכבדים.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003סולמות\u0004 בבל אינם צריכים קבע, \u0003כל שכן דקלים\u0004 שמניחים אותם מלכתחילה לצורך זה, ודאי כקבועים הם שהם כבדים ביותר ואף אינם עשויים לטלטול. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003דקלים\u0004 אינם צריכים קבע, \u0003אבל סולמות — לא,\u0004 שסולם גם אם כבד, הוא עשוי לטלטול.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב יוסף מרבה:\u0004 היה \u0003סולם\u0004 צר פחות מארבעה טפחים \u0003מכאן\u0004 מצד אחד, \u0003וסולם\u0004 צר כעין זה \u0003מכאן\u0004 סמוך לו, \u0003וקשים\u0004 כעין שלבים ארוגים מקש שאי אפשר להניח רגל עליהם \u0003באמצע, מהו\u0004 הדין? האם על ידי כך יחשב הסולם כיחידה אחת ברוחב ארבעה טפחים, וסולם שרחבו ארבעה — ממעט?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין כף הרגל עולה בהם,\u0004 שדרכו של אדם להניח רגלו בסולם באמצע, וכיון שאמצע הסולם הזה עשוי קש, אף שנראה כרחב ארבעה, איננו ראוי — ואינו ממעט.","ושאלו: ואם יהיו \u0003קשין מכאן וקשין מכאן וסולם\u0004 צר \u0003באמצע,\u0004 ויחד רוחבם ארבעה טפחים, \u0003מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי כף הרגל עולה בהן,\u0004 וכיון שכף הרגל עולה בהם, והסולם נראה לעין רחב ארבעה — הרי הוא ממעט בכותל."],["\u0003חקק להשלים בכותל, בכמה?\u0004 שאם היה סולם פחות מארבעה טפחים, וחקק בתוך הכותל כעין המשך של השלבים עד לרוחב ארבעה, כמה צריך להיות גובה חקיקה זו אלה כדי שתחשב כפתח? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעשרה\u0004 טפחים, שאם יהיה גובהה עשרה טפחים ברוחב ארבעה הרי זה כפתח.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חקקו כולו בכותל, בכמה,\u0004 אם חקק את כל הסולם בכותל שיצר שלבים בכותל בלבד מה דינו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 צריך שיהיו שלבים אלה \u0003מלא קומתו\u0004 של הכותל. ושאלו: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה\u0006 זה\u0005]\u0006 שיש לעשותו גבוה יותר מתוספת חקוקה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003מסתלק ליה\u0004 \u0005[נוח לעלות עליו],\u0006 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא מסתלק ליה\u0004 \u0005[נוח לעלות עליו],\u0006 ואם אינו מגיע לקצה הכותל, אינו חשוב כפתח.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב יוסף מרבה: עשאו לאילן סולם מהו\u0004 הדין? שהרי אילן הצומח אסור לטפס עליו בשבת, ואם היה האילן סמוך לכותל ונוח לטפס עליו, האם נחשב הוא כפתח בכותל לענין דיני שבת?","ושאלה זו \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003רבי\u0004 האומר שכל הקונה עירוב תחומים באילן קנה שביתה, \u0003תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת \u0005חכמים]\u0006 ומפרטים: כיצד","\u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003רבי עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[\u0006ש\u0005אמר]\u0006 \u0003רבי התם\u0004 \u0005[שם]\u0006 (לעיל עירובין לב,ב): \u0003כל דבר שהוא משום שבות לא גזרו עליו\u0004 חכמים, ולכן אפשר לקנות עירוב גם אם היה מונח על אילן, שיש בשימוש בו משום שבות. ואולם יש לטעון כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 שהיה הדבר \u0003בין השמשות,\u0004 שהרי עירוב נקנה בין השמשות והוא עדיין ספק יום ספק לילה ויש להקל בו, \u0003אבל כולי יומא\u0004 \u0005[בכל היום\u0006 כולו\u0005]\u0006 — \u0003לא,\u0004 שלא יתיר רבי בעצם יום השבת אף דבר האסור משום שבות. וכיון שאילן זה אסור בשימוש כסולם — אין להחשיבו כפתח.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 האוסרים להשתמש באילן לצורך עירוב, אפשר לומר שלענייננו שאין צריך בשימוש בפועל באילן זה יסכימו כי \u0003פיתחא\u0004 \u0005[פתח]\u0006 \u0003הוא\u0004 בפועל, \u0003ואריא\u0004 \u0005[ו\u0006אולם \u0005אריה]\u0006 \u0003הוא דרביע עליה\u0004 \u0005[שרובץ עליו].\u0006 וכשם שאריה הרובץ בפתח אינו מבטלו מתורת פתח בשל כך, ואף שלמעשה לא יעבור איש בפתח זה, אם כן נוכל לומר גם באילן כי האיסור המוטל על הטיפוס בו איננו מבטל אותו מתורת פתח.","ועוד שאל רב יוסף: \u0003עשאו לאשירה\u0004 (עץ שנעשה לעבודה זרה, ואסור בהנאה) \u0003סולם מהו\u0004 הדין? האם יכול הוא להיחשב כפתח לכותל זה? ואף שאלה זו \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה, תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת \u0005חכמים]\u0006.","ומפרטים: כיצד \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' יהודה התם\u0004 \u0005[שם]\u0006 (לעיל עירובין לא,א) ש\u0003מותר לקנות\u0004 (כלומר, להשתמש) \u0003בית\u0004 לצורך עירוב \u0003באיסורי הנאה\u0004 כגון בקבר, \u0003אלא התם\u0004 \u0005[שם]\u0006 לענין קניית עירוב שם, \u0003דבתר\u0004 \u0005[שאחר]\u0006 ש\u0003קנה ליה\u0004 \u0005[לו]\u0006 \u0003עירוב לא ניחא ליה דלינטר\u0004 \u0005[נוח,\u0006 חשוב\u0005, לו שישמר],\u0006 שהרי אינו צריך להשתמש בקבר אלא רק לזכות בו לרגע של קניית העירוב. אבל כאן, שרוצה הוא בקיום הסולם, אפשר לומר שאף ר' יהודה מודה שאין סומכים על דבר שהוא איסור הנאה, שאסור לטפס עליו ולהשתמש בו.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אפילו ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 האוסרים בקבר כאן \u0003פיתחא\u0004 \u0005[פתח]\u0006 \u0003הוא, ואריא דרביע עליה\u0004 \u0005[ואריה\u0006 הוא \u0005שרובץ עליו]\u0006 ולא בטלו מלהיות פתח.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילן מותר, ואשירה אסורה. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: אדרבא\u0004 (להיפך), \u0003אילן שאיסור שבת גורם לו\u0004 להיאסר — \u0003ניתסר\u0004 \u0005[ייאסר],\u0006 כדי שלא נאמר שהאיסור משום שבת לא נתחשב באיסורו לענין דיני שבת.","ולהיפך, \u0003אשירה שאיסור דבר אחר גורם לו,\u0004 ואינו אסור משום דיני שבת — \u0003לא ניתסר\u0004 \u0005[ייאסר],\u0006 ופתח הוא לענין שבת.","ואכן \u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל, \u0003אמר ר' אלעזר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר ר' אבהו אמר ר' יוחנן: כל שאיסור שבת גרם לו — אסור, כל שאיסור דבר אחר גרם לו — מותר.\u0004","ואילו \u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[היה שונה כך]\u0006 לא כרב יוסף ששאלות אלה נכללות במחלוקות ידועות: \u0003אילן\u0004 אם פתח הוא או לא — \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003רבי ורבנן\u0004 \u0005[וחכמים],\u0006 שרבי מתיר וחכמים אוסרים. \u0003אשירה\u0004 אם פתח היא — \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003ר' יהודה\u0004 המתיר להשתמש באיסורי הנאה, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 האוסרים לעשות עירוב באיסורי הנאה.","\u0003חריץ שבין שתי חצירות, עמוק עשרה\u0004 טפחים \u0003ורוחב ארבעה\u0004 — הרי הוא מחיצה גמורה \u0003מערבין שנים\u0004 כל חצר עירוב לעצמה, \u0003ואין מערבין אחד. אפילו\u0004 היה החריץ \u0003מלא קש או תבן,\u0004 אין אלו נחשבים כסותמים אותו, ואין החריץ מתבטל. ואולם אם היה החריץ \u0003מלא עפר או צרורות\u0004 אבנים — \u0003מערבין אחד ואין מערבין שנים,\u0004 שבטל החריץ והריהו כלא היה.","\u0003נתן עליו\u0004 על החריץ \u0003נסר שרחב ארבעה טפחים\u0004 ואפשר לעבור בו, \u0003וכן שתי גזוזטראות זו כנגד זו\u0004 שנתן נסר רחב ארבעה ביניהן — \u0003מערבין שנים\u0004 עירובין, \u0003ואם רצו מערבין אחד,\u0004 שנסר זה משמש כפתח ומקום מעבר. \u0003פחות מכאן\u0004 אם רוחב הנסר פחות מארבעה טפחים — \u0003מערבין שנים ואין מערבין אחד.\u0004","על המשנה תוהים: \u0003ו\u0004כי \u0003תבן לא חייץ\u0004 \u0005[חוצץ]\u0006 ואינו נחשב כסתימה? \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003מתבן שבין שתי חצרות\u0004 והיה התבן \u0003גבוה עשרה טפחים — מערבין שנים ואין מערבין אחד\u0004 משמע שמחיצת תבן מחיצה היא!","\u0003אמר אביי,\u0004 כך יש להבין: \u0003לענין מחיצה כולי עלמא לא פליגי דהויא\u0004 \u0005[הכל אינם חולקים שהריהי]\u0006 \u0003מחיצה\u0004 והיא חוצצת בין חצר לחצר כל זמן שמונחת שם, \u0003אבל לענין חציצה\u0004 שתיחשב כסותמת את החריץ יש לחלק, \u0003אי בטליה\u0004 \u0005[אם בטלו]\u0006 בפיו במפורש והחליט להשאירו שם — \u0003חייץ\u0004 \u0005[חוצץ]\u0006 וסותם את החריץ, \u0003ואי לא בטליה\u0004 \u0005[ואם לא ביטלו]\u0006 ומתכוון להוציא את תבנו מן החריץ — \u0003לא חייץ\u0004 \u0005[חוצץ]\u0006 ואין החריץ נחשב כסתום.","נאמר במשנה שאם היה החריץ \u0003מלא עפר\u0004 או צרורות הרי הוא כסתום. ושואלים: \u0003ואפילו בסתמא\u0004 \u0005[בסתם]?\u0006 כלומר, האם גם אם לא פירש אם כוונתו להשאירם שם, תהא זו חציצה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בהלכות טומאת מת: \u0003בית שמלאהו תבן או צרורות ובטלו\u0004 שבטל את התבן או הצרורות והחליט להשאירם בבית — \u0003בטל\u0004 הבית (רמב\"ם), ושוב אין הבית נחשב כבית בעל מחיצות. ואם היה בו מת, שוב אינו יכול להיות כאהל הטומאה (שתוכו טמא אבל אינו מטמא סביביו), אלא נעשה כקבר סתום, המטמא מכל סביבותיו.","ונדייק מלשון המשנה: אם \u0003ביטלו\u0004 את התבן והצרורות — \u0003אין\u0004 \u0005[כן]\u0006 הרי הוא מבוטל וסותם,"],["\u0003לא ביטלו — לא,\u0004 והבית נדון כאהל אף שהתבן ממלאו. \u0003אמר רב הונא: מאן תנא\u0004 \u0005[מיהו\u0006 התנא ש\u0005שנה]\u0006 מסכת \u0003אהלות\u0004 — \u0003ר' יוסי היא\u0004 \u0005[הוא],\u0006 והתנא במשנתנו אינו מקבל שיטתו.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 דעת \u0003ר' יוסי\u0004 היא, הלוא \u0003איפכא שמעינן ליה\u0004 \u0005[ההיפך שמענו אותו\u0006 אומר\u0005]\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בתוספתא\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 בית מלא \u0003תבן, ואין עתיד לפנותו — הרי הוא\u0004 כמלא \u0003סתם עפר, ובטל.\u0004 ואילו בית מלא \u0003עפר, ועתיד לפנותו — הרי הוא כסתם תבן, ולא בטיל.\u0004 הרי שר' יוסי איננו מחלק לפי החומרים שבבית, אלא דן אם עתיד לפנותם אם לא!","\u0003אלא אמר רב אסי,\u0004 כך יש לומר: \u0003מאן תנא\u0004 \u0005[מיהו\u0006 התנא ש\u0005שנה]\u0006 מסכת \u0003עירובין\u0004 — \u0003ר' יוסי היא\u0004 \u0005[הוא],\u0006 ואינו מקבל דעת התנא במסכת אהלות.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 וכי מדיני \u0003טומאה\u0004 על דיני \u0003שבת קרמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 הלוא אין עניניהם שוים. \u0003הנח איסור שבת\u0004 שהרי לענין שבת, \u0003אפילו ארנקי נמי\u0004 \u0005[ארנק\u0006 מלא כסף \u0005גם כן]\u0006 \u0003מבטל איניש\u0004 \u0005[אדם],\u0006 שכן אסור הארנק בטלטול בשבת, וממילא נחשב כקבוע באותו מקום. ולעומת זאת התבן כיון שהוא ניטל אף בשבת, אינו חשוב קבוע בחריץ.","\u0003רב אשי אמר:\u0004 וכי מ\u0003בית\u0004 על \u0003חריץ קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003חריץ למיטיימיה קאי\u0004 \u0005[לסתום אותו הוא עומד],\u0006 וחזקה היא שמה שמניחים בתוכו ישאר שם, שהרי ודאי מתכוונים לסותמו. \u0003אלא בית, למיטיימיה קאי\u0004 \u0005[לסתום אותו הוא עומד]?\u0006 ומן הסתם יוציאו ממנו את התבן והעפר, ולכן יש צורך בהוכחה יתרה בבית שרוצים להשאיר את הבית מלא כדי לסותמו.","נאמר במשנה שאם \u0003נתן\u0004 על החריץ \u0003נסר שרוחב ארבעה\u0004 טפחים לו, הרי הוא כפתח. \u0003אמר רבא: לא שנו אלא שנתן\u0004 אורכו של הנסר \u0003לרחבו\u0004 של החריץ, \u0003אבל\u0004 אם נתן את אורכו של הנסר \u0003לארכו\u0004 של החריץ — \u0003אפילו\u0004 הנסר רחב \u0003כל שהוא נמי\u0004 \u0005[גם כן]\u0006 ממעט את החריץ, והריהו כפתח, \u0003שהרי מיעטו מארבעה.\u0004 שכן החריץ אינו רחב אלא ארבעה טפחים, ואם נתן לאורכו נסר רחב כלשהו, הרי שהוא עכשיו פחות מארבעה ואינו מהווה מחיצה.","נאמר גם: \u0003וכן\u0004 הדין ב\u0003שתי גזוזטראות זו כנגד זו. אמר רבא: הא דאמרת\u0004 \u0005[זו שאומר אתה\u0006 בהלכה זו\u0005]\u0006 \u0003זו שכנגד זו — אין\u0004 \u0005[כן]\u0006 ניתרת על ידי נסר, \u0003וזו שלא כנגד זו — לא\u0004 ניתרת, \u0003וזו למעלה מזו נמי\u0004 \u0005[גם כן]. .\u0006 שכן גם על ידי נסר קשה ללכת שם מפני הסכנה, ואין זה חשוב כפתח. \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא כשיש בין זה לזה\u0004 בגובה \u0003שלשה\u0004 טפחים, \u0003אבל\u0004 אם \u0003אין בין זה לזה שלשה\u0004 אין מחלקים \u0003וגזוזטרא עקומה היא,\u0004 שכל שהוא פחות משלושה טפחים דינו כלבוד, וההפרש הזה כאילו אינו.","\u0003מתבן\u0004 (ערימת תבן צבורה ומונחת) \u0003שבין שתי חצירות,\u0004 אם המתבן \u0003גבוה עשרה טפחים\u0004 — הריהו כמחיצה, \u0003ומערבין\u0004 בחצירות \u0003שנים\u0004 (שני עירובין) \u0003ואין מערבין אחד. אלו,\u0004 בני חצר זו \u0003מאכילין\u0004 בהמתן \u0003מכאן,\u0004 מצדו האחד של המתבן. \u0003ואלו, מאכילין מכאן.\u0004 ואין חוששים שמא יתמעט ושוב לא יהיה כמחיצה. ואם \u0003נתמעט התבן מ\u0004גובה \u0003עשרה טפחים\u0004 לכל אורכו — שוב אינו מחיצה, ולכן \u0003מערבין\u0004 עירוב \u0003אחד, ואין מערבין שנים.\u0004","על מה שנאמר במשנה שבני שתי החצירות רשאים להעמיד בהמותיהם ליד המתבן ולהאכילן, \u0003אמר רב הונא: ובלבד שלא יתן לתוך קופתו\u0004 (סלו) בידים \u0003ויאכיל,\u0004 כי יש לחשוש שמא יתמעט גובה התבן מעשרה טפחים, ותפרץ חצר אחת לחברתה, ונמצא מטלטל בחצר שאין בה עירוב.","ושואלים, אם כן שאין לטלטל בידים תבן זה, יש לשאול: \u0003ולאוקמי שרי\u0004 \u0005[ו\u0006כי \u0005להעמיד\u0006 בהמה על גבי התבן \u0005מותר]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא אמר ר' חנינא: מעמיד אדם את בהמתו על גבי עשבים בשבת,\u0004 ואין חוששים שמא הוא עצמו יבוא לקטוף לבהמה עשבים, שבשל האיסור החמור שמדברי תורה ודאי לא ישכח ולא יעשה כן. אבל \u0003אין אדם מעמיד את בהמתו על גבי מוקצה בשבת.\u0004 כי מחמת שאיסור המוקצה הוא מדברי חכמים בלבד, שמא ישכח ויבוא לטלטל בעצמו את המוקצה. וכן בענייננו, שאם אסור מדברי חכמים לקחת מן המתבן בידים, אסור אף להעמיד את הבהמה.","ומתרצים שאין מדובר שמעמיד את הבהמה שם ממש אלא \u0003דקאים לה באפה\u0004 \u0005[שעומד בפניה]\u0006 כשרוצה לילך למקום אחר \u0003ו\u0004ממילא \u0003אזלה ואכלה\u0004 \u0005[הולכת\u0006 בעצמה \u0005ואוכלת]\u0006 מן המתבן, ועל כך לא גזרו חכמים.","על עיקר דברי רב הונא שואלים: \u0003ולא יתן לתוך קופתו תבן? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית\u0004 שהיה \u0003בין שתי חצירות\u0004 ופתוחים לו שני בתים אחרים \u0003ומילאהו תבן — מערבין שנים ואין מערבין אחד,\u0004 שהתבן נחשב כמחיצה בתוך הבית. \u0003זה נותן לתוך קופתו ויאכיל\u0004 לבהמתו, \u0003וזה נותן לתוך קופתו ויאכיל.\u0004 ואם \u0003נתמעט התבן מעשרה טפחים — שניהם אסורים.\u0004","\u0003כיצד הוא עושה?\u0004 להתיר את השימוש לאחד מהם לבדו — \u0003נועל\u0004 אחד מהם \u0003את ביתו\u0004 בפתח הפתוח לבית האמצעי \u0003ומבטל את רשותו\u0004 לחבירו, ואז \u0003הוא אסור\u0004 להוציא מביתו לחצר \u0003וחבירו מותר.\u0004","\u0003וכן אתה אומר\u0004 כעין הלכה זו \u0003בגוב\u0004 (בבור) \u0003של תבן ש\u0004נמצא \u0003בין שני תחומי שבת,\u0004 שבני כל תחום יכולים להאכיל בהמותיהם מן התבן המשותף, ואין חוששים שמא יצאו מתחומם. \u0003קתני מיהת\u0004 \u0005[שנינו מכל מקום]:\u0006 \u0003זה נותן לתוך קופתו ויאכיל, וזה נותן לתוך קופתו ויאכיל.\u0004 וקשה לדברי רב הונא!","ומתרצים \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003בית, כיון דאיכא\u0004 \u0005[שיש בו]\u0006 \u0003מחיצות ותקרה, כי מיפחית\u0004 \u0005[כאשר מתמעט]\u0006 התבן מגובהו \u0005—\u0006 \u0003מינכרא ליה מלתא\u0004 \u0005[ניכר לו הדבר],\u0006 שהכל רואים את הבדל הגובה בהשוואה לתקרה, ולכשיתמעט מגובה עשרה ימנעו מליטול עוד. \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003לא מינכרא ליה מלתא\u0004 \u0005[ניכר לו הדבר],\u0006 ועשוי התבן להתמעט ותתבטל המחיצה מבלי משים.","נאמר בברייתא שאם \u0003נתמעט התבן\u0004 שבבית \u0003מעשרה טפחים שניהן אסורין.\u0004 ונדייק מלשון הברייתא: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה התבן \u0003עשרה\u0004 לפחות — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003ואף על גב דמידליא\u0004 \u0005[ואף על פי שגבוהה]\u0006 ה\u0003תקרה טובא\u0004 \u0005[הרבה]\u0006 מעל לתבן זה. \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מחיצות שאין מגיעות לתקרה — שמן מחיצות.\u0004 והרי נחלקו חכמים בבעיה זו אם מחיצות עשרה שאינן מגיעות לתקרה קרויות מחיצות (לעיל עירובין עב,א), ולכאורה מכאן ראיה שמחיצות הן לכל דבר!","\u0003אמר אביי: הכא\u0004 \u0005[כאן]\u0006 מדובר במקרה מיוחד; \u0003בבית\u0004 שגובהו \u0003שלשה עשר\u0004 טפחים \u0003חסר משהו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ותבן\u0004 שגובהו \u0003עשרה.\u0004 וכיון שבין ראש ערימת התבן והתקרה יש פחות משלושה טפחים, הרי כל הפחות משלושה טפחים לבוד הוא, וכאילו מגיעות המחיצות לתקרה.","\u0003ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003בבית\u0004 שגובהו \u0003עשרה\u0004 טפחים"],["\u0003ותבן\u0004 שבבית גובהו \u0003שבעה ומשהו\u0004 טפחים, וכיון ש\u0003כל פחות משלשה\u0004 טפחים \u0003כלבוד דמי\u0004 \u0005[נחשב],\u0006 הרי זו כמחיצה גמורה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 — \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]:\u0006 נתמעט התבן \u0003מעשרה, אלא לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003מעשרה?\u0004 הלוא מתחילה לא היו כאן עשרה!","ומתרצים: הכוונה היא \u0003מתורת עשרה,\u0004 שכל עוד התבן גבוה שבעה ומשהו, הריהו כגבוה עשרה מדין לבוד. ואם נתמעט, נתמעט מתורת מחיצה גבוהה עשרה.","באותה ברייתא נאמר שאם נתמעט התבן מעשרה \u0003שניהן אסורין.\u0004 ומעירים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 כי \u0003דיורין הבאין בשבת אסורין,\u0004 שהרי מתחילת השבת מותר היה לשני הדיירים להשתמש בתבן ובבית. וביום השבת, כיון שנתמעט התבן, נוספו כאילו דיירים חדשים לכל אחד מהבתים, ונאסרו הכל. ולכאורה מדוע לא נאמר שכיון שהותרה בתחילת השבת, הותרה לכולה?","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003דאימעט\u0004 \u0005[שהתמעט]\u0006 התבן \u0003מאתמול\u0004 עוד מלפני השבת, ובכגון זה לא הותרה כלל.","אמרו: \u0003כיצד הוא עושה נועל את ביתו ומבטל את רשותו.\u0004 ותוהים: \u0003תרתי\u0004 \u0005[שתים]?!\u0006 כלומר למה לו לעשות שני דברים אלה יחד? די באחד מהם! ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה הכוונה\u0005]:\u0006 \u0003או נועל את ביתו או מבטל את רשותו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 הסבר אחר\u0005]:\u0006 \u0003לעולם\u0004 תפרש ש\u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 צריך שיעשה כאן, אף שכרגיל די באחד, כי \u0003כיון דדש ביה\u0004 \u0005[שרגיל בו\u0006 בשימושו\u0005] —\u0006 \u0003אתי לטלטולי\u0004 \u0005[יבוא לטלטל],\u0006 והחמירו בו שיעשה תיקון יתר על הרגיל שלא ישכח ויבוא לטלטל.","נאמר שאם ביטל — \u0003הוא אסור וחבירו מותר.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[\u0006הלוא \u0005פשוט\u0006 הדבר ומובן מאליו\u0005]\u0006 ולשם מה יש לומר זאת? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דהדר אידך ובטיל ליה לחבריה\u0004 \u0005[שחזר האחר וביטל לו לחבירו]\u0006 בחזרה אחרי שהשתמש בה כרצונו, \u0003והא קא משמע לן\u0004 \u0005[זה משמיע לנו]\u0006 ש\u0003אין מבטלין, וחוזרין ומבטלין\u0004 אותה רשות פעם שניה.","נאמר: ש\u0003כן אתה אומר בגוב של תבן שבין שני תחומי שבת.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[\u0006הלוא \u0005פשוט\u0006 הוא\u0005]\u0006 ואותו עקרון קיים גם שם כבמתבן בין חצירות! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003ל\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר:\u0004 דין \u0003תחומין דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליגזור דלמא אתי לאיחלופי\u0004 \u0005[שנגזור\u0006 ונאסור \u0005שמא יבואו להחליף]\u0006 לקחת דברים מתחום אל תחום, שכיון שעיקר האיסור מן התורה ראוי שיוסיפו בו חכמים גזירות לשמרו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת אין לחלק, ואין גוזרים.","\u0003כיצד משתתפין במבוי\u0004 אם רוצה אדם אחד לזכות את כל בני המבוי? \u0003מניח את החבית\u0004 המלאה אוכל משלו, \u0003ואומר: הרי זו לכל בני מבוי,\u0004 וכדי שתהא זו נתינה המזכה את האחרים צריך שיהא מי שיזכה בחבית זו עבורם, \u0003ומזכה להם על ידי בנו ובתו הגדולים\u0004 (הבוגרים), \u0003ו\u0004כן \u0003על ידי עבדו ושפחתו העברים\u0004 (שאין גופם קנוי לו), \u0003ו\u0004כן \u0003על ידי אשתו,\u0004 והם זוכים לכל בני המבוי.","\u0003אבל אינו מזכה לא על ידי בנו ובתו הקטנים, ולא על ידי עבדו ושפחתו הכנענים, מפני ש\u0004אין להם זכות קנין, והרי \u0003ידם כידו\u0004 (רשותם כרשותו), ואינם יכולים לזכות אחרים. שהרי גם כשנותן להם נותר החפץ ברשותו, שרשותם כרשותו ממש.","\u0003אמר רב יהודה: חבית של שיתופי מבואות — צריך\u0004 הזוכה \u0003להגביה\u0004 אותה \u0003מן הקרקע טפח,\u0004 שעל ידי כך כאילו מוציאה הזוכה מרשות המזכה, שלולי כן אינו יכול לזכותה לאחרים.","\u0003אמר רבא: הני תרתי מילי\u0004 \u0005[שני דברים אלה],\u0006 \u0003סבי\u0004 \u0005[זקני]\u0006 \u0003פומבדיתא,\u0004 רב יהודה ובני ישיבתו, \u0003אמרינהו\u0004 \u0005[אמרוהו]:\u0006 \u0003חדא\u0004 \u0005[אחד] —\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו בענין הגבהת חבית. \u0003אידך\u0004 \u0005[השניה]\u0006 — ששנינו \u0003המקדש\u0004 על היין בשבת או בחג, \u0003אם טעם\u0004 מן היין \u0003מלא לוגמיו — יצא\u0004 ידי חובת קידוש, \u0003ואם לאו — לא יצא.\u0004","\u0003אמר רב חביבא: הא נמי סבי דפומבדיתא אמרינהו\u0004 \u0005[דבר זה\u0006 נוסף לשניים שאמרנו \u0005גם כן זקני פומבדיתא אמרוהו],\u0006 שכן \u0003אמר רב יהודה אמר שמואל: עושין מדורה לחיה\u0004 \u0005[ליולדת]\u0006 \u0003בשבת.\u0004","ומעירים: \u0003סבור מינה\u0004 \u0005[סברו מכאן]\u0006 מלשון הלכה זו כי \u0003לחיה — אין\u0004 \u0005[כן]\u0006 מותר לעשות משום שהיא מסוכנת ביותר, אולם \u0003לחולה\u0004 סתם — \u0003לא. בימות הגשמים\u0004 שברורה סכנת ההצטננות \u0003אין\u0004 \u0005[כן],\u0006 \u0003בימות החמה — לא.\u0004","ולכן יש להוסיף מה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 \u0003אמר רב חייא בר אבין אמר שמואל:\u0004 מי ש\u0003הקיז דם ונצטנן — עושין לו מדורה בשבת, ואפלו בתקופת תמוז.\u0004 משמע שלאו דוקא יולדת, ולאו דוקא בימות הגשמים.","\u0003אמר אמימר: הא נמי סבי דפומבדיתא אמרינהו\u0004 \u0005[ודבר\u0006 נוסף זה \u0005גם כן זקני פומבדיתא אמרוהו]\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בדבר \u0003איזו היא אשירה סתם,\u0004 כלומר איזהו האילן הנחשב כעץ המשמש לעבודה זרה, אף שאין אנו רואים שעובדים לו ממש?","\u0003אמר רב: כל\u0004 אילן \u0003שכומרין שומרין אותה\u0004"],["\u0003ואין טועמין מפירותיה,\u0004 הרי זו הוכחה שהיא מקודשת לפולחן.","\u0003ושמואל אמר: כגון דאמרי \"הני תמרי לשיכרא דבי ניצרפי דשתו ליה\u0004 \u0005[אלה התמרים לשיכר\u0006 של בית עבודה זרה \u0005ששותים אותו]\u0006 \u0003ביום חגם\",\u0004 ודבר זה דיו לדון את האילן כדין אשירה. \u0003אמר אמימר: ואמרו לי סבי\u0004 \u0005[זקני]\u0006 \u0003פומבדיתא\u0004 לענין זה: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003שמואל.\u0004","על דברי רב יהודה בענין הגבהת חבית (ר\"ח). \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003כיצד משתתפין במבוי — מביאים חבית של יין ו\u0004כן \u0003של שמן ו\u0004כן \u0003של תמרים ו\u0004כן \u0003של גרוגרות ו\u0004כן \u0003של שאר מיני פירות\u0004 לצורך השיתוף.","ו\u0003אם\u0004 נתן את החבית \u0003משלו — צריך לזכות\u0004 לכולם על ידי אחר. \u0003ואם משלהן — צריך\u0004 על כל פנים \u0003להודיע\u0004 להם שהוא עושה את השיתוף. \u0003ומגביה מן הקרקע משהו\u0004 כדי לזכות לאחרים. הרי שאין צורך להגביה טפח! ומתרצים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"משהו\" נמי דקאמר\u0004 \u0005[\u0006זה \u0005שאמר גם כן\u0006 משמעו\u0005]\u0006 \u0003טפח\u0004 ולא פחות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בנושא \u0003שיתופי מבואות, רב אמר: אין צריך לזכות\u0004 לכולם על ידי אחר, וכל אחד מבני המבוי נעשה שותף מעצמו. \u0003ושמואל אמר: צריך לזכות\u0004 במעשה של הקנאה. וכן נחלקו ב\u0003עירובי תחומין, רב אמר: צריך לזכות, ושמואל אמר: אין צריך לזכות.\u0004","ומקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003שמואל\u0004 אפשר להבין את דבריו כי \u0003הכא\u0004 \u0005[כאן]\u0006 בדין שיתופי מבואות \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שצריך לזכות, \u0003והכא\u0004 \u0005[וכאן]\u0006 בדיני עירובי תחומין \u0003לא תנן\u0004 \u0005[שנינו].\u0006 \u0003אלא לרב מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לחלק כך בין הדברים?","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בנושא זה, וכן מסופר ש\u0003אמר רב יהודה אמר רב: מעשה בכלתו של ר' אושעיא שהלכה\u0004 מבעוד יום \u0003לבית המרחץ\u0004 שהיה מחוץ לתחום, \u0003וחשכה לה\u0004 שהגיעה השבת לפני שיכלה לחזור. \u0003ועירבה לה חמותה\u0004 עירובי תחומין עבורה, שתוכל לחזור לביתה.","\u0003ובא מעשה לפני ר' חייא\u0004 לשאול אם אפשר לסמוך על עירוב זה — \u0003ואסר. אמר לו ר' ישמעאל בר' יוסי: בבלאי\u0004 \u0005[בבלי],\u0006 \u0003כל כך אתה מחמיר בעירובין?! כך אמר אבא: כל שיש לך להקל בעירובין — הקל.\u0004","\u0003ואבעיא להו\u0004 \u0005[ונשאלה להם\u0006 ללומדים שאלה זו\u0005]\u0006 האם \u0003משל חמותה עירבה לה,\u0004 וטעמו של ר' חייא שאסר היה \u0003משום\u0004 ש\u0003לא זיכתה לה.\u0004 וכיון שלא היה זיכוי אלא עירוב בלבד — אין העירוב קונה בלא זיכוי. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משלה,\u0004 משל הכלה, \u0003עירבה לה,\u0004 ולא הועיל העירוב \u0003משום\u0004 שנעשה \u0003שלא מדעתה?\u0004","\u0003אמר להן ההוא מרבנן\u0004 \u0005[אחד מהחכמים],\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003לדידי מיפרשא לה מיניה\u0004 \u0005[לי עצמי נתפרש לו\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוחנן\u0004 ש\u0003משל חמותה עירבה, ומשום\u0004 ש\u0003לא זיכתה לה\u0004 אסר ר' חייא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' יעקב בריה [בנה]\u0004 של \u0003בת יעקב: כי מטית התם\u0004 \u0005[כשתבוא לשם\u0006 לארץ ישראל\u0005]\u0006 \u0003אקיף\u0004 \u0005[הקף]\u0006 את הדרך, שלא תלך בדרך הקצרה ביותר \u0003וזיל לסולמא\u0004 \u0005[ולך לסולם]\u0006 \u0003צור, ובעית מיניה\u0004 \u0005[ושאל ממנו]\u0006 \u0003מרב יעקב בר אידי\u0004 ענין זה.","ואכן, כך עשה ו\u0003בעא מיניה\u0004 \u0005[שאל ממנו]:\u0006 האם באותו מעשה \u0003משל חמותה עירבה, ומשום\u0004 ש\u0003לא זיכתה לה\u0004 אסר ר' חייא, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משלה עירבה, ומשום\u0004 שנעשה \u0003שלא מדעתה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משל חמותה עירבה לה, ומשום\u0004 ש\u0003לא זיכתה לה\u0004 אסר ר' חייא. ורב סבור כדעת רבו ודודו ר' חייא, ואף הוא סבר שבעירוב תחומין יש לזכות.","\u0003אמר רב נחמן נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 בהלכה פסוקה זו: \u0003אחד עירובי תחומין ואחד עירובי חצירות אחד שיתופי מבואות — צריך לזכות.\u0004 ולאחר שאמר דבר ברור זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב נחמן\u0004 דבר שלא היה ברור לו כל צורכו: האם \u0003עירובי תבשילין\u0004 שעושים כדי להתיר לבשל ביום טוב לצורך שבת שלאחריו \u0003צריך לזכות\u0004 לכל אלו שיאכלו מתבשיל זה, \u0003או אין צריך לזכות?\u0004","\u0003אמר רב יוסף: ומאי תיבעי ליה\u0004 \u0005[ומה תישאל לו]\u0006 בענין זה, וכי \u0003לא שמיע ליה הא\u0004 \u0005[שמע\u0006 דבר \u0005זה]\u0006 ש\u0003אמר ר' נחמן בר רב אדא אמר שמואל: עירובי תבשילין צריך לזכות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 ש\u0003לא שמיע ליה\u0004 \u0005[שמע אותה\u0006 הלכה\u0005]\u0006. \u0003דאי שמיע ליה, מאי תיבעי ליה\u0004 \u0005[שאם שמע אותה, מה נסתפק לו]\u0006 \u0003מה היא ההלכה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו\u0004 \u0005[וכי]\u0006 ב\u0003עירובי תחומין מי\u0004 \u0005[האם]\u0006 \u0003לא אמר שמואל אין צריך לזכות, ואמר איהו\u0004 \u0005[הוא]\u0006 בכל זאת ש\u0003צריך לזכות,\u0004 ושמא אף כאן אין רב נחמן מקבל את פסקו של שמואל.","אמר לו אביי: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בשיתוף מבואות ועירובי תחומין \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003רב ושמואל, וקא משמע לן כחומרין דמר, וכי חומרין דמר\u0004 \u0005[והשמיע לנו\u0006 שהלכה \u0005כחומרתו של זה, וכחומרתו של זה]\u0006 שסומך על שתי הדעות כאחת \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בענין עירוב תבשילין, \u0003אי איתא דשמיע ליה מי איכא דמאן דפליג\u0004 \u0005[אם אמנם שמע\u0006 את ההלכה \u0005האם יש מי שחלק]\u0006 בכך? ומן הסתם אם אומר אחד מרבותיו פסק הלכה שאין אחרים חולקים עליו, הלכה פסוקה היא.","\u0003ההוא טורזינא דהוה בשיבבותיה\u0004 \u0005[אותו פקיד\u0006 גוי \u0005שהיה בשכנותו]\u0006 של \u0003ר' זירא, אמרו ליה\u0004 \u0005[לו]\u0006 השכנים: \u0003אוגיר לן\u0004 \u0005[השכר לנו]\u0006 את \u0003רשותך\u0004 לצורך טלטול בשבת, \u0003לא אוגיר להו\u0004 \u0005[השכיר להם].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' זירא אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מהו\u0004 הדין, האם מותר \u0003למיגר מדביתהו\u0004 \u0005[לשכור מאשתו]\u0006 שלא מדעת בעלה?","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ריש לקיש משמיה דגברא רבה\u0004 \u0005[משמו של אדם גדול],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]\u0006 \u0003ר' חנינא: אשתו של אדם מערבת שלא מדעתו.\u0004 ולפי עקרון זה, יכולה אשת הפקיד להשכיר שלא מדעתו.","כעין זה מסופר: \u0003ההוא טורזינא דהוה בשיבבותיה\u0004 \u0005[אותו פקיד שהיה בשכנותו]\u0006 של \u0003רב יהודה בר אושעיא, אמרי ליה\u0004 \u0005[אמרו לו]\u0006 השכנים: \u0003אוגר לן\u0004 \u0005[השכר לנו]\u0006 את \u0003רשותך\u0004 לצורך טלטול בשבת, \u0003לא אוגר להו\u0004 \u0005[השכיר להם].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב יהודה בר אושעיא, אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003מהו למיגר מדביתהו\u0004 \u0005[לשכור מאשתו],\u0006 \u0003ולא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב מתנא, לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב יהודה, אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אשתו של אדם מערבת שלא מדעתו,\u0004 ואף בהשכרה כן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 שנינו: \u0003נשים שעירבו ונשתתפו שלא מדעת בעליהן — אין עירובן עירוב, ואין שיתופן שתוף!\u0004 וכיצד פסק שמואל היפך דברים אלה?","ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 כשאמר שמואל שאשתו מערבת שלא מדעתו — הרי זה במקרה ש\u0003אסר\u0004 על שכניו אם לא עירב עימם, ואז מקילים אנו ואומרים שאף אשתו רשאית לערב עבורו. \u0003הא\u0004 \u0005[כאן]\u0006 שאין אשתו רשאית לערב שלא מדעתו — מדובר כ\u0003שלא אסר\u0004 על אחרים.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שיש להבין את הדברים כך, ש\u0003אם כן קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003שמואל\u0004 על דברי \u0003שמואל\u0004 עצמו, ש\u0003אמר שמואל: אחד מבני מבוי שרגיל להשתתף עם בני מבוי, ולא נשתתף\u0004 שבת אחת — \u0003בני המבוי נכנסין לתוך ביתו ונוטלין שיתופן ממנו בעל כרחו.\u0004","ונדייק מכאן: \u0003רגיל — אין\u0004 \u0005[כן],\u0006 אבל \u0003שאין רגיל — לא,\u0004 הרי שלא בכל מקרה אפשר לשתף אדם שלא מדעתו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם\u0006 נוכל \u0005לסייע לו]\u0006 ממה ששנינו: כל הדר במבוי \u0003כופין אותו לעשות לחי וקורה למבוי,\u0004 הרי שלצורך תיקון לשבת אין מתחשבים בדעתו ואפשר לעשות אפילו על ידי כפיה."],["\u0003שאני התם דליכא\u0004 \u0005[שונה שם שאין]\u0006 \u0003מחיצות,\u0004 כלומר אותו מבוי פרוץ הוא, וראוי לכפות את דייריו לעשות בו מחיצות כל שהן, אפילו לצורך שמירה. אבל כשיש מחיצות, אין מחייבים אותו ביותר מכך.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר],\u0006 \u0003מצד שאני\u0004 \u0005[שונה],\u0006 שתיקון בעירוב אינו תיקון בגוף המבוי אלא בדבר צדדי, ולכן אין כופין בו את היחיד (מאיר נתיב).","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנושא זה; ש\u0003ר' חייא בר אשי אמר: עושין לחי\u0004 מעצי \u0003אשירה,\u0004 אף שהעץ אסור בהנאה ועומד לשריפה בלבד, כי בעצם עשיית הלחי יש צד של מצוה ואין איסור הנאה שייך בענין מצוה. \u0003ור' שמעון בן לקיש אמר: עושין\u0004 אפילו \u0003קורה\u0004 מעצי \u0003אשירה.\u0004","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שעושים \u0003קורה — כל שכן לחי, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003לחי — אבל קורה לא\u0004 התיר. משום שבאיסור עצי אשירה \u0003כתותי מכתת שיעוריה\u0004 \u0005[כתות הוא שיעורו],\u0006 שכיון שהעץ עומד לשריפה הריהו כשרוף כבר, ואין לעשות ממנו קורה הצריכה לשיעור רוחב מסוים. אבל לחי שדי לו ברוחב כל שהוא — אפילו עצי אשירה, שהם כשרופים — ראויים.","\u0003נתמעט האוכל\u0004 שהיה בחבית השיתוף משיעורו — \u0003מוסיף\u0004 מקצת משלו \u0003ומזכה\u0004 לרבים. \u0003ואין צריך להודיע\u0004 להם שהוסיף. ואולם אם \u0003נתוספו עליהן\u0004 דיורים חדשים — \u0003מוסיף\u0004 לצורך אותם דיורים \u0003ומזכה\u0004 להם, \u0003וצריך להודיע\u0004 לדיירים החדשים שזיכה אף להם שיתוף זה.","\u0003כמה הוא שיעורן\u0004 של המזונות לשיתוף? \u0003בזמן שהן\u0004 (בני המבוי) \u0003מרובין\u0004 — די ב\u0003מזון שתי סעודות\u0004 עבור \u0003כולם, בזמן שהן מועטין\u0004 ממספר מסויים — די במזון \u0003כגרוגרת לכל אחד ואחד.\u0004","\u0003אמר ר' יוסי: במה דברים אמורים\u0004 שצריכים שיעורים אלה, \u0003בתחילת עירוב,\u0004 כשעושין אותו לכתחילה, \u0003אבל בשירי עירוב\u0004 כגון שנתמעט העירוב בשבת הריהו כשר \u0003בכל שהוא. ו\u0004בכלל,","\u0003לא אמרו לערב בחצירות\u0004 אף ששיתפו במבואות \u0003אלא כדי שלא לשכח את התינוקות,\u0004 כדי שיידעו שעושים עירובי חצירות, שאם לא כן לא ידעו כלל הלכה זו.","במשנה נאמר שאם נתמעט מזון השיתוף, אין המוסיף צריך להודיע. ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה\u0006 באיזה מקרה \u0005עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003במין אחד,\u0004 שהוא מוסיף מאותו מין שעירבו בו תחילה, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע שנה דוקא\u0005]\u0006 \u0003נתמעט אפילו כלה\u0004 מזון זה לגמרי \u0003נמי\u0004 \u0005[גם כן]\u0006 אינו צריך להודיע!","\u0003אלא\u0004 תאמר שמדובר \u0003בשני מינין,\u0004 שמוסיף ממין אחר שלא שיתפו בו בתחילה, אם כן \u0003אפילו נתמעט נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יועיל בלא שיודיעום! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלה האוכל\u0004 של שיתוף, אם הוסיף עליו \u0003ממין אחד\u0004 — \u0003אין צריך להודיע, משני מינים — צריך להודיע!\u0004","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר במשנתנו שמוסיף \u0003ממין אחד, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003משני מינין.\u0004 וכך יש להסביר: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כשהוסיף \u0003ממין אחד,\u0004 ואולם \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003נתמעט — נתמטמט\u0004 לגמרי ולא נשאר מאומה, שכוונת נתמטמט פירושה שהלך ונתמעט עד שכלה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 שהוסיף \u0003משני מינים,\u0004 אלא אם \u0003כלה\u0004 העירוב \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005]\u0006 שהלכה זו שיש להודיע היא רק אם כלה האוכל לגמרי, אבל אם נשאר משהו אין צורך להודיע, ויכול לזכות אפילו ממין שני, ואם כן אין ללמוד מן הברייתא לענייננו.","נאמר במשנה שאם \u0003נתוספו\u0004 דיירים \u0003עליהן\u0004 בחצר \u0003מוסיף ומזכה\u0004 וצריך להודיע. \u0003אמר רב שיזבי אמר רב חסדא: זאת אומרת\u0004 מכלל דברי המשנה כי \u0003חלוקין עליו חביריו על ר' יהודה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יהודה: במה דברים אמורים\u0004 שצריך דעתו של הזוכה בעירוב \u0003בעירובי תחומין, אבל בעירובי חצירות — מערבין בין לדעת ובין שלא לדעת,\u0004 ולדברי המשנה מוסיף אף שלא מדעת. ותוהים: הלוא \u0003פשיטא\u0004 \u0005[פשוט\u0006 ברור\u0005]\u0006 ש\u0003חלוקין,\u0004 ומה ראה רב חסדא להודיענו דבר הברור לכול?","ומשיבים: בכל זאת נצרכה, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שצריך להודיע נאמרו \u0003בחצר שבין שני מבואות\u0004 שיכולים בני חצר זו לערב עם איזה מבוי שירצה. וצריך להודיעם באיזה מבוי שיתפו עבורם, שמא רצונם דוקא לערב עם המבוי האחר. \u0003אבל חצר של מבוי אחד\u0004 שרק זכות הוא להם השיתוף, ואין בכך צד חובה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שאף החכמים במשנתנו מסכימים שאין צריך להודיע. על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב חסדא שדעת משנתנו שיש להודיע בכל מקרה.","במשנה נקבע \u0003כמה הוא שעורו\u0004 של עירוב למרובים וכמה למועטים. ושאלו: \u0003כמה הוא\u0004 מניינם של \u0003מרובין\u0004 וכמה של מועטים? \u0003אמר רב יהודה אמר שמואל: שמונה עשרה בני אדם\u0004 אלה הם מרובים. ותוהים: \u0003שמונה עשרה, ותו לא\u0004 \u0005[ולא יותר]\u0006 ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003משמונה עשר ואילך\u0004 (והלאה).","ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003שמונה עשר\u0004 ש\u0003נקט\u0004 (תפס), מדוע דוקא מספר זה? ומשיבים: \u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: לדידי מיפרשא לי מיניה דאבא\u0004 \u0005[לי התפרש הדבר ממנו, מאבי\u0006 רב יהודה\u0005]:\u0006 \u0003כל שאילו מחלקו למזון שתי סעודות ביניהן ואין מגעת גרוגרת לכל אחד ואחד הן הן מרובין, ו\u0004אז \u0003סגי\u0004 \u0005[די]\u0006 \u0003במזון שתי סעודות. ואי\u0004 \u0005[ואם]\u0006 \u0003לא — הן הן מועטין נינהו\u0004 \u0005[הם],\u0006 וצריך שיהיה כגרוגרת לכל אחד.","\u0003ואגב אורחיה קא משמע לן\u0004 \u0005[ודרך אגב הוא משמיע לנו]\u0006 \u0003ששתי סעודות הויין\u0004 \u0005[הריהן]\u0006 \u0003שמונה עשרה גרוגרות,\u0004 ולכן אם היו יותר דיורים, דיים בשמונה עשרה גרוגרות שהוא מזון שתי סעודות.","בכל מזון שהוא \u0003מערבין ומשתתפין, חוץ מן המים ומן המלח\u0004 שאינם קרויים מזון, אלו \u0003דברי ר' אליעזר. ר' יהושע אומר:\u0004 יש הגבלה אחרת בדבר: \u0003ככר\u0004 שלם \u0003הוא עירוב, ואפלו מאפה\u0004 שגודלו \u0003סאה, והוא פרוסה\u0004 שניטל ממנו חלק — \u0003אין מערבין בה.\u0004 ואילו \u0003ככר\u0004 אפילו גודלו \u0003כאיסר, והוא שלם — מערבין בו.\u0004"],["על ההלכה במשנה במה מערבים ובמה אין מערבים, שואלים: הלוא כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו פעם אחת]\u0006 דבר זה: \u0003בכל מערבין ומשתתפין, חוץ מן המים והמלח!\u0004","\u0003אמר רבה:\u0004 תוספת זו באה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003ר' יהושע\u0004 במשנתנו, ש\u0003אמר ככר — אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא, קא משמע לן\u0004 \u0005[\u0006על כן \u0005משמיע לנו]\u0006 \u0003בכל\u0004 מערבין ומשתתפין, ולא רק בפת.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי,\u0004 הלוא שנינו: \u0003בכל מערבין עירובי חצירות ובכל משתתפין שיתופי מבואות, ולא אמרו לערב בפת אלא בחצר בלבד.\u0004 ונברר, \u0003מאן\u0004 \u0005[מי הוא]\u0006 זה ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר פת — אין\u0004 \u0005[כן]\u0006 מערבין בה, \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא\u0004 ראוי לעירוב, \u0003ר' יהושע\u0004 הוא, ובכל זאת \u0003קתני\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003\"בכל\"!\u0004 משמע ש\"בכל מערבין\" איננו דוקא כדי להוציא מדברי ר' יהושע אלה.","\u0003אלא אמר רבה בר בר חנה: לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהושע\u0004 בפרט אחר, שר' יהושע \u0003אמר: שלימה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 ראויה לערב בה, ואילו \u0003פרוסה\u0004 — \u0003לא, קא משמע לן \"בכל\"\u0004 — ואפילו בפרוסה.","ולעיקר שיטה זו שואלים: \u0003ופרוסה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יערבו בה? \u0003אמר ר' יוסי בן שאול אמר רבי: משום איבה,\u0004 שיבוא אדם ויאמר לחבירו: אתה נתת פרוסה בלבד ואני נתתי ככר שלימה. ולכן תקנו שיתן כל אחד ככר שלימה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: עירבו כולן בפרוסות מהו?\u0004 שהרי כאן שוב אין מקום לאיבה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין עושין כן, \u0003שמא יחזר\u0004 ה\u0003דבר לקלקולו,\u0004 ושמא יבוא אחד לתת ככר שלימה ויתרעם על חבירו שנותן פרוסה בלבד.","\u0003אמר ר' יוחנן בן שאול: ניטלה הימנה\u0004 מן הככר רק \u0003כדי חלתה,\u0004 כדי השיעור שמפרישים מן העיסה לחלה, או \u0003כדי דימועה.\u0004 שפעמים נופל משהו תרומה לתוך עיסת חולין, ואם נפל בשיעור של אחד ממאה, מפרישים מן הככר שנאפה מאותה עיסה כשיעור מה שנפל, ונותנים לכהן. ונחשב הדבר כאילו התרומה שנפלה היא שהוצאה, הרי הדין הוא ש\u0003מערבין לו בה\u0004 בככר כזו. משום שבכגון זה אין אנשים מתלוננים עליו על שלא רצה לתת ככר שלימה, אלא סבורים שחסרון קטן זה בככר משום שהפריש ממנה כדי חלה או הוצאת המדומע בה.","אבל ביתר מכן חושדים בו שהוא אוכל מן העירוב, ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003שאם היתה הככר חסרה כדי דימועה — מערבין לו בה,\u0004 היתה חסרה \u0003כדי חלתה — אין מערבין לו בה!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006, שכן לא באותו שיעור עצמו דיברו בשני המקומות, \u0003הא\u0004 \u0005[זה]\u0006 שהתירו בכדי חלה — מדובר \u0003בחלת נחתום\u0004 ששיעורה הוא קטן יותר, ולכן, אין שיעור שכזה נחשב חסרון לככר, ומערבים בה. \u0003הא\u0004 \u0005[זה]\u0006 שאסרו בככר חסר בכדי חלה — הוא \u0003בחלת בעל הבית\u0004 ששיעורה גדול יותר, ולכן אם חסר בככר שיעור כזה, אינו מערב בה.","וביאור הדברים, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שיעור חלה\u0004 שתיקנו חכמים הוא \u0003אחד מעשרים וארבעה.\u0004 וכן \u0003העושה עיסה לעצמו\u0004 או \u0003עיסה למשתה בנו,\u0004 שיעור החלה גם הוא \u0003אחד מעשרים וארבעה.\u0004 ואולם \u0003נחתום שהוא עושה למכור בשוק, וכן האשה שעשתה למכור בשוק\u0004 — יפרישו רק \u0003אחד מארבעים ושמונה,\u0004 שהקלו חכמים על המוכר שלא יפסיד בסחורתו.","\u0003אמר רב חסדא:\u0004 אם \u0003תפרה\u0004 (חבר שני חלקיה) \u0003בקיסם — מערבין לו בה,\u0004 שכן היא נראית כשלימה. ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבכגון זה \u0003אין מערבין לו בה!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאין מערבים — \u0003דידיע תיפרה\u0004 \u0005[שניכר התפר שבה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמערבים — ש\u0003לא ידיע תיפרה\u0004 \u0005[ניכר התפר שבה]\u0006.","\u0003אמר ר' זירא אמר שמואל: מערבין\u0004 אף \u0003בפת אורז ובפת דוחן. אמר מר עוקבא: לדידי מיפרשא לי מיניה\u0004 \u0005[לי עצמי פורש ממנו]\u0006 מ\u0003מר שמואל, בפת אורז — מערבין, ובפת דוחן אין מערבין,\u0004 שקשה לעשות ממנה פת הראויה למאכל.","\u0003אמר רב חייא בר אבין אמר רב: מערבין בפת עדשים.\u0004 ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 והאם פת זו ראויה למאכל, \u0003והא ההיא\u0004 \u0005[והרי אותה]\u0006 פת עדשים \u0003דהואי בשני\u0004 \u0005[שהיתה בימי]\u0006 \u0003מר שמואל, ושדייה לכלביה\u0004 \u0005[וזרקה לכלבו]\u0006 \u0003ולא אכלה,\u0004 ובודאי אינה ראויה למאכל אדם!","ומתרצים: אותה פת שלא אכלה הכלב בתערובת של \u0003שאר מינים\u0004 של אוכל \u0003הויא\u0004 \u0005[היתה],\u0006 לפי שעשו פת זאת לבדוק מה יהא טעמה של הפת. כעין מה שנאמר ליחזקאל הנביא לאכול: \u0003דכתיב \"ואתה קח לך חטין ושערים ופול ועדשים ודחן וכסמים\u0004 ונתת אותם בכלי אחד ועשית אותם לך ללחם\u0003\"\u0004 (יחזקאל ד, ט), וזהו מאכל שאינו ראוי לאכילת אדם, שאף הכלב פעמים אינו אוכלו. אבל פת העשויה מעדשים בלבד, ראויה לאכילה.","\u0003רב פפא אמר: ההיא\u0004 \u0005[אותה]\u0006 פת של יחזקאל \u0003צלויה בצואת אדם הואי\u0004 \u0005[היתה],\u0006 שכן נאמר \u0003\"\u0004ועוגת שעורים תאכלנה \u0003והיא בגללי צאת האדם תעגנה לעיניהם\"\u0004 (יחזקאל ד, יב).","וכיון שהוזכר כתוב זה שואלים: אם נעשה לחם זה ממינים שונים, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ועגת שעורים תאכלנה\"? אמר רב חסדא:\u0004 יש להבין שיאכל \u0003לשיעורים\u0004 כלומר בחלקים קטנים, ולא אכילה לשובע. \u0003רב פפא אמר: עריבתה,\u0004 האופן שמערבים אותה, \u0003כעריבת שעורים,\u0004 כדרך שעושים בפת שעורים שהיא פת גסה ואין טורחים לעשותה נאה, \u0003ולא כעריבת חטים.\u0004","\u0003נותן אדם מעה לחנוני\u0004 המוכר יין \u0003ולנחתום\u0004 הגרים באותו מבוי או חצר, \u0003כדי שיזכה לו עירוב\u0004 עם שאר בני החצר אם יבואו אליהם לקנות מהם יין או לחם לצורך העירוב, \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים: לא זכו לו מעותיו,\u0004 שעל ידי מתן כסף בלבד אי אפשר לזכות בעירוב, שנתינת כסף איננה יוצרת קנין כשלעצמה, שאין דבר נקנה לכל צורך שהוא אלא במשיכה או באחת מדרכי הקנין המקובלות."],["\u0003ומודים בשאר כל האדם.\u0004 שאם נתן מעות למי שאיננו חנווני או נחתום כדי שיזכה לו בעירוב, \u0003שזכו לו מעותיו. שאין מערבין לאדם אלא מדעתו\u0004 ובשליחותו, ולכן בחנווני שאין דעת נותן המעות שייעשה החנווני שלוחו, וגם המעות אינן קונות — אין במעשהו כלום. אבל באומר לאחר, ודאי נתכווין לעשותו שלוחו, ומועיל.","\u0003אמר ר' יהודה: במה דברים אמורים — בעירובי תחומין, אבל בעירובי חצרות — מערבין\u0004 לאדם \u0003לדעתו ושלא לדעתו, לפי שזכין לאדם שלא בפניו,\u0004 ואין צריך שיגלה דעתו ויסכים אלא אפשר לזכות עבורו, ועירוב חצירות זכות הוא לו. \u0003ואין חבין לאדם שלא בפניו,\u0004 ובעירובי תחומין, אף שמשתכר שיכול להלך יותר מצד זה של התחום, הריהו מפסיד מצידו האחר. ואין לגרום לאדם כל הפסד, אלא בידיעתו ובהרשאתו.","שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר\u0004 הסבור שאם נתן פרוטה לחנווני או לנחתום זכה בעירוב? ו\u0003הא\u0004 \u0005[והרי]\u0006 \u0003לא משך,\u0004 וכיון שלא משך אינו יכול לזכות בדבר!","\u0003אמר רב נחמן אמר רבה בר אבהו: עשאו ר' אליעזר כארבעה פרקים בשנה, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בארבעה פרקים\u0004 (זמנים) \u0003אלו:\u0004 ערב פסח, ערב שבועות ערב ראש השנה, וערב שמיני עצרת, \u0003משחיטין את הטבח\u0004 לשחוט בהמה \u0003בעל כרחו. ואפלו\u0004 היה בידו \u0003שור שוה אלף דינר, ואין ללוקח\u0004 שקנה ממנו \u0003אלא דינר אחד — כופין אותו\u0004 את הטבח, \u0003לשחוט,\u0004 ויקח הקונה בשר בדינר. כי ארבעה פרקים אלה הם זמנים שבהם הכל קונים בשר. והטבח שהבטיח לספקו, חייב לתתו לקונה, אפילו הוא מפסיד על ידי כך סכום ניכר.","\u0003לפיכך אם מת\u0004 השור, \u0003מת ללוקח. מת ללוקח\u0004 — מדוע? \u0003הא\u0004 \u0005[והרי]\u0006 \u0003לא משך\u0004 הלוקח את השור ולא נעשה בו קנין, ואם מת השור הרי זה לא קנה מאומה, ויקבל דינרו בחזרה! \u0003אמר רב הונא:\u0004 מדובר כאן \u0003ב\u0004מקרה \u0003שמשך.\u0004","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך\u0006 אתה מפרש \u0005אמור את סופה\u0006 של אותה משנה\u0005]:\u0006 \u0003בשאר ימות השנה אינו כן. לפיכך, אם מת — מת למוכר,\u0004 ואולם אם אומר אתה שמדובר שמשך הלוקח, \u0003אמאי\u0004 \u0005[מדוע]\u0006 מת למוכר? \u0003הא\u0004 \u0005[והרי]\u0006 \u0003משך\u0004 הלוקח, ואם משך קנה, והשור שמת — ברשותו מת!","\u0003אמר רב שמואל בר יצחק: לעולם\u0004 מדובר \u0003בשלא משך, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בשזיכה לו על ידי אחר,\u0004 שזיכה הטבח ללוקח על ידי אחר, ואמר לו שיזכה בבשר שור זה שווה דינר עבור פלוני, בלא לשאול את דעתו.","ומעתה, \u0003בארבעה פרקים אלה\u0004 ש\u0003זכות הוא לו,\u0004 שהכל רוצים לקנות בשר — \u0003זכין לו\u0004 לאדם \u0003שלא בפניו,\u0004 ונגמר הקנין בכך. \u0003בשאר ימות השנה,\u0004 ש\u0003חוב הוא לו,\u0004 שיתחייב לשלם, ושמא איננו רוצה כלל בהוצאה זו — \u0003אין חבין לו אלא בפניו.\u0004","\u0003ורב אילא אמר\u0004 בשם \u0003ר' יוחנן: בארבעה פרקים אלו העמידו חכמים דבריהם על דברי תורה.\u0004 שכן \u0003אמר ר' יוחנן: דבר תורה\u0004 מעיקר הדין, כפי שהוא בתורה, \u0003מעות\u0004 עצמן \u0003קונות,\u0004 וכיון שנתן מעות בעד חפץ מסוים — נקנה החפץ.","\u0003ומפני מה אמרו\u0004 חכמים שלא המעות קונות אלא \u0003משיכה\u0004 של גוף החפץ עצמו \u0003קונה — גזירה שמא יאמר לו\u0004 לקונה לאחר שנתן מעות: \u0003נשרפו חיטיך בעלייה,\u0004 ואבדת הכל. שהרי עם נתינת המעות, זכה באותו חפץ שקנאו בכל מקום שהוא. וכיון שעשוי הדבר להביא לידי רמאות, תיקנו שהקנין יגמר רק על ידי משיכה. ובארבעה פרקים אלה תיקנו חכמים להחזיר את הדבר לקנין היסודי שמן התורה. וסבר ר' אליעזר כי תקנה זו קיימת גם לענין עירוב.","נאמר במשנה כי \u0003מודים\u0004 חכמים \u0003בשאר כל האדם.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מהו]\u0006 \u0003שאר כל האדם? אמר רב:\u0004 משמעו \u0003בעל הבית,\u0004 אדם שאינו סוחר, שאמר לו חבירו שיזכה לו בעירובו על ידי מעה שנותן לו.","\u0003וכן אמר שמואל: בעל הבית\u0004 קונה. שכן \u0003אמר שמואל: לא שנו אלא נחתום, אבל בעל הבית קונה. ואמר שמואל: לא שנו אלא\u0004 שנתן \u0003מעה, אבל\u0004 נתן \u0003כלי — קונה\u0004 את העירוב בדרך קנין חליפין. שאם נותן את הכלי עבור העירוב נקנה לו העירוב בכל מקום על ידי חליפין, מה שאין כן במעות שאין קנין חליפין במעות.","\u0003ואמר שמואל: לא שנו אלא\u0004 ש\u0003אמר לו\u0004 לנחתום: \u0003זכה לי, אבל אמר: ערב לי,\u0004 הרי שכוונתו היתה \u0003שליח שויה\u0004 \u0005[עשאו]\u0006 לערב עבורו, וממילא \u0003קני\u0004 \u0005[נקנה\u0006 לו\u0005]\u0006 העירוב מכוחה של שליחות.","במשנה שנינו, \u0003אמר ר' יהודה: במה דברים אמורים\u0004 שמערבים רק לדעת, בעירוב תחומין, ולא בעירובי חצירות. \u0003אמר רב יהודה אמר שמואל: הלכה כר' יהודה\u0004 בענין זה, \u0003ולא עוד אלא כל מקום ששנה ר' יהודה\u0004 הלכה \u0003בעירובין — הלכה כמותו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 \u0003לרב יהודה:\u0004 האם \u0003אמר שמואל\u0004 פסק זה \u0003אפילו\u0004 לענין \u0003מבוי שניטלו קורותיו או לחייו\u0004 בתוך השבת?","שלדעת ר' יהודה מותר לטלטל בו באותה שבת \u0003אמר ליה\u0004 \u0005[לו]:\u0006 בקניית \u0003עירובין אמרתי לך, ולא במחיצות.\u0004 שדין המחיצות אינו חלק מדיני עירובין, אלא נוגע בכמה גופי הלכה וביניהם גם לענין עירוב, ובענין זה לא פסקו כר' יהודה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 אם נאמר ש\u0003\"הלכה\"\u0004 כר' יהודה, \u0003מכלל דפליגי\u0004 \u0005[מכאן שנחלקו]\u0006 בדבר זה. \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי: כל מקום שאמר ר' יהודה \"אימתי\" ו\"במה\u0004 דברים אמורים \u0003\"במשנתנו — אינו אלא לפרש דברי חכמים\u0004 שקדמוהו ולא לחלוק עליהם! ולפיכך מדוע קובעים הלכה כר' יהודה, אם לדעת ר' יהושע בן לוי לא באו דבריו אלא לפרש, והכל מודים להם.","לפני שמתייחסים לעצם השאלה תוהים על הדבר: \u0003ו\u0004כי \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 ר' יהודה וחכמים בענין זה? \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 \u0003נתוספו עליהן,\u0004 על בני המבוי, דיורין חדשים — \u0003מוסיף ומזכה\u0004 לאחרים, \u0003וצריך להודיע\u0004 להם. הרי שאף בעירובי חצירות צריך להודיע, שלא כדברי ר' יהודה. ומכאן שיש חכם שאינו מקבל את שיטתו!","ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בחצר שבין שני מבואות\u0004 שיכולה לערב עם כל מבוי שתרצה. וכיון שיש שם גם צד של חוב, שמא אין בני החצר רוצים לערב עם מבוי זה להפסיד את המבוי האחר, ולכן צריך להודיעם.","ומקשים עוד: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שיזבי אמר רב חסדא\u0004 על אותה משנה: \u0003זאת אומרת חלוקין עליו חבריו על ר' יהודה\u0004 לענין הודעה לאחרים בעירובי חצירות. משמע שיש סבורים שיש מחלוקת בדבר זה, ולא הכל מסכימים לר' יהודה.","\u0003אלא\u0004 חייבים אנו לתרץ ולישב את שתי הקושיות כאחת:"],["\u0003גברא אגברא קא רמית\u0004 \u0005[\u0006וכי \u0005מאדם על אדם אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 כלומר אין מקום להקשות מדברי אמורא אחד על דברי אמורא אחר. \u0003מר\u0004 \u0005[חכם זה,\u0006 שמואל] \u0003סבר פליגי\u0004 \u0005[\u0006ש\u0005נחלקו]\u0006 ר' יהודה וחכמים. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יהושע בן לוי\u0005]\u0006 \u0003סבר שלא פליגי\u0004 \u0005[נחלקו].\u0006","\u0003גופא\u0004 \u0005[לגופו\u0006 של דבר\u0005]\u0006 שהובא אגב נושא אחר, שבים לדון בו: \u0003אמר ר' יהושע בן לוי: כל מקום שאמר ר' יהודה \"אימתי\" ו\"במה\u0004 דברים אמורים \u0003\" במשנתינו — אינו אלא לפרש דברי חכמים. ור' יוחנן אמר \"אימתי\" — לפרש\u0004 הוא, ואולם \u0003\"במה\"\u0004 — ענינו \u0003לחלוק.\u0004 על כך מקשים.","\u0003ו\"אימתי\" לפרש הוא\u0004 בכל מקרה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ואלו הם הפסולים\u0004 לעדות מדברי חכמים משום שהחשיבום חכמים כגזלנים וחומסים: \u0003המשחק בקוביא\u0004 לשם רווח כסף, \u0003ומלוה בריבית, ומפריחי יונים\u0004 העושים תחרויות ביונים ומהמרים עליהן. וטעם פסולם משום שבכל משחק מזל וכיוצא בו אין המשתתף מקנה בכל לב את הממון שהוא מהמר עליו, שהוא סבור שירויח ולא יפסיד, ונמצא הלוקח ממון כגון זה לוקח כסף שהנותן לא הקנהו לו, והריהו כגזלן מדברי חכמים. \u0003וסוחרי\u0004 פירות \u0003שביעית\u0004 שמותר לאוכלם, אך לא לסחור בהם.","\u0003אמר ר' יהודה: אימתי\u0004 פסלו חכמים את כל אלה — \u0003בזמן שאין לו אומנות אלא היא\u0004 עיסוק זה בלבד, \u0003אבל יש לו אומנות\u0004 כשרה \u0003שלא היא,\u0004 אף על פי שמרויח כסף גם בדברים אלה — \u0003הרי זה כשר.\u0004 כי לדעתו, המרויח כסף במשחקי מזל אינו עבריין וגזלן, אלא טעם פסולם של כל אלה לעדות הוא משום שאינם עוסקים ביישובו של עולם, וכיון שממונם בא להם בלא יגיעה אינם מתחשבים בהפסד ממונם של אחרים. ולכן אם יש להם אומנות אחרת — כשרים. ולפי הכלל צריך היה לומר שדברי ר' יהודה הם לפרש בלבד. אך \u0003תני עלה [שנינו עליה,\u0004 על כך\u0005]\u0006 \u0003בברייתא, וחכמים אומרים: בין שאין לו אומנות אלא היא, ובין שיש לו אומנות שלא היא — הרי זה פסול.\u0004 הרי שדברי ר' יהודה, אף שאמרם בלשון \"אימתי\", לא לפרש באו אלא לחלוק!","","ומתרצים: \u0003ההיא\u0004 \u0005[אותה\u0006 הלכה\u0005]\u0006 בברייתא לענין פסולי העדות לא דעת חכמים שבמשנה היא אלא שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003ר' טרפון היא,\u0004 אבל חכמים במשנה סבורים כר' יהודה בענין זה. ולא באו דבריו אלא לפרש.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדיני נזירות, \u0003אמר ר' יהודה משום\u0004 \u0005[בשם]\u0006 \u0003ר' טרפון:\u0004 במקרה שאנשים התערבו על דבר, שאם יהא באופן מסוים יהא אחד מהם נזיר, ונוצר ספק דברי מי התקיימו — \u0003לעולם אין אחד מהם נזיר, לפי שאין נזירות אלא להפלאה.\u0004 שאין נדר נזירות חל אלא אם כן יהיה הנזר מופלא, כלומר מבורר ומובהר מראש שאותו אדם מתכוון בודאות להיות נזיר.","\u0003אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 \u0003כיון דמספקא ליה\u0004 \u0005[שמסופק הוא]\u0006 במקרה זה \u0003אי\u0004 \u0005[אם]\u0006 \u0003נזיר אי\u0004 \u0005[אם]\u0006 \u0003לא נזיר הוא — לא משעביד נפשיה\u0004 \u0005[משעבד עצמו]\u0006 ואינו מקבל עליו בשלמות את נדר הנזירות. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכולים אנו לומר שר' יהודה ראה את המשחקים במשחקי תחרות כפסולים לעדות משום גזלנות כי \u0003כיון\u0004 ש\u0003לא ידע\u0004 המשחק \u0003אי קני אי לא קני\u0004 \u0005[אם יקנה\u0006 ויזכה \u0005או לא יקנה]\u0006 \u0003לא גמר ומקנה\u0004 את הממון שהוא משחק בו, ונמצא שהמרויח במשחקים אלה לוקח ממון על סמך הקנאה שאינה גמורה, והריהו כגזלן מדברי סופרים, ופסול לעדות.","","\u0003כיצד משתתפין בתחומין?\u0004 אם רוצה לעשות עירוב תחומין לעצמו וגם לאחרים \u0003מניח את החבית\u0004 שיש בה מזון במקום שקבע לקנות שביתה, \u0003ואומר: הרי זה לכל בני עירי, לכל מי שילך\u0004 בשבת \u0003לבית האבל\u0004 שנמצא מחוץ לתחום \u0003או לבית המשתה\u0004 (שמחת נישואין). \u0003וכל שקיבל עליו\u0004 ללכת \u0003מבעוד\u0004 יום — \u0003מותר, משתחשך — אסור.\u0004 שכללו של דבר: \u0003שאין מערבין משתחשך.\u0004","\u0003אמר רב יוסף: אין מערבין\u0004 עירובי תחומין \u0003אלא לדבר מצוה,\u0004 אבל לא להליכה לדבר הרשות. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במפורש במשנה: \u0003לכל מי שילך לבית האבל או לבית המשתה\u0004 משמע שמערבים רק לשם מצות ניחום אבלים או שמחת החתונה, ולא למקרה אחר!","ומתרצים: מן המשנה בלבד אין להוכיח כי \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אורחא דמלתא קתני\u0004 \u0005[דרך\u0006 המקובלת \u0005בדברים שנה]\u0006 שכרגיל אין רבים מערבים מחוץ לתחום אלא לצורך מאורע מיוחד כגון חתונה, אבל מן הדין מותר לערב גם לדבר הרשות, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב יוסף הלכה זו. במשנה שנינו: ש\u0003כל שקיבל עליו מבעוד יום\u0004 ללכת, התירו העירוב. ומעירים: אם כן \u0003שמעת מינה\u0004 \u0005[למדת מכאן]\u0006 ש\u0003אין ברירה,\u0004 שאין אומרים שנודע למפרע מה היתה כוונתו של אדם בשעת מעשה, וכאילו על דעת כן אמר את הדברים קודם לכן. כי \u0003אי\u0004 \u0005[אם]\u0006 \u0003יש ברירה\u0004 ויש לה תוקף בהלכה — \u0003תיגלי מילתא\u0004 \u0005[יתגלה הדבר]\u0006 \u0003למפרע\u0004 ש\u0003מבעוד יום הוה ניחא ליה\u0004 \u0005[היה נוח לו]\u0006 ויקנה לו העירוב למפרע!","","\u0003אמר רב אשי:\u0004 אין להבין \"שמבעוד יום\" משמעו שאם הסכים לסמוך על העירוב מבעוד יום, אלא ש\u0003\"הודיעוהו\" ו\"לא הודיעוהו\" קתני\u0004 \u0005[שנינו],\u0006 כלומר אם ידע על קיום העירוב מבעוד יום, אף שלא החליט להשתמש בו אלא לאחר מכן — הרי זה עירוב, משום שיש ברירה. אבל אם לא ידע על קיום העירוב — ודאי אין לומר שנתגלה הדבר למפרע, שהרי בשעה שחל העירוב לא ידע כלל על מציאותו.","\u0003אמר רב אסי: קטן בן שש יוצא בעירוב אמו\u0004 שהוא נחשב כטפל לה ואינו צריך עירוב לעצמו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003קטן שצריך לאמו — יוצא בעירוב אמו, ושאין צריך לאמו — אין יוצא בעירוב אמו.\u0004","וכדי שנברר מיהו הקרוי קטן הצריך לאמו נביא ראיה מנושא אחר \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 דין \u0003סוכה כי האי גוונא\u0004 \u0005[כעין זה]:\u0006 \u0003קטן שאין צריך לאמו — חייב בסוכה\u0004 מדברי סופרים, לחנכו במצוות.","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בבעיה זו: \u0003ואיזהו קטן שאין צריך לאמו? אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כל שנפנה\u0004 לצרכיו \u0003ואין אמו מקנחתו,\u0004 והיכול לקנח עצמו הריהו לענין זה גדול. \u0003ר' שמעון בן לקיש אמר: כל שניעור\u0004 משנתו \u0003ואינו קורא \"אימא\".\u0004 ותוהים: \u0003\"אימא\" סלקא דעתך\u0004 \u0005[עולה על דעתך],\u0006 והרי אפילו ילדים \u0003גדולים\u0004 בהרבה, \u0003נמי קרו\u0004 \u0005[גם כן קוראים]\u0006 בבוקר שתבוא אליו אמו לצורך מה. \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003כל שניעור משנתו ואינו קורא \"אימא, אימא\",\u0004 שילד שאינו קם עד שאמו באה אליו, הוא הקרוי קטן הצריך לאמו.","","ושאלו: \u0003וכמה\u0004 מהו גיל זה שכבר אינו מוגדר כקטן הצריך לאמו? \u0003כבר\u0004 \u0005[כבן]\u0006 \u0003ארבע, כבר\u0004 \u0005[כבן]\u0006 \u0003חמש.\u0004 וקשה לדברי ר' אסי שלדבריו אף בן שש יוצא בעירוב אמו כיון שנחשב זקוק לאמו!"],["\u0003אמר רב יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 בישוב קושיה זו: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב אסי\u0004 שתינוק כזה יוצא בעירוב אמו הכוונה \u0003כגון שעירב עליו אביו לצפון, ואמו\u0004 עירבה עבורו \u0003לדרום,\u0004 שבמקרה זה \u0003אפילו בר\u0004 \u0005[בן]\u0006 \u0003שש נמי בצוותא דאמיה ניחא ליה\u0004 \u0005[גם כן בחברת אמו נוח לו]\u0006 יותר מבחברת אביו. אבל אם לא עירבו עליו, אף רב אסי מסכים שאינו טפל לאמו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מן הברייתא: \u0003קטן שצריך לאמו — יוצא בעירוב אמו\u0004 שעירבה לעצמה. ועד כמה יהא גילו, \u0003עד בן שש.\u0004 ומכאן, \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זאת \u0005קושיה חמורה]\u0006 על \u0003רב יהושע בר אידי\u0004 שפירש שאין בן שש יוצא בעירוב אמו רק אם עירבה עליו.","ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005].\u0006 ושואלים: \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זאת \u0005קושיה חמורה]\u0006 על דברי \u0003רב אסי,\u0004 שהרי נאמר כאן עד בן שש, ומשמע: ולא בן שש עצמו. ואילו לדבריו, אפילו בן שש! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005היה לומר לך]\u0006 \u0003רב אסי:\u0004 מה שנאמר כאן \u0003\"עד\u0004 בן שש \u0003\",\u0004 משמעו: \u0003ועד בכלל.\u0004 כלומר, גם בן שש בכלל.","ושואלים: \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זאת \u0005קושיה חמורה]\u0006 על שיטת \u0003ר' ינאי וריש לקיש\u0004 שלדעתם הצריך לאמו הוא כבן ארבע וחמש! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דאיתיה אבוהי במתא\u0004 \u0005[שנמצא אביו בעיר]\u0006 והתינוק יכול לצאת עמו, ואינו קרוי צריך לאמו אפילו כשהוא רק בן ארבע וחמש, ו\u0003הא\u0004 \u0005[זה] —\u0006 ש\u0003לא איתיה אבוהי במתא\u0004 \u0005[נמצא אביו בעיר],\u0006 הרי הוא צריך לאמו עד כבן שש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מערב אדם על ידי\u0004 (עבור) \u0003בנו ובתו הקטנים, על ידי עבדו ושפחתו הכנענים, בין לדעתן בין שלא לדעתן. אבל אינו מערב לא על ידי\u0004 (עבור) \u0003עבדו ושפחתו העברים, ולא על ידי בנו ובתו הגדולים, ולא על ידי אשתו אלא מדעתם.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא יערב אדם על ידי בנו ובתו הגדולים, ו\u0004לא \u0003על ידי עבדו ושפחתו העברים, ולא על ידי אשתו אלא מדעתן. אבל מערב הוא על ידי עבדו ושפחתו הכנענים, ועל ידי בנו ובתו הקטנים, בין לדעתן ובין שלא לדעתן — מפני שידן כידו,\u0004 שרשותם והחלטתם בטלים לו.","\u0003וכולן שעירבו\u0004 לעצמם \u0003ו\u0004אף \u0003עירב עליהם רבן\u0004 (אדונם) לצד אחר — \u0003יוצאין\u0004 בעירוב \u0003של רבן, חוץ מן האשה,\u0004 ש\u0003מפני שיכולה למחות\u0004 ולומר שאיננה רוצה בעירובו של בעלה.","ושואלים תחילה: \u0003אשה מאי שנא\u0004 \u0005[\u0006ב\u0005מה\u0006 היא \u0005שונה]\u0006 מבנו ובתו הגדולים, ומדוע אין הם יכולים למחות? הלוא אף הם הריהם בני דעת וברשות עצמם! \u0003אמר רבה:\u0004 אין הכוונה לאשה דוקא, אלא \u0003אשה וכל דדמי\u0004 \u0005[שדומה]\u0006 \u0003לה\u0004 לענין זה, כגון עבדו העברי או בנו הגדול.","ולעניננו, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חוץ מן האשה, מפני שיכולה למחות.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 \u0003דמחי\u0004 \u0005[שמחתה],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 שאם עשה עירוב \u0003סתמא\u0004 \u0005[סתם]\u0006 ולא מחתה \u0005—\u0006 \u0003נפקא\u0004 \u0005[יוצאת]\u0006 \u0003ב\u0004עירוב של \u0003בעלה,\u0004 וקשה: \u0003הא קתני רישא\u0004 \u0005[הלוא שנינו בתחילת\u0006 הברייתא\u0005]\u0006 שאינו יכול לערב \u0003אלא מדעתם, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ששואל אותם אם רצונם בעירוב זה, \u0003דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003\"אין\"\u0004 \u0005[כן],\u0006 משמע שבסתם אינו מועיל!","ודוחים: \u0003לא,\u0004 אלא כך יש להבין: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"אלא מדעתם\" — דאישתיקו\u0004 \u0005[ששתקו],\u0006 ולא אמרו דבר למחות. \u0003לאפוקי היכא דאמרי\u0004 \u0005[להוציא היכן שאמרו]:\u0006 \u0003\"לא\",\u0004 ואם לא מחו הריהם יוצאים בעירובו של אבי המשפחה.","ומקשים: \u0003הא\u0004 \u0005[הרי\u0006 שנינו\u0005]:\u0006 \u0003וכולן שעירבו ועירב עליהן רבן — יוצאין בשל רבן, וסתמא\u0004 \u0005[וסתם]\u0006 \u0003הוא,\u0004 שהרי לא נאמר שמחו, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנינו]:\u0006 \u0003חוץ מן האשה דלא נפקי\u0004 \u0005[יוצאים].\u0006 הרי שאף בלא מיחוי אין עירוב האב מועיל לאחרים!","\u0003אמר רבא: כיון שעירבו\u0004 לרוח אחרת, \u0003אין לך מיחוי גדול מזה.\u0004 שאינם צריכים למחאה אחרת, שהרי מעשיהם מוכיחים שאין רצונם להשתתף בעירוב האב.","\u0003כמה הוא שיעורו\u0004 של עירוב התחומין? \u0003מזון שתי סעודות לכל אחד ואחד.\u0004 וביחס לשיעור זה נחלקו באשר לאלו שתי סעודות מדובר כאן. \u0003מזונו לחול ולא לשבת,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר\u0004 שקובעים על פי מזונו \u0003לשבת ולא לחול, וזה וזה מתכוונים להקל.\u0004 שלדעת ר' מאיר אוכלים בשבת יותר, ולדעת ר' יהודה אוכלים בחול יותר.","\u0003ר' יוחנן בן ברוקה אומר:\u0004 כי מזון שתי סעודות \u0003מככר\u0004 הנקנה \u0003ב\u0004מטבע \u0003פונדיון,\u0004 שהוא אחד מארבעים ושמונה בסלע, כאשר קונים \u0003ארבע סאין ב\u0004מטבע \u0003סלע,\u0004 זהו מזון שתי סעודות. \u0003ר' שמעון אומר: שתי ידות\u0004 (חלקים) \u0003לככר משלש לקב.\u0004 כלומר, השיעור הוא שני שליש ככר מאותן ככרות שכל אחת מהן היא שליש הקב.","ואגב כך נאמר ש\u0003חצייה\u0004 של ככר זו הוא הקרוי פרס (מחצית), וזמן אכילתה הוא שיעור הזמן בו נטמאים בגדיו של אדם הנכנס \u0003לבית המנוגע\u0004 (בית שיש בכתליו נגע צרעת). \u0003וחצי חצייה\u0004 של ככר זו הוא שיעור המאכל הטמא, \u0003לפסול את הגויה\u0004 כלומר לפסול, כעין טומאה, את גופו של האוכל, שיהא אסור מדברי חכמים לאכול בתרומה.","שואלים: \u0003וכמה\u0004 הוא \u0003מזון שתי סעודות\u0004 בשיעורים של ר' יהודה ור' מאיר? \u0003אמר ר' יהודה אמר רב: תרתי ריפתא איכרייתא\u0004 \u0005[שתי ככרות לחם של איכרים].\u0006 \u0003רב אדא בר אהבה אמר: תרתי ריפתא נהר פפיתא\u0004 \u0005[שתי ככרות לחם\u0006 הנעשות באיזור \u0005נהר פפא].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לרב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: אבוך כמאן סבירא ליה\u0004 \u0005[אביך כמי סבר]\u0006 כר' יהודה או כר' מאיר? אמר לו: \u0003כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא].\u0006 אמר לו רב יוסף: \u0003אנא נמי\u0004 \u0005[אני גם כן]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר סבירא לי\u0004 \u0005[אני סבור].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 תחשוב \u0003כר' יהודה, קשיא הא דאמרי אינשי\u0004 \u0005[קשה על\u0006 שיטתו \u0005זה שאומרים בני אדם]\u0006 בפתגם המקובל: \u0003רווחא לבסימא שכיח\u0004 \u0005[הרווח\u0006 במעי האדם לדברים \u0005מתוקים מצוי],\u0006 שלפי ההנחה המקובלת אדם האוכל מעדנים אוכל כמות גדולה יותר, ולכן כמות מזון סעודות שבת גדול מסעודות החול, כיון שיש בהן יותר מעדנים.","במשנה שנינו כי \u0003ר' יוחנן בן ברוקא\u0004 קבע שיעור אחד למזון שתי סעודות, ור' שמעון קבע שיעור אחר. \u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003וקרובים דבריהן להיות שוין.\u0004 על כך תוהים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?!\u0006 הלוא לשיטת \u0003ר' יוחנן\u0004 יש \u0003ארבע סעודתא לקבא\u0004 \u0005[סעודות\u0006 הן \u0005לקב]\u0006 שבארבע סאין יש עשרים וארבעה קבים. ואם ארבע סאין נקנות בסלע, ומזון שתי סעודות נקנה בפונדיון, שהוא אחד מארבעים ושמונה בסלע, הרי ששיעור שתי סעודות הוא מחצית הקב, רבע הקב לכל סעודה. ולשיטת \u0003ר' שמעון — תשע סעודתא לקבא\u0004 \u0005[סעודות לקב]\u0006 אם כן רחוקים דבריהם ביותר!","\u0003אמר רב חסדא:\u0004 את דברי ר' יוחנן בן ברוקא יש להבין כך, \u0003צא מהן שליש לחנוני,\u0004 שארבע סאין נמכרות בסלע לחנווני, ואילו החנווני מרויח בשכר עמלו שליש (שהוא תוספת מחצית על סכום הקניה).","על שיעור זה שואלים: \u0003אכתי\u0004 \u0005[עדיין]\u0006 נמצא כי \u0003למר\u0004 \u0005[ל\u0006שיטת \u0005חכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003תשע\u0004 סעודות בקב. \u0003ולמר\u0004 \u0005[ול\u0006שיטת \u0005חכם זה,\u0006 לשיטת ר' יוחנן\u0005]\u0006 אמנם אינן ארבע אלא \u0003שית\u0004 \u0005[שש]\u0006 סעודות, ועדיין השיעורים רחוקים!","\u0003אלא\u0004 יש לומר \u0003כאידך\u0004 \u0005[כ\u0006דעה \u0005האחרת]\u0006 שהביע \u0003רב חסדא\u0004 לענין אחר ש\u0003אמר: צא מהן\u0004 \u0005[הוצא מהן]\u0006 מן החשבון \u0003מחצה לחנוני,\u0004 ואם נחשוב שרווח החנווני הוא מחצית המחיר, יתברר שהשיעורים קרובים.","ושואלים: \u0003ואכתי, למר — תשע, ולמר — תמני\u0004 \u0005[ועדיין לחכם זה,\u0006 ר' שמעון \u0005—\u0006 \u0005תשע\u0006 בקב, \u0005ולחכם זה —\u0006 \u0005שמונה\u0006 בקב\u0005]!\u0006 ומשיבים: \u0003הינו דקאמר\u0004 \u0005[זה שאמר]\u0006 \u0003וקרובים דבריהם להיות שוין,\u0004 שאמנם אינם זהים, אבל אין הבדל גדול ביניהם.","ומעירים: מכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב חסדא\u0004 על דברי \u0003רב חסדא\u0004 עצמו בענין שיעור הרווח של חנווני! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דקא יהיב\u0004 \u0005[שנותן]\u0006 \u0003בעל הבית ציבי\u0004 \u0005[עצים],\u0006 ואין החנווני צריך להוציא הוצאות עבור העצים לאפיה, אז מקבל החנווני בשכר טרחתו שליש מן המחיר הסופי. \u0003הא\u0004 \u0005[זה\u0006 שלוקח חצי\u0005]\u0006 — ש\u0003לא יהיב\u0004 \u0005[נותן]\u0006 \u0003בעל הבית ציבי\u0004 \u0005[עצים]\u0006 ומקבל החנווני ריווח גם תמורת העצים שקנה לצורך אפיית הלחם.","נאמר במשנה שזמן אכילת \u0003חצייה\u0004 של הפת שנאמרה הוא הראוי לטמא את בגדי הנכנס \u0003לבית המנוגע,\u0004 וכן ש\u0003חצי חצייה היא הכמות הראויה לפסול את הגוייה מלאכול בתרומה.\u0004"],["\u0003א תנא\u0004 \u0005[שנה\u0006 בתוספתא\u0005]:\u0006 \u0003וחצי חצי חציה\u0004 של ככר זו \u0003לטמא טומאת אוכלין,\u0004 שבשיעור זה מקבל האוכל טומאה. ושואלים: \u0003ותנא דידן מאי טעמא לא תני\u0004 \u0005[והתנא שלנו,\u0006 במשנתנו\u0005, מה טעם לא שנה]\u0006 אף הוא \u0003טומאת אוכלין?\u0004 ומשיבים: \u0003משום\u0004 ש\u0003לא שוו שיעורייהו להדדי\u0004 \u0005[שיעוריהם זה לזה],\u0006 שאין השיעור לטומאת אוכלים בדיוק חצי השיעור לפסול את הגויה.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כמה שיעור חצי פרס? שתי ביצים חסר קימעא\u0004 (משהו), \u0003דברי ר' יהודה. ר' יוסי אומר: שתי ביצים שוחקות\u0004 (עודפות מעט). \u0003שיער רבי\u0004 את מידת חצי פרס, לאחר שמדד את מנין הקבים בסאה שהובאה לפניו, ומצא שהוא \u0003שתי ביצים ועוד.\u0004 ואמרו: \u0003כמה ועוד? אחד מעשרים בביצה.\u0004","\u0003ואילו גבי טומאת אוכלין תניא\u0004 \u0005[שנויה\u0006 בברייתא\u0005]:\u0006 \u0003ר' נתן ור' דוסא אמרו: כביצה שאמרו\u0004 חכמים שהיא שיעור הנטמא בטומאת אוכלים משערים \u0003כמוה וכקליפתה, וחכמים אומרים: כמוה בלא קליפתה.\u0004 ושיעורים אלה אינם בדיוק מחצית של אף אחד מן השיעורים שנאמרו מקודם בחצי פרס.","לגוף הענין \u0003אמר רפרם בר פפא אמר רב חסדא:\u0004 מדה \u0003זו\u0004 שנאמרה בשיעור חצי פרס היא \u0003דברי ר' יהודה ור' יוסי,\u0004 וקרובה שיטתם לדברי ר' שמעון במשנתנו. \u0003אבל חכמים אומרים: כביצה ומחצה שוחקות. ומאן\u0004 \u0005[ומיהם]\u0006 \u0003חכמים\u0004 אלו — \u0003ר' יוחנן בן ברוקה.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי לפי דעתו חצי ככר הוא שלוש ביצים, נמצא שמחציתן היא ביצה ומחצה! ומשיבים: לא לענין המדה עצמה בא לחדש כי אם שהשיעור יהא בביצים \u0003שוחקות אתא לאשמועינן\u0004 \u0005[בא להשמיענו].\u0006","מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: שיגר\u0004 איש אחד ושמו \u0003בוניוס לרבי מודיא דקונדיס\u0004 (מדת סאה) \u0003מן\u0004 המקום \u0003נאוסא.\u0004 שהיתה להם מסורת שהיא מדה קדומה ומדוייקת (ריטב\"א). \u0003ושיער רבי\u0004 שהיא מכילה \u0003מאתן\u0004 \u0005[מאתים]\u0006 \u0003ושבע עשרה ביעין\u0004 \u0005[ביצים].\u0006","ושואלים: \u0003הא\u0004 \u0005[זו]\u0006 מדת \u0003סאה דהיכא\u0004 \u0005[של היכן]\u0006 היא, לפי מה נקבעה מדה זו? \u0003אי\u0004 \u0005[אם]\u0006 של ה\u0003מדברית\u0004 כלומר, המדה היסודית שהשתמש בה משה רבינו במדבר, ושעל פיה נקבעו כל המדות שבתורה, הרי בסאה יש ששה קבים, ובכל קב ארבעה לוגין, וכל לוג יש בו שש ביצים, ונמצא סך הכל \u0003מאה ארבעין וארבע\u0004 ביצים \u0003הויא\u0004 \u0005[הריהי].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 של המדה ה\u0003ירושלמית,\u0004 שהגדילו בירושלים את מדת הסאה עד שסאה מדברית היא חמש שישיות מן הירושלמית, אם ככה נחשב נמצא כי רק \u0003מאה ושבעין ושלש\u0004 ביצים \u0003הויא\u0004 \u0005[הריהי]\u0006 הסאה.","\u0003ואי\u0004 \u0005[ואם]\u0006 של הסאה ה\u0003ציפורית,\u0004 שהגדילו שוב את מדת הסאה עד שהירושלמית היא חמש שישיות ממנה, הרי \u0003מאתן\u0004 \u0005[מאתים]\u0006 \u0003ושבע\u0004 ביצים \u0003הויין\u0004 \u0005[הריהן].\u0006 ונמצא שמדה זו אינה מתאימה אף לאחת ממדות הסאה!","ומשיבים: \u0003לעולם\u0004 סאה זו על פי מדה ה\u0003ציפורית\u0004 היתה, אלא \u0003אייתי חלתא שדי עלייהו\u0004 \u0005[הבא את\u0006 שיעור \u0005החלה\u0006 הניתנת לכהן \u0005והטל\u0006 הוסף \u0005עליהן],\u0006 שבמדה זו היתה כמות הקמח לאחר כל הניכויים סאה בדיוק.","\u0003ומקשים: חלתא\u0004 \u0005[החלה]\u0006 \u0003כמה\u0004 ביצים \u0003הויין\u0004 \u0005[הן]?\u0006 \u0003תמני\u0004 \u0005[שמונה]\u0006 ביצים בקירוב, אחד מעשרים וארבעה ממאה תשעים ושתים, אם כן \u0003אכתי בצר ליה\u0004 \u0005[עדיין חסר לו],\u0006 שגם אם נוסיף על מאתים ושבע עוד שמונה ביצים לחלה, נגיע רק למאתים וחמש עשרה (או אם נדקדק ונגיע עד למאתים ושש עשרה) ועדיין הוא פחות ממאתים ושבע עשרה אלו!","\u0003אלא אייתי ועודות דרבי שדי עלייהו\u0004 לא על פי חשבון החלה יש לחשוב, אלא ביצים אלה ששער בהן רבי את הסאה, ביצים עצבות (חסרות) היו, ולכן מוסיפים לכל ביצה כדי אחד מעשרים. נמצא שאחד מעשרים למאתים ושבע ביצים הוא עשר בערך, והמדה כולה היא כמאתים ושבע עשרה ביצים.","ומקשים: \u0003אי הכי, הוי ליה טפי\u0004 \u0005[אם כך, הרי הוא\u0006 מעט \u0005יותר]\u0006 מכדי שבעה חלקי עשרים של ביצה! ומשיבים: \u0003כיון\u0004 ש\u0003לא הוי\u0004 \u0005[שאינו]\u0006 \u0003כביצה\u0004 שלימה, \u0003לא חשיב ליה\u0004 \u0005[חושב אותו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003סאה ירושלמית יתירה\u0004 במידתה \u0003על\u0004 הסאה ה\u0003מדברית שתות\u0004 \u0005[ששית],\u0006 שהמדברית חמש שישיות ממנה. \u0003ושל ציפורית יתירה על ירושלמית שתות\u0004 \u0005[ששית].\u0006 \u0003נמצאת\u0004 סאה \u0003של ציפורית יתירה על מדברית שליש.\u0004","ותוהים: \u0003שליש דמאן\u0004 \u0005[של מי]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא \u0003שליש\u0004 של הסאה ה\u0003מדברית, מכדי\u0004 \u0005[והרי]\u0006 \u0003שליש\u0004 של \u0003מדברית כמה הוי\u0004 \u0005[הם],\u0006 \u0003ארבעין ותמניא\u0004 \u0005[ארבעים ושמונה\u0006 ביצים\u0005],\u0006 \u0003ואילו עודפא\u0004 \u0005[העודף,\u0006 ההבדל\u0005]\u0006 בין סאה מדברית וציפורית הוא \u0003שיתין ותלת\u0004 \u0005[ששים ושלוש\u0006 ביצים\u0005],\u0006 שהרי כאמור הציפורית היא בת מאתים ושבע ביצים, והמדברית של מאה ארבעים וארבע בלבד.","\u0003ואלא\u0004 תאמר \u0003שליש\u0004 סאה \u0003ירושלמית,\u0004 ונבדוק: \u0003שליש דידה\u0004 \u0005[שלה]\u0006 \u0003כמה הוי\u0004 \u0005[הוא],\u0006 \u0003חמשין ותמניא נכי תילתא\u0004 \u0005[חמישים ושמונה פחות שליש]\u0006 \u0003ואילו עודפא, שתין ותלת\u0004 \u0005[העודף, ששים ושלוש]\u0006. \u0003ואלא\u0004 תפרש שמדובר בשליש מסאת \u0003ציפורי; שליש דידה\u0004 \u0005[שלה]\u0006 \u0003כמה הוי\u0004 \u0005[הוא],\u0006 \u0003שבעין נכי חדא\u0004 \u0005[שבעים פחות אחד],\u0006 \u0003ואילו עודפא, שתין ותלת\u0004 \u0005[העודף, ששים ושלוש].\u0006 ונמצא שההפרש בין המדות איננו שליש מדויק מכל מידת סאה מוכרת.","\u0003אלא אמר ר' ירמיה, הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003נמצאת סאה של ציפורי יתירה על מדברית\u0004 ששים ושלוש ביצים שהן \u0003קרוב לשליש שלה\u0004 של סאה ציפורי (שהוא ששים ותשע ביצים). \u0003ושליש שלה\u0004 (ששים ותשע ביצים) \u0003קרוב למחצה\u0004 של \u0003מדברית\u0004 (שהוא שבעים ושתים ביצים).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: מידי\u0004 \u0005[וכי]\u0006 \u0003\"קרוב\" \"קרוב\" קתני\u0004 \u0005[שנינו]?\u0006 והרי מלשון הברייתא נראה שנאמרו הדברים בדיוק. \u0003אלא אמר רבינא: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]\u0006 \u0003נמצאת שליש של ציפורי בועודיות של רבי,\u0004 כלומר אם נוסיף על כל ביצה גם את התוספת שהוסיף רבי אחד מעשרים בביצה שהן ביחד מאתים ושבע עשרה ביצים, כאמור, הרי שליש סאה זו שהוא שבעים ושתים ביצים ושליש \u0003יתירה על מחצה של\u0004 סאה \u0003מדברית\u0004 רק \u0003שליש ביצה,\u0004 וכך יש להבין את דברי הברייתא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"ראשית עריסותיכם\u0004 חלה תרימו תרומה כתרומת גורן כן תרימו אותה \u0003\"(במדבר טו, כ).\u0004"],["\u0003כדי עיסותיכם, וכמה\u0004 הוא \u0003עיסותיכם\u0004 מה הוא השיעור של עיסה סתם? \u0003כדי עיסת המדבר. וכמה\u0004 היא \u0003עיסת המדבר?\u0004","נאמר כבר שהיה המן \"עומר לגולגולת\", ושיעורו של העומר נתפרש בכתוב: \u0003\"והעמר עשרית האפה הוא\"\u0004 (שמות טז, לו). וכיון שהאיפה היא שלוש סאים, שהן שמונה עשר קבים, שהם שבעים ושנים לוגים (רבעי הקב), והעומר הוא עשירית שיעור זה, \u0003מכאן אמרו,\u0004 לפי החשבון הזה, כי עיסה שיש בה \u0003שבעה רבעים\u0004 של קב \u0003קמח ועוד\u0004 משהו, עיסה כזו \u0003חייבת בחלה, שהן\u0004 שיעור \u0003ששה\u0004 רבעי קבים של מדה \u0003ירושלמית, שהן חמשה\u0004 רבעי קבים של מדת \u0003ציפורי.\u0004","\u0003מכאן אמרו: האוכל כמדה זו\u0004 ליום — \u0003הרי זה בריא\u0004 שמסוגל לאכול כמות זו \u0003ומבורך,\u0004 שאינו רעבתן וזקוק ליותר. \u0003יתר על כן\u0004 — הרי הוא \u0003רעבתן.\u0004 האוכל \u0003פחות מכאן\u0004 — הרי הוא \u0003מקולקל במעיו,\u0004 ועליו לדאוג לתיקון בריאותו.","\u0003אנשי חצר ואנשי מרפסת\u0004 שפתחי העליות פתוחים אליה \u0003ששכחו ולא עירבו\u0004 ביניהם, \u0003כל\u0004 דבר המצוי בחצר \u0003שגבוה עשרה טפחים\u0004 מקרקעה — שייך מבחינת היתר השימוש בו בשבת \u0003למרפסת,\u0004 ובני המרפסת רשאים ממקומם להשתמש בו. כל ה\u0003פחות מכאן\u0004 — \u0003לחצר.\u0004","וכן \u0003חוליית הבור\u0004 (האבן שמסביב לפתח הבור) \u0003והסלע,\u0004 אם היו \u0003גבוהים עשרה טפחים — למרפסת, פחות מכאן\u0004 — הרי הם \u0003ל\u0004שימושה של \u0003חצר.\u0004","\u0003במה דברים אמורים\u0004 שהגבוה עשרה טפחים למרפסת — כשהיתה המרפסת \u0003סמוכה, אבל ב\u0004מקרה שהיתה \u0003מופלגת\u0004 (מרוחקת) — \u0003אפילו\u0004 דבר ה\u0003גבוה עשרה טפחים\u0004 — שימושו \u0003לחצר. ואיזו היא סמוכה — כל שאינה רחוקה\u0004 ממנו \u0003ארבעה טפחים.\u0004","בקשר להלכות שבמשנתנו, באים לקבוע כללים למי מן הדיירים בבתים ובחצירות זכות השימוש בשבתות בחלקים שונים מן הבית או החצר. \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 כי אם מצוי מקום שלכל הדיירים יש גישה נוחה אליו, כמו \u0003לזה בפתח ולזה בפתח\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 כהלכה של \u0003חלון שבין שתי חצירות\u0004 האסור לשניהן אם לא עירבו.","מקום ששימושו הוא אינו נוח לשניהם, ואינו אלא באופן ש\u0003לזה בזריקה ולזה בזריקה — היינו\u0004 \u0005[זהו]\u0006 הדין של \u0003כותל שבין שתי חצירות.\u0004 ואילו מקום שאינו ניתן לשניהם לשימוש, אלא באופן ש\u0003לזה בשלשול\u0004 שמורידים חפצים לתוכו \u0003ולזה בשלשול — היינו\u0004 \u0005[זהו]\u0006 כדין \u0003חריץ שבין שתי חצירות,\u0004 שבכל אלה שנוחיות שימושם שוה לשתי חצירות, אם לא עירבו הרי שתיהן אסורות להשתמש שם.","וכן אם ניתן לשימוש רק באופן ש\u0003לזה בפתח ולזה בזריקה — היינו\u0004 \u0005[זהו]\u0006 כדינו של \u0003רבה בר רב הונא אמר רב נחמן\u0004 (לעיל עירובין עז,א), שלדעתו משתמש בו זה ששימושו על ידי הפתח. ואם שימושו הוא באופן ש\u0003לזה בפתח ולזה בשלשול — היינו\u0004 \u0005[זהו]\u0006 כדינו של \u0003רב שיזבי אמר רב נחמן\u0004 שזכות השימוש רק לחצר שנוח שימושה בו (בפתח).","עד כאן היו לנו הלכות מוסכמות, ואולם מה דין אם קיים מקום ש\u0003לזה\u0004 שימושו על ידי \u0003שלשול ולזה בזריקה,\u0004 שלשניהם אין השימוש בו נוח, וכגון שהוא גבוה מחצר אחת ונמוך מחצר אחרת \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006","\u0003אמר רב: שניהן אסורין\u0004 בו, שכיון שלשניהם קשה להשתמש בו, הריהם שוים כאחת בזכותם עליו, ואוסרים אלה על אלה. \u0003ושמואל אמר: נותנין אותו לזה ש\u0004משתמש \u0003בשלשול. ש\u0004כן \u0003לזה תשמישו בנחת,\u0004 שקל להוריד חפצים למטה. ואילו \u0003לזה\u0004 שצריך לזרוק על גביו, \u0003תשמישו בקשה, ו\u0004כלל הוא לענין שבת: \u0003כל דבר שתשמישו לזה בנחת ולזה בקשה — נותנים אותו לזה שתשמישו בנחת.\u0004","כדי להכריע במחלוקת זו מביאים ראיות ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אנשי חצר ואנשי מרפסת ששכחו ולא עירבו\u0004 ביניהם \u0003כל\u0004 דבר \u0003שגבוה עשרה טפחים\u0004 — שימושו \u0003למרפסת, פחות מכאן — לחצר,\u0004 ומסבירים תחילה:","\u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתך]\u0006 לומר \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003מרפסת\u0004 במשנתנו"],["\u0003בני עלייה\u0004 הגרים בקומה גבוהה למעלה מהמרפסת. \u0003ומאי קרו\u0004 \u0005[ומדוע קוראים]\u0006 \u0003לה מרפסת\u0004 לעליה? משום שבני העליה \u0003קסלקי\u0004 \u0005[עולים]\u0006 ויורדים \u0003במרפסת, אלמא\u0004 \u0005[מכאן נסיק]:\u0006 \u0003כל לזה בשלשול ולזה בזריקה — נותנים אותו לזה שבשלשול,\u0004 שהרי בני עלייה המשתמשים במקום הגבוה מעשרה משתמשים בו בשלשול. הרי שאם לזה בשלשול ולזה בזריקה, נותנים אותו לזה ששימושו בשלשול. וקשה לרב!","ודוחים: הכוונה \u0003כ\u0004מו ש\u0003אמר רב הונא\u0004 לענין אחר: \u0003לאותן הדרים במרפסת. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענייננו: \u0003לאותן הדרין במרפסת.\u0004 ונמצא שלבני המרפסת שימושו בנחת, שהרי הוא בשוה (בכעין פתח) לאותו מקום, ולבני החצר שימושו בקשה, וברור שיינתן לבני המרפסת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור את סוף\u0006 המשנה\u0005]:\u0006 היה העמוד \u0003פחות מכאן\u0004 מגובה עשרה — הריהו שייך \u0003לחצר. אמאי\u0004 \u0005[מדוע]\u0006 נאמר כן? הלוא \u0003לזה בפתח ולזה בפתח הוא!\u0004 שעדיין הוא נוח במדה שווה גם לבני מרפסת וגם לבני חצר, ומדוע יתנוהו לבני חצר לבדם?","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"לחצר\"\u0004 — הכוונה: \u0003אף לחצר,\u0004 שאף בני חצר יכולים להשתמש בעמוד זה. \u0003ו\u0004ממילא \u0003שניהן אסורין,\u0004 שמקום ששתי רשויות שלא עירבו יחד יכולות להשתמש בו, אסור על שתיהן עד שיערבו.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין את המשנה, \u0003מדקתני סיפא\u0004 \u0005[ממה ששנינו בסופה\u0006 של המשנה\u0005]:\u0006 \u0003במה דברים אמורים — בסמוכה. אבל במופלגת, אפילו גבוה עשרה טפחים\u0004 — שייך \u0003לחצר. מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"לחצר\"? אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003לחצר ושרי\u0004 \u0005[ומותר]\u0006 לבני החצר להשתמש בו, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלוא \u0003רשותא דתרוייהו\u0004 \u0005[רשות שניהם]\u0006 \u0003הוא\u0004 שעדיין הוא קרוב לבני המרפסת ויכולים אף הם להשתמש בו!","\u0003אלא\u0004 יש להבין \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לחצר\" — אף לחצר,\u0004 וממילא כיון ששתי רשויות ראויות להשתמש בו, \u0003ו\u0004ממילא \u0003שניהן אסורין. הכא נמי, מאי\u0004 \u0005[כאן גם כן\u0006 לעניננו, \u0005מה\u0006 משמעות\u0005]\u0006 \u0003\"לחצר\" — אף לחצר, ושניהן אסורין.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך יש להבין.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חוליית הבור והסלע שהן גבוהין עשרה\u0004 — נותנים אותם \u0003למרפסת, פחות מכאן — לחצר.\u0004 הרי שאף לבני העליה העוברים דרך המרפסת ששימושם קשה, מכל מקום נותנים אותו להם. ותירצו, \u0003אמר רב הונא:\u0004 \"מרפסת\" פירושה כמשמעה: \u0003לאותן הדרים במרפסת.\u0004","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 לגבי \u0003סלע,\u0004 הרי הם משתמשים בראש הסלע, ומניחים עליו דברים. ואולם \u0003בור מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 והרי המים שבבור עמוקים מן המרפסת, ואין שימושה בהם אלא בדרך שלשול, ומדוע נאמר כי הבור נוח לשימוש לבני מרפסת?","\u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: הכא\u0004 \u0005[כאן]\u0006 \u0003בבור מלאה מים עסקינן\u0004 \u0005[אנו עוסקים],\u0006 ואת המים דולים מחלקו העליון הסמוך לבני מרפסת. ומקשים: \u0003והא חסרא\u0004 \u0005[והרי חסר]\u0006 בור זה ממימיו עם השאיבה, ואף שמתחילה מי הבור מגיעים סמוך למרפסת, לאחר מכן גדל המרחק!","ומשיבים: \u0003כיון דכי מליא שריא, כי חסרא\u0004 \u0005[שכאשר\u0006 הבור \u0005מלא\u0006 הוא \u0005מותר, כאשר\u0006 הוא \u0005חסר —\u0006 \u0003נמי שריא\u0004 \u0005[גם כן מותר].\u0006 ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003כיון דכי חסרה, אסירא\u0004 \u0005[שכאשר חסר\u0006 הבור, הוא \u0005אסור].\u0006 \u0003כי מליא, נמי אסירא\u0004 \u0005[כאשר\u0006 הוא \u0005מלא, גם כן\u0006 הוא \u0005אסור].\u0006","\u0003אלא אמר אביי: הכא\u0004 \u0005[כאן]\u0006 \u0003בבור מליאה פירות עסקינן\u0004 \u0005[אנו עוסקים],\u0006 שהפירות העליונים שבבור סמוכים למרפסת. ומקשים: \u0003והא חסרי\u0004 \u0005[והרי חסרים\u0006 הפירות\u0005],\u0006 שהרי גם הפירות כאשר משתמשים בהם, מתמעטים ומתרחקים מן המרפסת.","ומשיבים: מדובר כאן \u0003בטיבלא\u0004 \u0005[בטבל],\u0006 שהיו הפירות טבל (בלתי מעושרים), ואסור לתקן (להפריש מעשר) מטבל בשבת. וכיון שאי אפשר להשתמש בהם, גובהם קבוע ועומד במשך השבת.","ומעירים: \u0003דיקא נמי\u0004 \u0005[\u0006כך \u0005גם כן מדויק]\u0006 להבין מלשון המשנה \u0003דקתני דומיא\u0004 \u0005[ששנינו\u0006 חוליית הבור \u0005בדומה]\u0006 ל\u0003סלע,\u0004 כשם שסלע אין משתמשים אלא על גביו, אף חוליית הבור הכוונה היתה לשימוש שעל גבה, ולא לשימוש במצוי בבור. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003ו\u0004שואלים: אם כן שמדובר במקרה כזה, \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003בור ולמה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003סלע\u0004 אם עניינם שווה בכול? ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005],\u0006 \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 \u0003סלע\u0004 בלבד, היינו אומרים: שדוקא בסלע מותר לבני החצר להשתמש משום \u0003דליכא למיגזר\u0004 \u0005[שאין מקום לגזור\u0006 בו\u0005]\u0006 שמא יתמעט מגובהו, \u0003אבל בור — ליגזור\u0004 \u0005[שיגזור\u0006 בו\u0005]\u0006 שיהא אסור להשתמש בו משום \u0003זימנין דמליא\u0004 \u0005[פעמים ש\u0006הוא \u0005מלא]\u0006 \u0003פירות מתוקנין,\u0004 שאפשר לקחת ולהשתמש בהם ויתמעטו, ועל כן \u0003צריכא\u0004 \u0005[צריך]\u0006 היה לומר גם דבר זה.","ולענין מחלוקת רב ושמואל מנסים להביא ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון, כי נאמר בברייתא: \u0003אנשי חצר ואנשי עלייה ששכחו ולא עירבו\u0004 ביניהם — \u0003אנשי חצר משתמשין בעשרה\u0004 הטפחים \u0003התחתונים\u0004 של הכותל הסמוכים להם, \u0003ואנשי עלייה משתמשין בעשרה\u0004 טפחים \u0003העליונים\u0004 הסמוכים להם. ו\u0003כיצד?\u0004 אם היה \u0003זיז יוצא מן הכותל למטה מעשרה\u0004 — \u0003ל\u0004בני \u0003חצר\u0004 הוא משמש, \u0003למעלה מעשרה\u0004 טפחים — משמש \u0003ל\u0004בני ה\u0003עלייה.\u0004","ומדייקים: \u0003הא דביני ביני\u0004 \u0005[הרי\u0006 זיז שנמצא \u0005בין\u0006 זה \u0005לבין\u0006 זה, באמצע\u0005] —\u0006 \u0003אסור,\u0004 והרי המקום שבאמצע נחשב כ\"לזה בשלשול ולזה בזריקה\", ומכאן שכל שהוא לזה בשלשול ולזה בזריקה שניהם אסורים, וכדברי רב!","\u0003אמר רב נחמן:\u0004 אין להוכיח מכאן, שכן \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בכותל\u0004 בן \u0003תשעה עשר\u0004 טפחים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ו\u0004היה \u0003זיז יוצא ממנו.\u0004 אם היה הזיז \u0003למטה מעשרה\u0004 — הרי \u0003לזה\u0004 לבני החצר הוא \u0003בפתח\u0004 בנוחיות, \u0003ולזה\u0004 לבני העלייה \u0003בשלשול.\u0004 אם היה \u0003למעלה מעשרה\u0004 — \u0003לזה\u0004 לבני העליה הוא \u0003בפתח, ולזה\u0004 לבני החצר הוא \u0003בזריקה.\u0004 אבל אין כאן מקום באמצע, ואין ללמוד מכאן לענייננו."],["\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 הוכחה למחלוקת רב ושמואל ממשנה אחרת: \u0003שתי גזוזטראות זו למעלה מזו\u0004 שהיו מצויות מעל לים. ו\u0003עשו\u0004 תיקון \u0003לעליונה\u0004 על ידי מחיצות סביב לה, שיהא מותר לשאוב מן הים לתוכה דרך נקב שעשו במרכזה שממנו שלשלו את הדלי לים. \u0003ולא עשו לתחתונה — שתיהן אסורות עד שיערבו\u0004 ביניהן. ולכאורה מדובר כאן שבני העליונה שואבים מים על ידי שלשול דלי לתוכה, ובני התחתונה זורקים את דלים לעליונה ושואבים באופן זה. ונמצא כי השימוש הוא לזו בשלשול ולזו בזריקה, ונאמר כי שתיהן אסורות, וכדברי רב, וקשה לשמואל!","\u0003אמר רב אדא בר אהבה:\u0004 מדובר כאן \u0003בבאין בני\u0004 הגזוזטרא ה\u0003תחתונה\u0004 ועולים בסולם \u0003דרך\u0004 ה\u0003עליונה למלאות\u0004 להם מים, שהם עצמם מצויים בשעת השאיבה בגזוזטרא העליונה, ושניהם בשלשול.","\u0003אביי אמר: כגון דקיימין\u0004 \u0005[שעומדות,\u0006 שמצויות\u0005]\u0006 שתי הגזוזטראות \u0003בתוך עשרה\u0004 טפחים \u0003דהדדי\u0004 \u0005[זו לזו],\u0006 \u0003ו\u0004בסגנון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר].\u0006 ולפי סגנון זה נבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם \u0003עשו לתחתונה\u0004 תיקון זה \u0003ולא עשו לעליונה, דאסירי\u0004 \u0005[שאסורות]\u0006 ש\u0003כיון דבגו\u0004 \u0005[שבתוך]\u0006 \u0003עשרה דהדדי קיימין\u0004 \u0005[זו מזו\u0006 הן \u0005עומדות] —\u0006 \u0003אסרן אהדדי\u0004 \u0005[אוסרות זו על זו]\u0006","\u0003אלא אפילו עשו\u0004 תיקון לגזוזטרא \u0003עליונה ולא עשו לתחתונה, סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון\u0004 ש\u0003לזה\u0004 העליונה שימוש השאיבה \u0003בנחת, ולזה בקשה\u0004 שהרי התחתונה צריכה להשליך דלי כלפי מעלה, ורק בדרך זו יכולה היא לשאוב — \u0003ליתביה\u0004 \u0005[שיתן]\u0006 \u0003לזה שתשמישו בנחת\u0004 ותהא העליונה מותרת והתחתונה אסורה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003כיון דבגו\u0004 \u0005[שבתוך]\u0006 \u0003עשרה\u0004 טפחים \u0003קיימין\u0004 \u0005[\u0006הם \u0005מצויים] —\u0006 \u0003אסרן אהדדי\u0004 \u0005[אוסרים\u0006 הם \u0005זה על זה],\u0006","\u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב נחמן אמר שמואל: גג\u0004 נמוך שהיה \u0003סמוך לרשות הרבים\u0004 והיתה מרפסת סמוכה לו — \u0003צריך\u0004 שיהא \u0003סולם קבוע\u0004 המוליך מן הקומה השניה אליו כדי \u0003להתירו\u0004 לבן המרפסת להשתמש בגג. שנעשה הסולם גשר קבוע בין המרפסת והגג, ומפקיע את השימוש מן הגג לרשות הרבים. ונדקדק: \u0003סולם קבוע — אין\u0004 \u0005[כן],\u0006 \u0003סולם עראי — לא, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003כיון\u0004 ש\u0003בתוך עשרה\u0004 טפחים \u0003דהדדי קיימי\u0004 \u0005[של זה מזה\u0006 הם \u0005מצויים] —\u0006 \u0003אסרן אהדדי\u0004 \u0005[אוסרים\u0006 הם \u0005זה על זה].\u0006 שכיון שבני המרפסת מצויים בתוך עשרה לרשות הרבים, הרי הם אוסרים את השימוש בה לבני הקומה השניה. ואין אפשרות לעלות ממנה לגג, ואין תקנה אלא בסולם קבע שדינו כפתח ממש.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 הרי אפשר לדחות את הראיה, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 מדובר כאן בגג כזה \u0003שרבים מכתפין עליו\u0004 (מניחים עליו את משאם), כגון \u0003בכומתא וסודרא\u0004 \u0005[כובע וסודר]\u0006 שמניחים לפי שעה כשרוצים לנוח מעט. וכיון שנעשה גג זה גם שימוש לרבים, הרי אם לא יהיה לו תיקון בסולם קבוע, לא יותר לבני הקומה העליונה להשתמש בו, שהרי הוא משמש גם לבני רשות הרבים. אבל אין לכך כל קשר עם היות בני המרפסת סמוכים בתוך עשרה טפחים. ואם כן אין להוכיח מכאן. ולא מצאנו ראיה מכרעת לא לשיטת רב ולא לשיטת שמואל.","\u0003אמר רב יהודה אמר שמואל:\u0004"],["\u0003בור\u0004 שנמצא בסמטא קטנה \u0003שבין שתי חצירות, מופלגת מכותל זה ארבעה ומכותל זה ארבעה — זה\u0004 הדר בחצר אחת \u0003מוציא זיז כל שהוא\u0004 לעבר הבור, להיכר שאינו משתמש ברשות של אחר, \u0003וממלא\u0004 דרך חלונות. \u0003וזה מוציא זיז כל שהוא, וממלא. ורב יהודה דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר:\u0004 אין צורך בזיז ממש אלא \u0003אפילו\u0004 מוציא \u0003קניא\u0004 \u0005[קנה]\u0006 בלבד דיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב יהודה\u0004 שצריך לעשות תיקון כלשהו כשיטת \u0003שמואל\u0004 רבו \u0003היא, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רב\u0004 רבו האחר הוא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר: אין אדם אוסר על חבירו דרך אויר,\u0004 ולשיטתו אף קנה אינו צריך.","ושואלים: \u0003ו\u0004שזו דעת \u0003שמואל מהיכא\u0004 \u0005[מהיכן]\u0006 למדנו? \u0003אילימא מהא\u0004 \u0005[אם תאמר מזו]\u0006 ש\u0003אמר רב נחמן אמר שמואל: גג הסמוך לרשות הרבים — צריך סולם קבוע להתירו,\u0004 ונלמד מכאן שבני רשות הרבים אוסרים בגג משום שימושם בו דרך אויר בזריקה. ואולם אין מכאן ראיה כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003כרב פפא\u0004 יש להבין את הענין שיש להם בו שימוש קבוע על ידי הנחת כומתא וסודרא, ולפיכך אינו נוגע כלל לשימוש דרך אויר!","\u0003אלא מהא\u0004 \u0005[מ\u0006דבר \u0005זה]\u0006 נלמד לשיטת שמואל, שאמרנו \u0003זה מוציא זיז כל שהוא וממלא, וזה מוציא זיז כל שהוא וממלא. טעמא דאפיק\u0004 \u0005[הטעם,\u0006 דוקא\u0005, שהוציא]\u0006 זיז, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אפיק\u0004 \u0005[הוציא] —\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003אדם אוסר על חבירו דרך אויר,\u0004 ויאסר לו לשאוב מים מפני חבירו שאף הוא סמוך לבור זה דרך אויר.","ושואלים: \u0003ו\u0004שיטתו של \u0003רב מהיכא\u0004 \u0005[מהיכן]\u0006 למדנו שאין אדם אוסר על חבירו דרך אויר? \u0003אילימא מהא\u0004 \u0005[אם תאמר מ\u0006הלכה \u0005זו]\u0006 ששנינו: היו \u0003שתי גזוזטראות\u0004 הבנויות מעל הים \u0003זו למעלה מזו, עשו מחיצה לעליונה ולא עשו מחיצה לתחתונה — שתיהן אסורות עד שיערבו\u0004 ביניהן.","\u0003ואמר רב הונא אמר רב: לא שנו\u0004 שהאחת אוסרת על חברתה \u0003אלא בסמוכה, אבל\u0004 אם היתה גזוזטרא אחת \u0003מופלגת\u0004 (מרוחקת) \u0003ארבעה\u0004 טפחים מחברתה, והשימוש בה דרך אויר בלבד — \u0003עליונה מותרת ותחתונה אסורה.\u0004","ואולם מכאן אין להוכיח, כי \u0003דילמא שאני הכא\u0004 \u0005[שמא שונה כאן]\u0006 ש\u0003כיון\u0004 ש\u0003לזה בזריקה ושלשול,\u0004 שהרי מגזוזטרא תחתונה מוכרחים הם לזרוק את הדלי אל העליונה ואחר כך לשלשל את הדלי משם כדי לשאוב מים. \u0003ולזה,\u0004 לבני גזוזטרא עליונה, \u0003בשלשול לחודיה\u0004 \u0005[לבדו]\u0006 יכולים לשאוב, הרי \u0003כלזה בזריקה ולזה בפתח דמי\u0004 \u0005[נחשב],\u0006 שהרי לעליונה קל יחסית השימוש במים. ולכן במקרה מיוחד זה אינם אוסרים דרך אויר.","\u0003אלא מהא\u0004 \u0005[מ\u0006דבר \u0005זה]\u0006 נוכל להביא ראיה מהו מקור שיטת רב ש\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב:\u0004 היו \u0003שני בתים ושלש חורבות ביניהם,\u0004 וחורבות אלה אין להן בעלים אחרים אלא בעלי בתים אלה. \u0003זה,\u0004 אדם הגר בבית אחד, \u0003משתמש\u0004 בחורבה \u0003בסמוך שלו על ידי זריקה\u0004 לתוך החורבה דרך חלונותיו, \u0003וזה משתמש בסמוך שלו על ידי זריקה\u0004 דרך חלונותיו,"],["\u0003והאמצעי — אסור\u0004 לשניהם.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב ברונא וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 בשם רב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר בר בי\u0004 \u0005[בן בית\u0006 המדרש\u0005]\u0006 של \u0003רב:\u0004 האם \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אמר לו: \u0003אחוי\u0004 \u0005[הראה]\u0006 \u0003לי\u0004 את \u0003אושפיזיה\u0004 \u0005[מקום דירתו].\u0006 \u0003אחוי ליה\u0004 \u0005[הראה לו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003אמר מר הכי\u0004 \u0005[אדוני כן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מר\u0004 \u0005[אדוני]\u0006 \u0003הוא\u0004 זה ש\u0003אמר: לזה בשלשול ולזה בזריקה — שניהן אסורין!\u0004 ומדוע לא תאסור גם בשתי החורבות הסמוכות, שאף בהן אין השימוש נוח?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת דקיימי\u0004 \u0005[האם סבור אתה ש\u0006היו שלוש החורבות \u0005עומדות]\u0006 זו ליד זו \u0003כשורה\u0004 אחת? \u0003לא — דקיימי\u0004 \u0005[ש\u0006היו \u0005עומדות]\u0006 \u0003כחצובה,\u0004 כלומר, שתי החורבות הסמוכות צמודות זו לזו, והשלישית נמצאת בצידן. ששתי החורבות משמשות בנוחות לבעלי הבתים הסמוכים להן, והרי כל אחת מהן כפתח לאחד וזריקה לאחר. וחורבה אמצעית קשה שימושה לשניהם בשוה, ומשום כך נאסרת על שניהם. ומתוך שהסמוכות מותרות לבית הסמוך להן, למדנו את שיטת רב שאין אדם אוסר על חבירו דרך אויר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003שמואל\u0004 שלדעתו אוסר אדם דרך אויר \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל] את שיטת \u0003רב דימי.\u0004 שכן, \u0003דכי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מקום\u0004 בין רשות הרבים לרשות היחיד \u0003שאין בו ארבע על ארבע\u0004 טפחים ואינו אלא כאויר — \u0003מותר לבני רשות הרבים ולבני רשות היחיד לכתף עליו, ובלבד שלא יחליפו\u0004 חפצים ביניהם.","ולשיטת שמואל צריך היה לאסור משום אויר של רשות אחרת, וענה לו רבא: \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' יוחנן — \u0003ברשויות דאורייתא\u0004 \u0005[שמן התורה]\u0006 שהיו מצויות משני צידי מקום פטור, ולא גזרו ואסרו משום אויר. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 באויר שבין שני רשות היחיד — \u0003ברשויות דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 שהרי איסור טלטול שבין רשות היחיד אחת לחבירתה אינו אלא מדבריהם. \u0003וחכמים עשו חזוק לדבריהם יותר משל\u0004 דברי \u0003תורה\u0004 כדי שיתקיימו, ולכן אמרו, כדברי שמואל, שאדם אוסר על חבירו דרך אויר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: מי\u0004 \u0005[האם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כן]\u0006 \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בבעיה זו, \u0003שני בתים\u0004 שהיו \u0003משני צידי רשות הרבים,\u0004 והיו שייכים לאדם אחד, \u0003רבה בר רב הונא אמר רב: אסור לזרוק מזה לזה, ושמואל אמר: מותר לזרוק מזה לזה!\u0004 ואם כן לכאורה נראה שמה שרב אוסר לזרוק הוא משום אויר אסור של רשות הרבים שבאמצע.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו מי אוקימנא דמדלי חד ומתתי חד\u0004 \u0005[האם לא העמדנו,\u0006 הסברנו, את הדבר \u0005ש\u0006היה בית \u0005אחד מוגבה\u0006 יותר \u0005ואחד נמוך\u0006 יותר\u0005],\u0006 ולא אסר רב משום אויר רשות הרבים, אלא טעם הדבר משום הקושי שבזריקה מן הנמוך לגבוה, ו\u0003זימנין דמגנדר ונפיל, ואתי לאיתויי\u0004 \u0005[פעמים שמתגלגל ונופל\u0006 לרשות הרבים, \u0005ויבואו להרימו]\u0006 ויכניסנו מרשות הרבים לרשות היחיד, ומשום טעם זה גזר רב.","\u0003הנותן את עירובו\u0004 (עירוב חצירות) \u0003בבית שער\u0004 שהוא כעין חדר קטן הנמצא מסביב לשער, או ב\u0003אכסדרא\u0004 שהיא כעין מרפסת מקורה שבפתח הבית, או \u0003מרפסת — אינו עירוב. והדר שם\u0004 באחד מכל אלה — \u0003אינו אוסר עליו\u0004 על הדר בבית ואינו נחשב כדייר נוסף בחצר.","המניח את עירובו ב\u0003בית התבן ו\u0004כן ב\u0003בית הבקר ו\u0004כן ב\u0003בית העצים ו\u0004כן ב\u0003בית האוצרות\u0004 — \u0003הרי זה עירוב\u0004 שהוא מקום הנשמר, \u0003והדר שם\u0004 ברשות — \u0003אוסר\u0004 על בעל הבית. \u0003ר' יהודה אומר: אם יש שם\u0004 בביתו של הדייר \u0003תפיסת יד של בעל הבית,\u0004 שיש לו חפצים שם ורשות שימוש מסויימת באותו בית — הרי זה כאילו היה עדיין הבית שלו, והדייר \u0003אינו אוסר\u0004 על בעל הבית.","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת: כל מקום שאמרו\u0004 ש\u0003הדר שם אינו אוסר,\u0004 גם \u0003הנותן את עירובו\u0004 שם \u0003אינו עירוב. חוץ מבית שער\u0004 של \u0003יחיד,\u0004 חדר המשמש מקום מעבר רק לאדם יחיד שהחצר שייכת רק לו, הדר שם אינו אוסר והנותן בו עירובו הריהו עירוב. \u0003וכל מקום שאמרו חכמים\u0004 ש\u0003אין מניחים בו עירוב\u0004 חצירות, \u0003מניחים בו שיתוף\u0004 מבואות. \u0003חוץ מאויר\u0004 (חלל) ה\u0003מבוי\u0004 שלא בתוך החצירות.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 בכך\u0005]?\u0006 והלוא \u0003תנינא\u0004 \u0005[שנינו\u0006 דברים אלו\u0005]:\u0006 \u0003הנותן את עירובו בבית שער אכסדרה\u0004 או \u0003מרפסת — אינו עירוב.\u0004 ונדייק: \u0003עירוב הוא דלא הוי\u0004 \u0005[שאיננו],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שיתוף הוי\u0004 \u0005[יהיה]!\u0006 אם כן מה חידש בדבריו?","ומשיבים: \u0003בית שער\u0004 של \u0003יחיד ואויר\u0004 של \u0003מבוי איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לומר, שכן אותם \u0003לא תנן\u0004 \u0005[שנינו]\u0006 כלל. וכן \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 בברייתא\u0005]:\u0006 \u0003הנותן את עירובו בבית שער אכסדרא\u0004 או \u0003מרפסת, ובחצר ובמבוי — הרי זה עירוב.\u0004 ויש להקשות: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין זה עירוב!\u0004 אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003הרי זה שיתוף.\u0004","ומקשים: אם ישים את מזון \u0003השיתוף במבוי\u0004 עצמו, הרי \u0003לא מינטר\u0004 \u0005[נשמר],\u0006 ושיתוף שישימו בו הרי זה כאילו לא הניחוהו כלל. אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שמדובר שהניחוהו \u0003בחצר שבמבוי.\u0004","\u0003אמר רב יהודה אמר שמואל: בני חבורה שהיו מסובין\u0004 לסעודה \u0003וקדש עליהן היום\u0004 (השבת), \u0003פת ש\u0004היתה \u0003על השלחן סומכין עליהן משום עירוב\u0004 ומותרים כולם לטלטל בחצר. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שסומכים על הפת \u0003משום שיתוף.\u0004","\u0003אמר רבה: ולא פליגי\u0004 \u0005[נחלקו]\u0006 שתי הלשונות בהלכה, אלא \u0003כאן\u0004 שסומכים משום עירוב — מדובר כשהיו \u0003מסובין בבית,\u0004 ופת שבבית מועילה לעירוב. \u0003כאן\u0004 — שהיו \u0003מסובין בחצר,\u0004 אינם יכולים לסמוך משום עירוב, אלא משום שיתוף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת]\u0006 \u0003לך\u0004 לשיטתך, ששנינו: \u0003עירובי חצרות בחצר, ושיתופי מבואות במבוי, והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בבעיה זו, כיצד אפשר לומר \u0003עירובי חצרות בחצר? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003הנותן את עירובו בבית שער אכסדרה ומרפסת אינו עירוב,\u0004 וכל שכן שאין להניחו בחלל החצר! אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך: \u0003עירובי חצרות\u0004 — מניחים \u0003בבית\u0004 שבאותה \u0003חצר, שיתופי מבואות\u0004 — די שמניחים אותה \u0003בחצר\u0004 שבאותו \u0003מבוי.\u0004","שנינו במשנה: \u0003ר' יהודה אומר\u0004 כי \u0003אם יש שם תפיסת יד\u0004 של בעל הבית במקום, שוב אין הדייר אוסר. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003תפיסת יד?\u0004 ומשיבים: \u0003כגון חצרו של\u0004 אותו אדם הנקרא \u0003בונייס\u0004 שהיה עשיר ביותר, והיו בחצרו דיירים שונים שדרו שם ברשותו. וכיון שהיו חפציו מרובים, היו לו חפצים אף באותן דירות שדרו בהן אחרים. וכיון שמותר לו לקחת את חפציו משם, הריהו נחשב כבעל הבית בכל הדירות כולן.","וכיון שהוזכר בונייס ועושרו מספרים מעשה הקשור בו: \u0003בן בונייס אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבי, אמר להו\u0004 \u0005[להם]\u0006 רבי לעומדים לפניו כשהכיר בו לפי לבושיו שהוא עשיר: \u0003פנו מקום לבן מאה מנה,\u0004 שראוי אדם כזה שיתנו לו כבוד לפי ערך עשרו. אחר כך \u0003אתא איניש אחרינא\u0004 \u0005[בא אדם אחר],\u0006 \u0003אמר\u0004 רבי לתלמידיו:"]]};
